function adaptScriptToDuration(items, totalSeconds, pace = 'standard', nh = null) {
  if (!items || items.length === 0) return [];
  const dur = Math.max(10, Math.min(300, parseInt(totalSeconds, 10) || 60));
  let adjustedItems = [];

  // Determine target scene count based on duration
  let targetCount = 6;
  if (dur <= 18) targetCount = 3;
  else if (dur <= 28) targetCount = 4;
  else if (dur <= 40) targetCount = 4;
  else if (dur <= 52) targetCount = 5;
  else if (dur <= 68) targetCount = Math.min(items.length, 7);
  else if (dur <= 85) targetCount = 7;
  else if (dur <= 105) targetCount = 8;
  else if (dur <= 135) targetCount = 10;
  else if (dur <= 165) targetCount = 12;
  else if (dur <= 210) targetCount = 14;
  else targetCount = 16;

  if (targetCount === 3) {
    // 3 scenes: Hook -> Core Highlights -> CTA
    adjustedItems = [
      items[0],
      {
        scene: items[1] ? items[1].scene : 'Toàn cảnh ngôi nhà và điểm bán cốt lõi',
        vo: (items[1] ? items[1].vo : '') + ' / ' + (items[3] ? items[3].vo : (items[2] ? items[2].vo : '')),
        text: (items[1] ? items[1].text : 'ĐIỂM NỔI BẬT')
      },
      items[items.length - 1]
    ];
  } else if (targetCount === 4) {
    adjustedItems = [
      items[0],
      items[1] || items[0],
      items[Math.floor(items.length / 2)] || items[1],
      items[items.length - 1]
    ];
  } else if (targetCount === 5) {
    if (items.length >= 6) {
      adjustedItems = [items[0], items[1], items[3], items[items.length - 2], items[items.length - 1]];
    } else {
      adjustedItems = [...items];
    }
  } else if (targetCount <= items.length) {
    adjustedItems = items.slice(0, targetCount);
    // ensure last is CTA
    adjustedItems[adjustedItems.length - 1] = items[items.length - 1];
  } else {
    // Expand scenes
    adjustedItems = [...items];
    const needed = targetCount - adjustedItems.length;
    const newHousePool = [];
    if (nh) {
      if (nh.hasElevator) {
        newHousePool.push({
          scene: 'Camera cận cảnh bảng điều khiển thang máy và nội thất cabin sang trọng',
          vo: `Trang bị ${nh.elevatorType || 'thang máy hiện đại'}, người lớn tuổi và trẻ nhỏ di chuyển lên xuống nhẹ nhàng, tiện lợi tối đa.`,
          text: 'THANG MÁY ÊM ÁI'
        });
      }
      if (nh.hasBathtub) {
        newHousePool.push({
          scene: 'Camera lia không gian phòng tắm Master với bồn tắm nằm cao cấp view chill',
          vo: 'Bồn tắm nằm ngâm mình thư giãn sau ngày dài làm việc, tận hưởng chuẩn phong cách resort nghỉ dưỡng ngay tại nhà.',
          text: 'BỒN TẮM NẰM CHILL'
        });
      }
      if (nh.hasSmartHome || nh.hasSmartLock) {
        newHousePool.push({
          scene: 'Chuyên viên thao tác mở cửa khóa vân tay và điều khiển ngữ cảnh đèn trên smartphone',
          vo: 'Hệ thống Smart Home thông minh kết hợp khóa từ vân tay, an ninh đa lớp và điều khiển tiện lợi chỉ bằng một chạm.',
          text: 'SMART HOME TIỆN NGHI'
        });
      }
      if (nh.hasSkyGarden) {
        newHousePool.push({
          scene: 'Góc flycam nhìn bao quát khu vườn sân thượng sky garden đón gió mát hoàng hôn',
          vo: 'Sân thượng xanh mát, không gian thưởng trà sáng và tổ chức BBQ tiệc rượu ngắm pháo hoa lung linh cùng bạn bè.',
          text: 'SKY GARDEN VIEW TRIỆU ĐÔ'
        });
      }
      if (nh.hasIndependentWall) {
        newHousePool.push({
          scene: 'Quay chi tiết tường riêng cột móng độc lập, khe hở kỹ thuật chuẩn chỉ',
          vo: 'Kết cấu chuẩn mực với tường riêng, móng riêng, cột riêng biệt, cách âm hoàn hảo và an tâm tuyệt đối về chất lượng xây dựng.',
          text: 'TƯỜNG RIÊNG • MÓNG RIÊNG'
        });
      }
      if (nh.hasWarranty) {
        newHousePool.push({
          scene: 'Tập hồ sơ hoàn công và sổ bảo hành kết cấu công trình chính hãng từ chủ đầu tư',
          vo: 'Chủ nhà cam kết bảo hành kết cấu dài hạn, bàn giao đầy đủ hồ sơ thiết kế và nghiệm thu xây dựng minh bạch.',
          text: 'BẢO HÀNH CÔNG TRÌNH'
        });
      }
    }
    const pool = [...newHousePool, ...EXPANSION_SCENES_POOL];
    for (let i = 0; i < needed && pool.length > 0; i++) {
      const insertPos = Math.min(adjustedItems.length - 1, 2 + i * 2);
      adjustedItems.splice(insertPos, 0, pool[i % pool.length]);
    }
  }

  // Ensure last item is always CTA
  if (items.length > 0 && adjustedItems[adjustedItems.length - 1] !== items[items.length - 1]) {
    adjustedItems[adjustedItems.length - 1] = items[items.length - 1];
  }

  const count = adjustedItems.length;

  // Calculate timing per scene with golden ratio
  let hookSec = Math.max(3, Math.min(Math.round(dur * 0.12), 7));
  let ctaSec = Math.max(4, Math.min(Math.round(dur * 0.14), 8));
  if (count <= 3) {
    hookSec = Math.max(3, Math.round(dur * 0.25));
    ctaSec = Math.max(3, Math.round(dur * 0.28));
  }

  const remainingSec = dur - hookSec - ctaSec;
  const middleCount = count - 2;
  const middleSecPerScene = middleCount > 0 ? remainingSec / middleCount : 0;

  let currentStart = 0;
  return adjustedItems.map((item, index) => {
    let sceneDuration;
    if (index === 0) {
      sceneDuration = count === 1 ? dur : hookSec;
    } else if (index === count - 1) {
      sceneDuration = dur - currentStart;
    } else {
      sceneDuration = middleSecPerScene;
    }

    const startSec = Math.round(currentStart);
    currentStart += sceneDuration;
    const endSec = index === count - 1 ? dur : Math.round(currentStart);
    const timeRangeStr = `${formatTime(startSec)}–${formatTime(endSec)}`;

    return {
      ...item,
      timeRange: timeRangeStr,
      startSec,
      endSec,
      sceneDurationSec: endSec - startSec
    };
  });
}

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
}

function getPaceLabel(pace) {
  if (pace === 'fast') return '⚡ Nhanh (FOMO)';
  if (pace === 'relaxed') return '☕ Thong thả';
  return '⚖️ Tiêu chuẩn';
}

function getRecommendedPlatform(duration) {
  if (duration <= 25) return 'TikTok Hook, Story, Reels Teaser';
  if (duration <= 45) return 'Facebook Reels, TikTok ngắn, Shorts';
  if (duration <= 65) return 'TikTok, Reels, Shorts (Chuẩn vàng)';
  if (duration <= 95) return 'Facebook Watch, TikTok dài, Zalo';
  if (duration <= 135) return 'Review chi tiết: FB Post, YouTube';
  return 'Tour nhà chuyên sâu: YouTube, Fanpage BĐS';
}

function estimateWordCount(duration, pace = 'standard') {
  const rate = pace === 'fast' ? 3.0 : pace === 'relaxed' ? 2.0 : 2.5;
  const minWords = Math.round(duration * (rate - 0.2));
  const maxWords = Math.round(duration * (rate + 0.2));
  return `~${minWords}–${maxWords} từ`;
}

function estimateSceneCount(duration) {
  if (duration <= 18) return 3;
  if (duration <= 40) return 4;
  if (duration <= 52) return 5;
  if (duration <= 68) return 6;
  if (duration <= 85) return 7;
  if (duration <= 105) return 8;
  if (duration <= 135) return 10;
  if (duration <= 165) return 12;
  if (duration <= 210) return 14;
  return 16;
}

// ==========================================
// 10. SHOT LIST, VO, TEXT, CTA (Section 17-20)
// ==========================================

function generateShotList(scriptItems) {
  return scriptItems.map((item, index) => ({
    shotNumber: `SHOT ${(index + 1).toString().padStart(2, '0')}`,
    timing: item.timeRange,
    description: item.scene,
    equipmentNote: index === 0 ? 'Gimbal / Cận cảnh' : index === 1 ? 'Góc rộng / Flycam' : 'Gimbal di chuyển mượt'
  }));
}

function generateVoiceover(scriptItems) {
  return scriptItems.map(item => item.vo).join('\n\n');
}

function generateOnScreenText(scriptItems) {
  return scriptItems.map(item => item.text);
}

function generateCTA(prop) {
  const street = (prop.location.street || 'căn này').toUpperCase();
  const nh = prop.newHouseFeatures || {};

  if (nh.isNew100 || nh.handover === 'full_interior') {
    return {
      primary: `Nhà mới 100% xách vali vào ở ngay / nhắn ${street} để xem nhà thực tế ngay hôm nay.`,
      alternatives: [
        `Muốn nhận trọn bộ bản vẽ kiến trúc & sổ hồng / nhắn XEM BẢN VẼ.`,
        `Cần thương lượng giá tốt trực tiếp chủ nhà / nhắn GIÁ TỐT.`
      ]
    };
  }

  return {
    primary: `Quan tâm căn này / nhắn ${street} để nhận hồ sơ chi tiết.`,
    alternatives: [
      `Muốn đi xem thực tế / nhắn XEM NHÀ.`,
      `Cần kiểm tra pháp lý và thương lượng / nhắn GIÁ.`
    ]
  };
}

// ==========================================
// 11. MANUAL INPUT FORM HANDLERS (NEW TAB)
// ==========================================

/**
 * Switch input mode tabs: 'raw' or 'manual'
 */
function switchInputTab(tabName) {
  AppState.currentInputTab = tabName;

  const btnRaw = document.getElementById('btnTabRaw');
  const btnManual = document.getElementById('btnTabManual');
  const paneRaw = document.getElementById('tabPaneRaw');
  const paneManual = document.getElementById('tabPaneManual');

  if (tabName === 'raw') {
    btnRaw.classList.add('active');
    btnManual.classList.remove('active');
    paneRaw.classList.add('active');
    paneManual.classList.remove('active');
  } else {
    btnManual.classList.add('active');
    btnRaw.classList.remove('active');
    paneManual.classList.add('active');
    paneRaw.classList.remove('active');
  }
}

/**
 * Fill manual form from extracted propertyData
 */
function fillManualFormFromPropertyData(prop) {
  if (!prop) return;

  const setValue = (id, val) => {
    const el = document.getElementById(id);
    if (el) el.value = val !== null && val !== undefined ? val : '';
  };

  const setCheckbox = (id, checked) => {
    const el = document.getElementById(id);
    if (el) el.checked = Boolean(checked);
  };

  setValue('manualStreet', prop.location.street);
  const distEl = document.getElementById('manualDistrict');
  if (distEl) {
    distEl.value = prop.location.district || '';
    updateManualWardsDropdown(prop.location.district, prop.location.ward);
  }
  setValue('manualLandmark', prop.connectivity.intersections[0] || prop.connectivity.nearbyPoints[0] || '');

  setValue('manualLandArea', prop.area.landArea);
  setValue('manualWidth', prop.dimensions.width);
  setValue('manualLength', prop.dimensions.length);
  setValue('manualDtxd', prop.area.constructionArea);
  setValue('manualDts', prop.area.totalFloorArea);
  setValue('manualYard', prop.area.yardArea);

  setValue('manualFloors', prop.structure.floors);
  setValue('manualFloorDesc', prop.structure.floorDescription);
  setValue('manualRooms', prop.rooms.bedrooms || prop.rooms.totalRooms);
  setValue('manualBathrooms', prop.rooms.bathrooms);
  setValue('manualCommercial', prop.rooms.commercialSpace ? 'Tầng trệt đang làm café' : '');

  setValue('manualAlleyType', prop.alley.type || 'Hẻm nhựa ô tô');
  setValue('manualDistanceToStreet', prop.alley.distanceToStreet);
  setCheckbox('manualBehindFront', prop.alley.behindFrontHouse);
  setCheckbox('manualThroughAlley', prop.alley.isThroughAlley);

  setValue('manualRent', prop.exploitation.monthlyRent);
  setValue('manualExploitStatus', prop.exploitation.currentStatus);
  setValue('manualPotential', prop.exploitation.potential.join(', '));

  setValue('manualPrice', prop.price.askingPrice);
  const oriEl = document.getElementById('manualOrientation');
  if (oriEl) {
    if (prop.orientation.direction) {
      const dirVal = prop.orientation.direction.trim();
      oriEl.value = dirVal;
      if (!oriEl.value && /^chính\s+/i.test(dirVal)) {
        oriEl.value = dirVal.replace(/^chính\s+/i, '');
      }
    } else {
      oriEl.value = '';
    }
  }
  setValue('manualLegalDoc', prop.legal.documentType || 'Sổ hồng riêng');
  setValue('manualCompletion', prop.legal.hasCompletion === true ? 'yes' : prop.legal.hasCompletion === false ? 'no' : 'unknown');
  setCheckbox('manualNegotiable', prop.price.negotiable);

  // Synchronize Section 7: New House & Luxury Amenities
  const nh = prop.newHouseFeatures || {};
  const setNhChip = (id, checked) => {
    const el = document.getElementById(id);
    if (el) {
      el.checked = Boolean(checked);
      const lbl = (el.closest ? el.closest('.nh-chip-label') : null) || document.getElementById('lbl_' + id);
      if (lbl) lbl.classList.toggle('active', Boolean(checked));
    }
  };

  setNhChip('nhNew100', nh.isNew100);
  setNhChip('nhFullInterior', nh.handover === 'full_interior');
  setNhChip('nhBasicInterior', nh.handover === 'basic_interior');
  setNhChip('nhGiftInterior', nh.giftInterior);

  setNhChip('nhElevator', nh.hasElevator);
  setNhChip('nhElevatorShaft', nh.hasElevatorShaft);
  setNhChip('nhGarageInside', nh.hasGarageInside);
  setNhChip('nhParkingYard', nh.hasParkingYard);

  setNhChip('nhMezzanineVoid', nh.hasMezzanineVoid);
  setNhChip('nhMasterCloset', nh.hasMasterCloset);
  setNhChip('nhBathtub', nh.hasBathtub);
  setNhChip('nhSauna', nh.hasSauna);
  setNhChip('nhSkyGarden', nh.hasSkyGarden);
  setNhChip('nhWorshipRoom', nh.hasWorshipRoom);
  setNhChip('nhSkylight', nh.hasSkylight);

  setNhChip('nhSmartLock', nh.hasSmartLock);
  setNhChip('nhSmartHome', nh.hasSmartHome);
  setNhChip('nhSecurityCam', nh.hasSecurityCam);
  setNhChip('nhCentralAC', nh.hasCentralAC);
  setNhChip('nhSolarWater', nh.hasSolarWater);
  setNhChip('nhIndependentWall', nh.hasIndependentWall);
  setNhChip('nhDesignDocs', nh.hasDesignDocs);
  setNhChip('nhWarranty', nh.hasWarranty);

  if (nh.elevatorType) {
    setValue('nhElevatorType', nh.elevatorType);
  }
  const elElevWrap = document.getElementById('nhElevatorSubWrap');
  if (elElevWrap) {
    elElevWrap.style.display = nh.hasElevator ? 'block' : 'none';
  }
}

/**
 * Collect data from manual form into propertyData and synthesize raw text
 */
function collectManualFormData() {
  const getVal = (id) => {
    const el = document.getElementById(id);
    return el && el.value !== undefined && el.value !== null ? String(el.value).trim() : '';
  };
  const getNum = (id) => {
    const val = getVal(id);
    return val ? parseFloat(val.replace(',', '.')) : null;
  };
  const getInt = (id) => {
    const val = getVal(id);
    return val ? parseInt(val, 10) : null;
  };
  const getCheck = (id) => (document.getElementById(id) ? document.getElementById(id).checked : false);

  const street = getVal('manualStreet');
  const district = getVal('manualDistrict');
  let ward = getVal('manualWard');
  if (ward === '__custom__') {
    ward = getVal('manualCustomWard');
  }
  const landmark = getVal('manualLandmark');

  const landArea = getNum('manualLandArea');
  const width = getNum('manualWidth');
  const length = getNum('manualLength');
  const dtxd = getNum('manualDtxd');
  const dts = getNum('manualDts');
  const yard = getNum('manualYard');

  const floors = getInt('manualFloors');
  const floorDesc = getVal('manualFloorDesc');
  const rooms = getInt('manualRooms');
  const bathrooms = getInt('manualBathrooms');
  const commercial = getVal('manualCommercial');

  const alleyType = getVal('manualAlleyType');
  const distanceToStreet = getVal('manualDistanceToStreet');
  const behindFront = getCheck('manualBehindFront');
  const throughAlley = getCheck('manualThroughAlley');

  const rent = getVal('manualRent');
  const exploitStatus = getVal('manualExploitStatus');
  const potential = getVal('manualPotential');

  const price = getVal('manualPrice');
  const orientation = getVal('manualOrientation');
  const legalDoc = getVal('manualLegalDoc');
  const completion = getVal('manualCompletion');
  const negotiable = getCheck('manualNegotiable');

  // Collect Section 7: New House & Turnkey Amenities
  const nhNew100 = getCheck('nhNew100');
  const nhFullInterior = getCheck('nhFullInterior');
  const nhBasicInterior = getCheck('nhBasicInterior');
  const nhGiftInterior = getCheck('nhGiftInterior');

  const nhElevator = getCheck('nhElevator');
  const nhElevatorType = getVal('nhElevatorType') || 'Thang máy kính quan sát 450kg (6 người)';
  const nhElevatorShaft = getCheck('nhElevatorShaft');
  const nhGarageInside = getCheck('nhGarageInside');
  const nhParkingYard = getCheck('nhParkingYard');

  const nhMezzanineVoid = getCheck('nhMezzanineVoid');
  const nhMasterCloset = getCheck('nhMasterCloset');
  const nhBathtub = getCheck('nhBathtub');
  const nhSauna = getCheck('nhSauna');
  const nhSkyGarden = getCheck('nhSkyGarden');
  const nhWorshipRoom = getCheck('nhWorshipRoom');
  const nhSkylight = getCheck('nhSkylight');

  const nhSmartLock = getCheck('nhSmartLock');
  const nhSmartHome = getCheck('nhSmartHome');
  const nhSecurityCam = getCheck('nhSecurityCam');
  const nhCentralAC = getCheck('nhCentralAC');
  const nhSolarWater = getCheck('nhSolarWater');
  const nhIndependentWall = getCheck('nhIndependentWall');
  const nhDesignDocs = getCheck('nhDesignDocs');
  const nhWarranty = getCheck('nhWarranty');

  // Synthesize formatted raw text lines
  const rawLines = [];
  if (street) rawLines.push(street);
  if (ward) rawLines.push(ward);
  if (district) rawLines.push(district);
  if (landArea) rawLines.push(`${landArea}m² đất`);
  if (dtxd) rawLines.push(`Diện tích xây dựng ${dtxd}m²`);
  if (dts) rawLines.push(`Tổng diện tích sàn ${dts}m²`);
  if (yard) rawLines.push(`Sân ${yard}m²`);
  if (floors) rawLines.push(`${floors} tầng`);
  if (floorDesc) rawLines.push(floorDesc);
  if (width) rawLines.push(`Ngang ${width}m`);
  if (length) rawLines.push(`Dài ${length}m`);
  if (price) rawLines.push(`Giá ${price}`);
  if (alleyType) rawLines.push(alleyType);
  if (behindFront) rawLines.push('Phía sau nhà mặt tiền');
  if (distanceToStreet) rawLines.push(`Cách mặt tiền ${distanceToStreet}`);
  if (landmark) rawLines.push(landmark);
  if (potential) rawLines.push(potential);
  if (commercial) rawLines.push(commercial);
  if (rent) rawLines.push(`Hiện đang cho thuê khoán ${rent}`);
  if (rooms) rawLines.push(`${rooms} phòng`);
  if (bathrooms) rawLines.push(`${bathrooms} WC`);
  if (orientation) rawLines.push(`Hướng ${orientation}`);
  if (legalDoc) rawLines.push(legalDoc);

  // Append new house lines to raw text
  if (nhNew100) rawLines.push('Nhà mới xây 100% bóc tem');
  if (nhFullInterior) rawLines.push('Full nội thất cao cấp xách vali vào ở');
  else if (nhBasicInterior) rawLines.push('Hoàn thiện cơ bản dính tường');
  if (nhGiftInterior) rawLines.push('Tặng lại toàn bộ nội thất và bản vẽ');
  if (nhElevator) rawLines.push(`Có ${nhElevatorType}`);
  if (nhElevatorShaft) rawLines.push('Có ô chờ thang máy');
  if (nhGarageInside) rawLines.push('Gara ô tô trong nhà');
  if (nhParkingYard) rawLines.push('Sân đậu ô tô riêng trước nhà');
  if (nhMezzanineVoid) rawLines.push('Phòng khách lửng thông tầng trần cao');
  if (nhMasterCloset) rawLines.push('Phòng ngủ Master VIP có phòng thay đồ walk-in closet');
  if (nhBathtub) rawLines.push('Bồn tắm nằm massage thư giãn');
  if (nhSauna) rawLines.push('Phòng xông hơi sauna');
  if (nhSkyGarden) rawLines.push('Sân thượng sky garden BBQ');
  if (nhWorshipRoom) rawLines.push('Có phòng thờ trang nghiêm riêng');
  if (nhSkylight) rawLines.push('Giếng trời lớn lấy sáng tự nhiên');
  if (nhSmartLock) rawLines.push('Khóa từ vân tay thông minh');
  if (nhSmartHome) rawLines.push('Hệ thống điện smart home');
  if (nhSecurityCam) rawLines.push('Camera an ninh 24/7 và chuông hình');
  if (nhCentralAC) rawLines.push('Máy lạnh âm trần cao cấp');
  if (nhSolarWater) rawLines.push('Nước nóng năng lượng mặt trời');
  if (nhIndependentWall) rawLines.push('Tường riêng, móng riêng, cột riêng');
  if (nhDesignDocs) rawLines.push('Có hồ sơ bản vẽ thiết kế kiến trúc kết cấu');
  if (nhWarranty) rawLines.push('Bảo hành kết cấu công trình');

  const syntheticRawText = rawLines.join('\n');
  const rawInputEl = document.getElementById('rawInfoInput');
  if (rawInputEl) rawInputEl.value = syntheticRawText;

  // Build propertyData
  const prop = {
    rawText: syntheticRawText,
    location: {
      street,
      ward,
      district,
      city: 'TP. Hồ Chí Minh',
      landmark,
      rawLocation: [street, ward, district].filter(Boolean).join(', '),
      verified: Boolean(street)
    },
    area: {
      landArea,
      landAreaUnit: 'm²',
      constructionArea: dtxd,
      totalFloorArea: dts,
      yardArea: yard,
      verified: Boolean(landArea)
    },
    dimensions: {
      width,
      length,
      verified: Boolean(width)
    },
    structure: {
      floors,
      floorDescription: floorDesc || (floors ? `${floors} tầng` : ''),
      hasGroundFloor: true,
      hasRooftop: /rooftop/i.test(floorDesc) || nhSkyGarden,
      hasTerrace: /sân thượng/i.test(floorDesc) || nhSkyGarden,
      verified: Boolean(floors)
    },
    rooms: {
      bedrooms: rooms,
      totalRooms: rooms,
      bathrooms,
      livingRoom: true,
      kitchen: true,
      commercialSpace: Boolean(commercial),
      verified: Boolean(rooms)
    },
    alley: {
      type: alleyType,
      isCarAccessible: /ô tô|xe hơi|mặt tiền/i.test(alleyType) || nhGarageInside || nhParkingYard,
      isThroughAlley: throughAlley,
      isDeadEnd: false,
      distanceToStreet,
      behindFrontHouse: behindFront,
      verified: Boolean(alleyType)
    },
    connectivity: {
      mainStreets: [street].filter(Boolean),
      intersections: landmark ? [landmark] : [],
      nearbyPoints: [],
      verified: Boolean(landmark)
    },
    exploitation: {
      currentStatus: commercial ? `${commercial}; các tầng trên khai thác phòng` : (exploitStatus || (nhNew100 ? 'Nhà mới xây 100% chưa qua sử dụng' : '')),
      monthlyRent: rent,
      revenueProvided: Boolean(rent),
      potential: potential ? [potential] : [],
      verified: Boolean(rent),
      cautionNote: potential ? 'Chủ nhà định hướng khai thác; cần kiểm tra quy hoạch, giấy phép và điều kiện xây dựng thực tế.' : ''
    },
    legal: {
      documentType: legalDoc,
      hasCompletion: completion === 'yes' ? true : completion === 'no' ? false : null,
      verified: Boolean(legalDoc),
      note: ''
    },
    price: (() => {
      if (!price) return { askingPrice: '', priceValue: null, negotiable, verified: false };
      const parsedP = parseRealEstatePrice(price);
      return {
        askingPrice: price,
        priceValue: parsedP.priceValue || (parseFloat(price.replace(',', '.')) || null),
        negotiable: negotiable || parsedP.negotiable,
        verified: true
      };
    })(),
    orientation: {
      direction: orientation,
      verified: Boolean(orientation)
    },
    currentStatus: {
      description: nhNew100 ? 'Nhà mới xây 100% chưa qua sử dụng' : (exploitStatus || (commercial ? 'Đang kinh doanh' : 'Đang sử dụng')),
      verified: true
    },
    interior: {
      description: nhFullInterior ? 'Full nội thất cao cấp xách vali vào ở' : (nhBasicInterior ? 'Hoàn thiện cơ bản dính tường' : 'Theo hiện trạng thực tế'),
      verified: Boolean(nhFullInterior || nhBasicInterior)
    },
    newHouseFeatures: {
      isNew100: nhNew100,
      handover: nhFullInterior ? 'full_interior' : (nhBasicInterior ? 'basic_interior' : ''),
      giftInterior: nhGiftInterior,
      hasElevator: nhElevator,
      elevatorType: nhElevatorType,
      hasElevatorShaft: nhElevatorShaft,
      hasGarageInside: nhGarageInside,
      hasParkingYard: nhParkingYard,
      hasMezzanineVoid: nhMezzanineVoid,
      hasMasterCloset: nhMasterCloset,
      hasBathtub: nhBathtub,
      hasSauna: nhSauna,
      hasSkyGarden: nhSkyGarden,
      hasWorshipRoom: nhWorshipRoom,
      hasSkylight: nhSkylight,
      hasSmartLock: nhSmartLock,
      hasSmartHome: nhSmartHome,
      hasSecurityCam: nhSecurityCam,
      hasCentralAC: nhCentralAC,
      hasSolarWater: nhSolarWater,
      hasIndependentWall: nhIndependentWall,
      hasDesignDocs: nhDesignDocs,
      hasCompletionDone: completion === 'yes',
      hasWarranty: nhWarranty
    },
    otherNotes: [],
    verification: {
      missingFields: [],
      conflicts: [],
      unverifiedPoints: []
    }
  };

  validatePropertyData(prop);
  return prop;
}

