function toggleNhChip(el) {
  if (!el) return;
  const isChecked = Boolean(el.checked);
  const lbl = (el.closest ? el.closest('.nh-chip-label') : null) || document.getElementById('lbl_' + el.id);
  if (lbl) {
    lbl.classList.toggle('active', isChecked);
  }
  if (el.id === 'nhElevator') {
    const wrap = document.getElementById('nhElevatorSubWrap');
    if (wrap) wrap.style.display = isChecked ? 'block' : 'none';
  }
  syncManualToRaw();
}

