    const wrap = document.getElementById('nhElevatorSubWrap');
    if (wrap) wrap.style.display = 'none';
    syncManualToRaw();
    showToast('🏠 Đã áp dụng Combo Nhà Phố Mới (Khóa Từ, Gara, Giếng Trời)!', '🏠');
