function renderMultiVersionTabs() {
  const tabsWrap = document.getElementById('versionTabsWrap');
  if (AppState.styleMode !== 'multi' || AppState.multiVersions.length === 0) {
    tabsWrap.classList.remove('visible');
    return;
  }

  tabsWrap.classList.add('visible');
  tabsWrap.innerHTML = AppState.multiVersions.map((v, i) => `
    <button class="version-tab ${i === AppState.activeMultiIndex ? 'active' : ''}" onclick="selectMultiVersionTab(${i})">
      <span>${v.title}</span>
    </button>
  `).join('');
}

function selectMultiVersionTab(index) {
  AppState.activeMultiIndex = index;
  const ver = AppState.multiVersions[index];
  AppState.currentStyle = ver.style;
  AppState.currentSellingAngle = ver.angle;
  renderMultiVersionTabs();
  renderActiveScript();
}

function renderActiveScript() {
  const prop = AppState.currentPropertyData;
  const styleKey = AppState.currentStyle;
  const angleObj = AppState.currentSellingAngle || AppState.allDiscoveredAngles[0];
  const duration = AppState.currentDuration;

  const styleDef = STYLE_DEFINITIONS[styleKey] || STYLE_DEFINITIONS['data_selling'];

  document.getElementById('displayVideoTitle').textContent = `KỊCH BẢN VIDEO: ${styleDef.name.toUpperCase()} — ${(angleObj ? angleObj.name : 'GÓC BÁN').toUpperCase()}`;
  document.getElementById('displayBadgeStyle').innerHTML = `🎭 Phong cách: <strong>${styleDef.name}</strong>`;
  document.getElementById('displayBadgeAngle').innerHTML = `🧭 Góc bán: <strong>${angleObj ? angleObj.name : 'Vị trí'}</strong>`;
  const rec = recommendVideoStyle(prop, angleObj);
  document.getElementById('displayStyleReason').textContent = rec.reason;

  const altWrap = document.getElementById('displayAlternativeStyles');
  const otherStyles = Object.keys(STYLE_DEFINITIONS).filter(k => k !== styleKey);
  altWrap.innerHTML = `
    <span>🎭 <strong>BLOCK 09 — Các Style khác có thể kể góc này:</strong></span>
    ${otherStyles.map(sk => `
      <button class="btn-copy-small" style="font-size: 0.72rem; padding: 0.2rem 0.5rem;" onclick="changeVideoStyle('${sk}')">
        ${STYLE_DEFINITIONS[sk].name}
      </button>
    `).join('')}
  `;

  const scriptItems = generateVideoScript(prop, styleKey, angleObj, duration);
  const totalWords = scriptItems.reduce((acc, item) => acc + (item.vo ? item.vo.split(/\s+/).filter(Boolean).length : 0), 0);
  document.getElementById('displayBadgeDuration').innerHTML = `⏱️ Thời lượng: <strong>${duration}s</strong> • ${scriptItems.length} cảnh • ~${totalWords} từ (${getPaceLabel(AppState.currentPace)})`;

  const hookText = scriptItems[0] ? scriptItems[0].vo : generateHook(prop, styleKey, angleObj);
  document.getElementById('displayHookContent').textContent = `"${hookText}"`;

  const tableBody = document.getElementById('scriptTableBody');
  tableBody.innerHTML = scriptItems.map(item => `
    <tr>
      <td class="timing-cell">${item.timeRange}</td>
      <td class="shot-desc-cell">${escapeHtml(item.scene)}</td>
      <td class="voiceover-cell">${formatVoiceoverHtml(item.vo)}</td>
      <td class="onscreen-text-cell">
        <span class="caption-tag">${escapeHtml(item.text)}</span>
      </td>
    </tr>
  `).join('');

  const shotList = generateShotList(scriptItems);
  const shotListContainer = document.getElementById('shotListContainer');
  shotListContainer.innerHTML = shotList.map(shot => `
    <div class="shot-card">
      <div class="shot-num">${shot.shotNumber}</div>
      <div class="shot-detail">
        <div class="shot-name">${escapeHtml(shot.description)}</div>
        <div class="shot-note">⏱️ ${shot.timing} • 🎥 ${shot.equipmentNote}</div>
      </div>
    </div>
  `).join('');

  const voContainer = document.getElementById('voiceoverContainer');
  const fullVO = generateVoiceover(scriptItems);
  voContainer.innerHTML = formatVoiceoverHtml(fullVO);

  const captions = generateOnScreenText(scriptItems);
  const captionsContainer = document.getElementById('captionsContainer');
  captionsContainer.innerHTML = captions.map(c => `
    <div class="caption-tag" style="padding: 0.4rem 0.7rem; font-size: 0.84rem;">
      💬 ${escapeHtml(c)}
    </div>
  `).join('');

  const cta = generateCTA(prop);
  document.getElementById('ctaMainText').textContent = `"${cta.primary}"`;
  document.getElementById('ctaVariantsText').innerHTML = `
    Các phương án CTA khác: <strong>"${cta.alternatives[0]}"</strong> • <strong>"${cta.alternatives[1]}"</strong>
  `;
}

function formatVoiceoverHtml(text) {
  if (!text) return '';
  const withBreaths = escapeHtml(text).replace(/\s*\/\s*/g, ' <span class="breath">/</span> ');
  return withBreaths.replace(/\n\n/g, '<br><br>');
}

// ==========================================
// 13. INTERACTIVE CONTROLS (Section 21 - 24)
// ==========================================

function changeSellingAngle(newAngleKey) {
  if (!AppState.currentPropertyData) return;

  const found = AppState.allDiscoveredAngles.find(a => a.key === newAngleKey);
  if (found) {
    AppState.currentSellingAngle = found;
  } else {
    const curIdx = AppState.allDiscoveredAngles.findIndex(a => a.key === (AppState.currentSellingAngle ? AppState.currentSellingAngle.key : ''));
    const nextIdx = (curIdx + 1) % AppState.allDiscoveredAngles.length;
    AppState.currentSellingAngle = AppState.allDiscoveredAngles[nextIdx];
  }

  renderBlockSellingAngles(AppState.currentPropertyData);
  renderActiveScript();
  showToast(`🧭 Đã đổi góc bán sang: ${AppState.currentSellingAngle.name}`, '🔄');
}

function changeVideoStyle(newStyleKey) {
  if (!AppState.currentPropertyData) return;
  AppState.currentStyle = newStyleKey;
  renderActiveScript();
  showToast(`🎭 Đã đổi phong cách sang: ${STYLE_DEFINITIONS[newStyleKey].name}`, '🎭');
}

function regenerateHook() {
  if (!AppState.currentPropertyData) return;
  const hooks = generateFiveHooks(AppState.currentPropertyData);
  const modalList = document.getElementById('hookModalList');

  modalList.innerHTML = hooks.map(h => `
    <div class="hook-option-item" onclick="applyCustomHook('${escapeHtml(h.text)}')">
      <div class="hook-option-tag">${h.type}</div>
      <div class="hook-option-text">"${escapeHtml(h.text)}"</div>
      <div style="font-size: 0.72rem; color: #94a3b8; margin-top: 0.3rem;">Bấm để áp dụng Hook này vào kịch bản</div>
    </div>
  `).join('');

  document.getElementById('hookModal').classList.add('open');
}

function applyCustomHook(hookText) {
  document.getElementById('displayHookContent').textContent = `"${hookText}"`;
  const firstRowVo = document.querySelector('#scriptTableBody tr td.voiceover-cell');
  if (firstRowVo) {
    firstRowVo.innerHTML = formatVoiceoverHtml(hookText);
  }
  closeHookModal();
  showToast('⚡ Đã cập nhật Hook mới vào kịch bản!', '✅');
}

function closeHookModal() {
  document.getElementById('hookModal').classList.remove('open');
}

function changeDuration(newDuration, newPace) {
  const parsed = parseInt(newDuration, 10);
  if (!isNaN(parsed)) {
    AppState.currentDuration = Math.max(10, Math.min(300, parsed));
  }
  if (newPace) {
    AppState.currentPace = newPace;
  }

  updateDurationUI(AppState.currentDuration, AppState.currentPace);

  if (AppState.currentPropertyData) {
    renderActiveScript();
    showToast(`⏱️ Đã tính toán lại kịch bản cho video ${AppState.currentDuration}s (${getPaceLabel(AppState.currentPace)})`, '⏱️');
  }
}

function changePace(newPace) {
  if (newPace && ['fast', 'standard', 'relaxed'].includes(newPace)) {
    AppState.currentPace = newPace;
    updateDurationUI(AppState.currentDuration, AppState.currentPace);
    if (AppState.currentPropertyData) {
      renderActiveScript();
      showToast(`🎙️ Đã đổi nhịp điệu giọng đọc: ${getPaceLabel(AppState.currentPace)}`, '🎙️');
    }
  }
}

function updateDurationUI(duration, pace = 'standard') {
  // 1. Update pills active state
  let matchedPreset = false;
  document.querySelectorAll('#durationPills .pill-btn[data-duration]').forEach(btn => {
    const btnDur = parseInt(btn.getAttribute('data-duration'), 10);
    if (btnDur === duration) {
      btn.classList.add('active');
      matchedPreset = true;
    } else {
      btn.classList.remove('active');
    }
  });

  const customToggleBtn = document.getElementById('btnToggleCustomDuration');
  if (customToggleBtn) {
    if (!matchedPreset) {
      customToggleBtn.classList.add('active');
    } else {
      customToggleBtn.classList.remove('active');
    }
  }

  // 2. Update inputs & slider
  const slider = document.getElementById('durationRangeSlider');
  if (slider && parseInt(slider.value, 10) !== duration) {
    slider.value = duration;
  }

  const numInput = document.getElementById('customDurationInput');
  if (numInput && parseInt(numInput.value, 10) !== duration) {
    numInput.value = duration;
  }

  const currentTag = document.getElementById('durationCurrentTag');
  if (currentTag) {
    currentTag.textContent = `${duration} giây (${formatTime(duration)})`;
  }

  // 3. Update Pacing buttons active state
  document.querySelectorAll('#pacingOptions .pacing-btn').forEach(btn => {
    if (btn.getAttribute('data-pace') === pace) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });

  // 4. Update metrics indicators
  const sceneCountEl = document.getElementById('metricSceneCount');
  if (sceneCountEl) {
    const sc = estimateSceneCount(duration);
    const avgSec = Math.round(duration / sc);
    sceneCountEl.textContent = `${sc} cảnh (~${avgSec}s/cảnh)`;
  }

  const wordCountEl = document.getElementById('metricWordCount');
  if (wordCountEl) {
    wordCountEl.textContent = estimateWordCount(duration, pace);
  }

  const platformEl = document.getElementById('metricPlatform');
  if (platformEl) {
    platformEl.textContent = getRecommendedPlatform(duration);
  }
}

function initDurationControls() {
  // Preset pills
  document.querySelectorAll('#durationPills .pill-btn[data-duration]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const dur = e.currentTarget.getAttribute('data-duration');
      changeDuration(dur);
    });
  });

  // Toggle custom box
  const btnToggleCustom = document.getElementById('btnToggleCustomDuration');
  const customBox = document.getElementById('customDurationBox');
  if (btnToggleCustom && customBox) {
    btnToggleCustom.addEventListener('click', () => {
      const isVisible = customBox.style.display !== 'none';
      customBox.style.display = isVisible ? 'none' : 'flex';
      if (!isVisible) {
        const input = document.getElementById('customDurationInput');
        if (input) input.focus();
      }
    });
  }

  // Range Slider
  const slider = document.getElementById('durationRangeSlider');
  if (slider) {
    slider.addEventListener('input', (e) => {
      changeDuration(e.target.value);
    });
  }

  // Number input
  const numInput = document.getElementById('customDurationInput');
  if (numInput) {
    numInput.addEventListener('input', (e) => {
      const val = parseInt(e.target.value, 10);
      if (!isNaN(val) && val >= 10 && val <= 300) {
        changeDuration(val);
      }
    });
    numInput.addEventListener('change', (e) => {
      let val = parseInt(e.target.value, 10);
      if (isNaN(val) || val < 10) val = 10;
      if (val > 300) val = 300;
      changeDuration(val);
    });
  }

  // Steppers
  const btnMinus = document.getElementById('btnDurationMinus');
  if (btnMinus) {
    btnMinus.addEventListener('click', () => {
      changeDuration(Math.max(10, AppState.currentDuration - 5));
    });
  }

  const btnPlus = document.getElementById('btnDurationPlus');
  if (btnPlus) {
    btnPlus.addEventListener('click', () => {
      changeDuration(Math.min(300, AppState.currentDuration + 5));
    });
  }

  // Pacing options
  document.querySelectorAll('#pacingOptions .pacing-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const pace = e.currentTarget.getAttribute('data-pace');
      changePace(pace);
    });
  });

  // Quick Action Bar cycle button
  const btnQuickDuration = document.getElementById('btnQuickChangeDuration');
  if (btnQuickDuration) {
    btnQuickDuration.addEventListener('click', () => {
      const durations = [15, 30, 45, 60, 90, 120, 180];
      const curIdx = durations.indexOf(AppState.currentDuration);
      const nextIdx = (curIdx + 1) % durations.length;
      changeDuration(durations[nextIdx]);
    });
  }

  // Initialize UI state
  updateDurationUI(AppState.currentDuration, AppState.currentPace);
}

