function copyResult(elementId, label) {
  const el = document.getElementById(elementId);
  if (!el) return;
  const text = el.innerText || el.textContent;
  copyTextToClipboard(text, label);
}

function copyBlockContent(elementId, label) {
  copyResult(elementId, label);
}

function copyEntireCurrentScript() {
  if (!AppState.currentPropertyData) {
    showToast('Chưa có kịch bản để copy!', '⚠️');
    return;
  }

  const prop = AppState.currentPropertyData;
  const styleDef = STYLE_DEFINITIONS[AppState.currentStyle];
  const angleObj = AppState.currentSellingAngle;
  const scriptItems = generateVideoScript(prop, AppState.currentStyle, angleObj, AppState.currentDuration);
  const shotList = generateShotList(scriptItems);
  const cta = generateCTA(prop);

  let exportText = `==================================================\n`;
  exportText += `KỊCH BẢN VIDEO BÁN NHÀ: ${prop.location.rawLocation || 'BẤT ĐỘNG SẢN'}\n`;
  exportText += `PHONG CÁCH: ${styleDef.name.toUpperCase()} (${styleDef.subtitle})\n`;
  exportText += `GÓC BÁN: ${angleObj ? angleObj.name.toUpperCase() : 'VỊ TRÍ'}\n`;
  exportText += `THỜI LƯỢNG: ${AppState.currentDuration} GIÂY\n`;
  exportText += `==================================================\n\n`;

  exportText += `[01] HOOK MỞ ĐẦU:\n`;
  exportText += `"${scriptItems[0].vo}"\n\n`;

  exportText += `[02] BẢNG KỊCH BẢN QUAY CHI TIẾT:\n`;
  scriptItems.forEach((item, i) => {
    exportText += `--------------------------------------------------\n`;
    exportText += `CẢNH ${(i + 1).toString().padStart(2, '0')} (${item.timeRange}):\n`;
    exportText += `• CẢNH QUAY: ${item.scene}\n`;
    exportText += `• VOICEOVER: ${item.vo}\n`;
    exportText += `• TEXT MÀN HÌNH: ${item.text}\n`;
  });
  exportText += `--------------------------------------------------\n\n`;

  exportText += `[03] SHOT LIST ĐI QUAY THỰC ĐỊA:\n`;
  shotList.forEach(s => {
    exportText += `${s.shotNumber} (${s.timing}): ${s.description} [${s.equipmentNote}]\n`;
  });
  exportText += `\n`;

  exportText += `[04] TOÀN BỘ LỜI ĐỌC VOICEOVER (CÓ DẤU NGẮT HƠI '/'):\n`;
  exportText += generateVoiceover(scriptItems) + `\n\n`;

  exportText += `[05] LỜI KÊU GỌI HÀNH ĐỘNG (CTA):\n`;
  exportText += `"${cta.primary}"\n\n`;

  exportText += `[06] THÔNG TIN XÁC MINH CẦN LƯU Ý KHI TƯ VẤN KHÁCH:\n`;
  prop.verification.unverifiedPoints.forEach(u => {
    exportText += `• ${u}\n`;
  });

  copyTextToClipboard(exportText, 'Toàn bộ Kịch Bản Video');
}

function copyTextToClipboard(text, label) {
  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      showToast(`Đã copy ${label || 'nội dung'} vào clipboard!`, '📋');
    }).catch(() => {
      fallbackCopyText(text, label);
    });
  } else {
    fallbackCopyText(text, label);
  }
}

function fallbackCopyText(text, label) {
  if (typeof document === 'undefined') return;
  const textArea = document.createElement('textarea');
  textArea.value = text;
  textArea.style.position = 'fixed';
  textArea.style.left = '-9999px';
  document.body.appendChild(textArea);
  textArea.focus();
  textArea.select();
  try {
    document.execCommand('copy');
    showToast(`Đã copy ${label || 'nội dung'} vào clipboard!`, '📋');
  } catch (err) {
    showToast('Không thể copy, vui lòng copy thủ công.', '⚠️');
  }
  document.body.removeChild(textArea);
}

function showToast(message, icon = '✅') {
  if (typeof document === 'undefined') return;
  const toast = document.getElementById('toastNotification');
  if (!toast) return;
  const iconEl = document.getElementById('toastIcon');
  const msgEl = document.getElementById('toastMessage');

  iconEl.textContent = icon;
  msgEl.textContent = message;

  toast.classList.add('show');
  setTimeout(() => {
    toast.classList.remove('show');
  }, 2800);
}

function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

// Settings modal
function openSettingsModal() {
  document.getElementById('settingsModal').classList.add('open');
  const saved = localStorage.getItem('auto_video_api_settings');
  if (saved) {
    try {
      const parsed = JSON.parse(saved);
      document.getElementById('apiProviderSelect').value = parsed.provider || 'offline';
      document.getElementById('userApiKeyInput').value = parsed.apiKey || '';
    } catch (e) {}
  }
}

function closeSettingsModal() {
  document.getElementById('settingsModal').classList.remove('open');
}

function saveApiSettings() {
  const provider = document.getElementById('apiProviderSelect').value;
  const apiKey = document.getElementById('userApiKeyInput').value.trim();

  AppState.apiSettings = { provider, apiKey };
  localStorage.setItem('auto_video_api_settings', JSON.stringify(AppState.apiSettings));
  closeSettingsModal();
  showToast('Đã lưu cấu hình AI API!', '⚙️');
}

// ==========================================
// 15. DOM LISTENERS & INITIALIZATION
// ==========================================
// ==========================================
// 2025 HCMC FORM & LOOKUP MODAL CONTROLLER
function syncManualToRaw() {
  if (typeof document === 'undefined') return;
  const rawEl = document.getElementById('rawInfoInput');
  if (!rawEl) return;
  try {
    collectManualFormData();
  } catch (e) {}
}

function initHcmcManualForm() {
  const distEl = document.getElementById('manualDistrict');
  const wardEl = document.getElementById('manualWard');
  const distDatalist = document.getElementById('districtsListDatalist');
  if (!distEl || !wardEl) return;

  // Populate districts datalist for autocomplete
  if (distDatalist) {
    distDatalist.innerHTML = '';
    HCMC_MERGER_DATA.forEach(d => {
      const opt = document.createElement('option');
      opt.value = d.district;
      distDatalist.appendChild(opt);
    });
  }

  // Live listener on District input
  const handleDistrictChange = () => {
    updateManualWardsDropdown(distEl.value, wardEl.value);
    updateMergerNoticeBadge(distEl.value, wardEl.value);
    syncManualToRaw();
  };
  distEl.addEventListener('input', handleDistrictChange);
  distEl.addEventListener('change', handleDistrictChange);

  // Live listener on Ward input (allows free-hand typing)
  const handleWardChange = () => {
    updateMergerNoticeBadge(distEl.value, wardEl.value);
    syncManualToRaw();
  };
  wardEl.addEventListener('input', handleWardChange);
  wardEl.addEventListener('change', handleWardChange);
}

function updateManualWardsDropdown(district, preselectedWard = '') {
  const wardEl = document.getElementById('manualWard');
  const wardsDatalist = document.getElementById('wardsListDatalist');
  const chipsWrap = document.getElementById('manualWardChipsWrap');
  const chipsList = document.getElementById('manualWardChipsList');
  if (!wardEl) return;

  const wards = getMergerWardsForDistrict(district);

  // 1. Populate Ward datalist for typing autocomplete
  if (wardsDatalist) {
    wardsDatalist.innerHTML = '';
    if (wards && wards.length > 0) {
      wards.forEach(w => {
        // Option 1: New Ward name (e.g. "Phường Đức Nhuận")
        const opt1 = document.createElement('option');
        opt1.value = w.newWard;
        opt1.label = w.displayLabel;
        wardsDatalist.appendChild(opt1);

        // Option 2: Display label with old ward context
        const opt2 = document.createElement('option');
        opt2.value = w.displayLabel;
        wardsDatalist.appendChild(opt2);

        // Option 3: Old ward abbreviations so typing "P.9" matches
        if (w.shortOld) {
          const parts = w.shortOld.split(',').map(s => s.trim()).filter(Boolean);
          parts.forEach(p => {
            const optOld = document.createElement('option');
            optOld.value = p + ' (nay là ' + w.newWard + ')';
            optOld.label = w.newWard;
            wardsDatalist.appendChild(optOld);
          });
        }
      });
    }
  }

  // 2. Render Quick Chips (1-click to fill)
  if (chipsWrap && chipsList) {
    if (wards && wards.length > 0) {
      chipsWrap.style.display = 'block';
      chipsList.innerHTML = wards.map(w => {
        const safeDisplay = escapeHtml(w.displayLabel);
        const safeNew = escapeHtml(w.newWard);
        const labelText = w.newWard + (w.shortOld ? ' (' + w.shortOld + ')' : '');
        return `<button type="button" class="ward-chip-btn" onclick="selectWardChip('${escapeHtml(w.newWard)}', '${escapeHtml(district)}')" title="Click để chọn ${safeDisplay}">
          ✨ ${escapeHtml(labelText)}
        </button>`;
      }).join('');
    } else {
      chipsWrap.style.display = 'none';
      chipsList.innerHTML = '';
    }
  }

  // 3. Set preselected ward if passed
  if (preselectedWard !== undefined && preselectedWard !== null && preselectedWard !== '') {
    wardEl.value = preselectedWard;
  }

  // 4. Update merger notice badge
  updateMergerNoticeBadge(district, wardEl.value);
}

function selectWardChip(wardName, district) {
  const wardEl = document.getElementById('manualWard');
  const distEl = document.getElementById('manualDistrict');
  if (wardEl) {
    wardEl.value = wardName;
  }
  const curDist = (distEl && distEl.value) ? distEl.value : district;
  updateMergerNoticeBadge(curDist, wardName);
  syncManualToRaw();
  showToast('Đã chọn ' + wardName, '📍');
}

function updateMergerNoticeBadge(district, wardDisplay) {
  const noticeEl = document.getElementById('manualMergerNotice');
  if (!noticeEl) return;

  if (!wardDisplay || !wardDisplay.trim()) {
    noticeEl.style.display = 'none';
    return;
  }

  const merger = resolveHcmcMerger(district, wardDisplay);
  if (merger && merger.matched) {
    noticeEl.style.display = 'flex';
    noticeEl.innerHTML = '<span>🏷️</span> <span>' + escapeHtml(merger.badge) + '</span>';
  } else {
    noticeEl.style.display = 'none';
  }
}

// ------------------------------------------
// MODAL: TRA CỨU SÁP NHẬP ĐƠN VỊ HÀNH CHÍNH 2025
