let currentMergerFilterDistrict = 'ALL';

function initMergerLookupModal() {
  const btnOpen = document.getElementById('btnMergerLookup');
  const btnClose = document.getElementById('btnCloseMergerModal');
  const modal = document.getElementById('mergerLookupModal');
  const searchInput = document.getElementById('mergerSearchInput');
  const pillsContainer = document.getElementById('mergerDistrictPills');

  if (!modal) return;

  if (btnOpen) {
    btnOpen.addEventListener('click', () => {
      openMergerLookupModal();
    });
  }

  if (btnClose) {
    btnClose.addEventListener('click', () => {
      closeMergerLookupModal();
    });
  }

  modal.addEventListener('click', (e) => {
    if (e.target === modal) closeMergerLookupModal();
  });

  // Render pills
  if (pillsContainer) {
    pillsContainer.innerHTML = '';
    const allPill = document.createElement('button');
    allPill.type = 'button';
    allPill.className = 'merger-filter-pill active';
    allPill.textContent = 'Tất cả (22)';
    allPill.addEventListener('click', () => {
      document.querySelectorAll('.merger-filter-pill').forEach(p => p.classList.remove('active'));
      allPill.classList.add('active');
      currentMergerFilterDistrict = 'ALL';
      filterAndRenderMergerCards();
    });
    pillsContainer.appendChild(allPill);

    HCMC_MERGER_DATA.forEach(d => {
      const pill = document.createElement('button');
      pill.type = 'button';
      pill.className = 'merger-filter-pill';
      pill.textContent = d.district;
      pill.addEventListener('click', () => {
        document.querySelectorAll('.merger-filter-pill').forEach(p => p.classList.remove('active'));
        pill.classList.add('active');
        currentMergerFilterDistrict = d.district;
        filterAndRenderMergerCards();
      });
      pillsContainer.appendChild(pill);
    });
  }

  if (searchInput) {
    searchInput.addEventListener('input', () => {
      filterAndRenderMergerCards();
    });
  }
}

function openMergerLookupModal() {
  const ws = document.getElementById('subsystemMergerWorkspace');
  if (ws && ws.style.display !== 'flex' && typeof switchSubsystem === 'function') {
    switchSubsystem('merger');
  }
  const modal = document.getElementById('mergerLookupModal');
  if (modal) {
    modal.classList.add('open');
    modal.classList.add('visible');
    modal.style.display = 'flex';
    filterAndRenderMergerCards();
    setTimeout(() => {
      const input = document.getElementById('mergerSearchInput');
      if (input) input.focus();
    }, 150);
  }
}

function closeMergerLookupModal() {
  const modal = document.getElementById('mergerLookupModal');
  if (modal) {
    modal.classList.remove('open');
    modal.classList.remove('visible');
    modal.style.display = 'none';
  }
  const ws = document.getElementById('subsystemMergerWorkspace');
  if (ws) ws.style.display = 'none';
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('dashboard');
  }
}

function filterAndRenderMergerCards() {
  const searchInput = document.getElementById('mergerSearchInput');
  const query = searchInput ? removeDiacritics(searchInput.value) : '';
  const resultsList = document.getElementById('mergerResultsList');
  const countEl = document.getElementById('mergerResultCount');
  if (!resultsList) return;

  const matches = [];

  HCMC_MERGER_DATA.forEach(d => {
    if (currentMergerFilterDistrict !== 'ALL' && d.district !== currentMergerFilterDistrict) {
      return;
    }

    d.wards.forEach(w => {
      const targetStr = removeDiacritics(d.district + ' ' + w.newWard + ' ' + w.oldWardsRaw + ' ' + w.shortOld);
      if (!query || targetStr.includes(query)) {
        matches.push({
          district: d.district,
          ward: w
        });
      }
    });
  });

  if (countEl) {
    countEl.textContent = 'Tìm thấy ' + matches.length + ' phường/xã sáp nhập phù hợp';
  }

  if (matches.length === 0) {
    resultsList.innerHTML = '<div style="grid-column: 1 / -1; text-align: center; padding: 2rem; color: #64748b;">🔍 Không tìm thấy phường/xã phù hợp với từ khóa "' + escapeHtml(searchInput ? searchInput.value : '') + '".</div>';
    return;
  }

  resultsList.innerHTML = matches.map(m => {
    const safeDist = escapeHtml(m.district);
    const safeNewWard = escapeHtml(m.ward.newWard);
    const safeOld = escapeHtml(m.ward.oldWardsRaw);
    const safeDisplay = escapeHtml(m.ward.displayLabel);

    return `
      <div class="merger-card">
        <div class="merger-card-header">
          <span class="merger-district-tag">${safeDist}</span>
          <span style="font-size: 0.72rem; color: #94a3b8;">Hành chính 2025</span>
        </div>
        <div class="merger-new-ward">${safeNewWard}</div>
        <div class="merger-old-desc">
          <strong style="color: #94a3b8;">Đơn vị cũ sáp nhập:</strong><br/>
          ${safeOld}
        </div>
        <div class="merger-card-actions">
          <button type="button" class="btn-copy-small" onclick="copyMergerInfo(\'${safeDist}\', \'${safeNewWard}\', \'${safeOld}\')">
            📋 Sao chép
          </button>
          <button type="button" class="btn-merger-apply" onclick="applyMergerToManualForm(\'${safeDist}\', \'${safeDisplay}\', \'${safeOld}\')">
            ➡️ Áp dụng vào Form
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function copyMergerInfo(district, newWard, oldWards) {
  const text = newWard + ' (Sáp nhập từ: ' + oldWards + ') - ' + district;
  copyTextToClipboard(text, 'thông tin sáp nhập');
}

function applyMergerToManualForm(district, displayLabel, oldDesc) {
  // 1. Switch to manual tab
  switchInputTab('manual');

  // 2. Set district & ward
  const distEl = document.getElementById('manualDistrict');
  const wardEl = document.getElementById('manualWard');
  if (distEl) {
    distEl.value = district;
  }
  updateManualWardsDropdown(district);
  if (wardEl) {
    wardEl.value = displayLabel;
  }

  // 3. Update notice
  updateMergerNoticeBadge(district, displayLabel);

  // 4. Close modal
  closeMergerLookupModal();

  // 5. Toast
  showToast('Đã áp dụng ' + displayLabel + ' (' + district + ') vào Form Nhập Tay!', '📍');

  // 6. Sync to raw
  syncManualToRaw();
}

