// 15B. LOCAL STORAGE MULTI-PROPERTIES MANAGER (KHO LƯU BẢN THẢO NHÀ)
// ==========================================
const STORAGE_KEY_PROPERTIES = 'auto_video_saved_properties';
const STORAGE_KEY_ACTIVE_ID = 'auto_video_active_property_id';

const SAMPLE_2_RAW_DATA = `Biệt thự sân vườn Thảo Điền
200m² đất (10m x 20m)
Giá 50 tỷ
Phường Thảo Điền, TP Thủ Đức
Đường ô tô tránh nhau 8m
3 tầng + hồ bơi riêng + gara ô tô
5 phòng ngủ, 6 WC, sân vườn xanh mát
Nội thất nhập khẩu Châu Âu cao cấp
Khu chuyên gia nước ngoài, an ninh 24/7, gần trường Quốc tế BIS
Sổ hồng chính chủ, hoàn công đầy đủ
Hướng Đông Nam`;

function getDefaultSampleProperties() {
  const prop1Data = extractPropertyData(SAMPLE_RAW_DATA);
  const prop2Data = extractPropertyData(SAMPLE_2_RAW_DATA);

  return [
    {
      id: 'prop_sample_nguyen_kiem',
      title: 'Nhà phố 15 phòng Nguyễn Kiệm, Phú Nhuận (Dòng tiền 30tr/tháng - 25 tỷ)',
      createdAt: new Date(Date.now() - 86400000 * 2).toISOString(),
      updatedAt: new Date(Date.now() - 86400000 * 2).toISOString(),
      notes: 'Đang cho thuê khoán 30tr/tháng, 1 trệt 2 lầu rooftop, hẻm xe hơi 10m ra mặt tiền, thích hợp khách mua giữ tiền.',
      inputMode: 'raw',
      rawText: SAMPLE_RAW_DATA,
      propertyData: prop1Data,
      style: 'talking_numbers',
      duration: 60,
      pace: 'standard'
    },
    {
      id: 'prop_sample_thao_dien',
      title: 'Biệt thự sân vườn Thảo Điền, TP Thủ Đức (200m², Ngang 10m - 50 tỷ)',
      createdAt: new Date(Date.now() - 86400000).toISOString(),
      updatedAt: new Date(Date.now() - 86400000).toISOString(),
      notes: 'Biệt thự sân vườn xanh mát Thảo Điền, 5PN 6WC, hồ bơi riêng, khu chuyên gia nước ngoài, an ninh 24/7.',
      inputMode: 'raw',
      rawText: SAMPLE_2_RAW_DATA,
      propertyData: prop2Data,
      style: 'storytelling',
      duration: 45,
      pace: 'relaxed'
    }
  ];
}

function getSavedProperties() {
  if (typeof localStorage === 'undefined') {
    if (!AppState.savedProperties) {
      AppState.savedProperties = getDefaultSampleProperties();
    }
    return AppState.savedProperties;
  }
  try {
    const raw = localStorage.getItem(STORAGE_KEY_PROPERTIES);
    if (raw === null) {
      const samples = getDefaultSampleProperties();
      localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify(samples));
      AppState.savedProperties = samples;
      return samples;
    }
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) {
      const samples = getDefaultSampleProperties();
      localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify(samples));
      AppState.savedProperties = samples;
      return samples;
    }
    AppState.savedProperties = parsed;
    return parsed;
  } catch (e) {
    console.warn('Error reading saved properties from localStorage:', e);
    const samples = getDefaultSampleProperties();
    AppState.savedProperties = samples;
    return samples;
  }
}

function savePropertiesList(list) {
  if (!Array.isArray(list)) list = [];
  AppState.savedProperties = list;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_PROPERTIES, JSON.stringify(list));
    } catch (e) {
      console.error('Failed to save to localStorage:', e);
      if (typeof showToast === 'function') {
        showToast('Lỗi dung lượng bộ nhớ khi lưu!', '⚠️');
      }
    }
  }
  updateSavedPropertiesBadge();
}

function updateSavedPropertiesBadge() {
  if (typeof document === 'undefined') return;
  const list = getSavedProperties();
  const count = Array.isArray(list) ? list.length : 0;

  const badge = document.getElementById('savedPropertiesCountBadge');
  if (badge) badge.textContent = String(count);

  const navBadge = document.getElementById('navSavedPropsBadge');
  if (navBadge) navBadge.textContent = String(count);

  const countText = document.getElementById('savedPropsCountText');
  if (countText) {
    countText.textContent = `Đang có ${count} căn nhà trong kho lưu trữ`;
  }
}

function populateSavedPropsDistrictFilter() {
  if (typeof document === 'undefined') return;
  const select = document.getElementById('savedPropDistrictFilter');
  if (!select) return;
  const currentVal = select.value || 'ALL';
  const list = getSavedProperties();
  const districts = new Set();
  list.forEach(p => {
    const d = (p.propertyData && p.propertyData.location && p.propertyData.location.district) || '';
    if (d && d.trim()) districts.add(d.trim());
  });

  const optionsHtml = ['<option value="ALL">Tất cả Quận / Huyện</option>'].concat(
    Array.from(districts).sort().map(d => `<option value="${escapeHtml(d)}">${escapeHtml(d)}</option>`)
  ).join('');

  select.innerHTML = optionsHtml;
  if (districts.has(currentVal)) {
    select.value = currentVal;
  } else {
    select.value = 'ALL';
  }
}

function renderSavedPropertiesList(filterDistrict, query) {
  if (typeof document === 'undefined') return;
  const container = document.getElementById('savedPropsList');
  if (!container) return;

  const distSelect = document.getElementById('savedPropDistrictFilter');
  const searchInput = document.getElementById('savedPropSearchInput');
  const activeDist = filterDistrict !== undefined ? filterDistrict : (distSelect ? distSelect.value : 'ALL');
  const activeQuery = query !== undefined ? query : (searchInput ? searchInput.value.trim().toLowerCase() : '');

  const list = getSavedProperties();

  let filtered = list;
  if (activeDist && activeDist !== 'ALL') {
    filtered = filtered.filter(p => {
      const d = (p.propertyData && p.propertyData.location && p.propertyData.location.district) || '';
      return d.toLowerCase() === activeDist.toLowerCase();
    });
  }
  if (activeQuery) {
    filtered = filtered.filter(p => {
      const matchTitle = (p.title || '').toLowerCase().includes(activeQuery);
      const matchNotes = (p.notes || '').toLowerCase().includes(activeQuery);
      const matchRaw = (p.rawText || '').toLowerCase().includes(activeQuery);
      const matchStreet = (p.propertyData && p.propertyData.location && p.propertyData.location.street || '').toLowerCase().includes(activeQuery);
      const matchDistrict = (p.propertyData && p.propertyData.location && p.propertyData.location.district || '').toLowerCase().includes(activeQuery);
      return matchTitle || matchNotes || matchRaw || matchStreet || matchDistrict;
    });
  }

  const countText = document.getElementById('savedPropsCountText');
  if (countText) {
    countText.textContent = `Hiển thị ${filtered.length} / ${list.length} căn nhà`;
  }

  if (filtered.length === 0) {
    container.innerHTML = `
      <div class="saved-prop-empty">
        <div style="font-size: 2.2rem;">🏚️</div>
        <div style="font-size: 0.95rem; font-weight: 600; color: #94a3b8;">Không tìm thấy căn nhà nào phù hợp bộ lọc</div>
        <div style="font-size: 0.8rem; color: #64748b;">Bạn có thể lưu thông tin căn đang mở hoặc xóa bộ lọc tìm kiếm.</div>
        <button type="button" class="btn-secondary" onclick="openSaveCurrentModal()" style="margin-top: 0.4rem;">
          ➕ Lưu căn đang mở vào kho
        </button>
      </div>
    `;
    return;
  }

  container.innerHTML = filtered.map(item => {
    const isCurrentlyActive = AppState.currentSavedPropertyId === item.id;
    const pData = item.propertyData || {};
    const loc = pData.location || {};
    const area = pData.area || {};
    const price = pData.price || {};
    const rooms = pData.rooms || {};
    const structure = pData.structure || {};
    const exploit = pData.exploitation || {};

    const priceText = price.askingPrice ? `${price.askingPrice}` : 'Chưa rõ giá';
    const locText = [loc.street, loc.ward, loc.district].filter(Boolean).join(', ') || 'Chưa rõ địa chỉ';
    const rawAreaMatch = (item.rawText && item.rawText.match(/(\d+[\.,]?\d*)\s*m²/)) ? item.rawText.match(/(\d+[\.,]?\d*)\s*m²/)[1] : null;
    const areaText = area.landArea ? `${area.landArea}m²` : (rawAreaMatch ? `${rawAreaMatch}m²` : '');
    const roomLabel = rooms.bedrooms ? `${rooms.bedrooms}PN` : (rooms.totalRooms ? `${rooms.totalRooms}P` : '');
    const wcLabel = rooms.bathrooms ? `${rooms.bathrooms}WC` : '';
    const roomsPart = [roomLabel, wcLabel].filter(Boolean).join(' ');
    const structText = structure.floorDescription || ((structure.floors ? `${structure.floors} tầng` : '') + (roomsPart ? ` • ${roomsPart}` : ''));
    const rentText = exploit.monthlyRent ? `Dòng tiền: ${exploit.monthlyRent}` : '';
    const styleName = (STYLE_DEFINITIONS[item.style] && STYLE_DEFINITIONS[item.style].name) || 'Mặc định';
    const durationText = item.duration ? `${item.duration}s` : '60s';

    const dateStr = item.updatedAt ? new Date(item.updatedAt).toLocaleDateString('vi-VN', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';

    return `
      <div class="saved-prop-card ${isCurrentlyActive ? 'active-loaded' : ''}" id="card_${item.id}">
        <div class="saved-prop-card-header">
          <div>
            <div class="saved-prop-title">
              ${isCurrentlyActive ? '<span style="color: #38bdf8; font-size: 0.74rem; font-weight: 800; background: rgba(56, 189, 248, 0.15); padding: 0.15rem 0.4rem; border-radius: 4px; margin-right: 4px;">ĐANG MỞ</span>' : ''}
              ${escapeHtml(item.title || 'Căn nhà chưa đặt tên')}
            </div>
            <div class="saved-prop-date">🕒 Cập nhật: ${dateStr}</div>
          </div>
        </div>

        <div class="saved-prop-specs">
          <span class="spec-pill price">💰 ${escapeHtml(priceText)}</span>
          <span class="spec-pill location">📍 ${escapeHtml(locText)}</span>
          ${areaText ? `<span class="spec-pill">📐 ${escapeHtml(areaText)}</span>` : ''}
          ${structText ? `<span class="spec-pill">🏠 ${escapeHtml(structText)}</span>` : ''}
          ${rentText ? `<span class="spec-pill" style="background: rgba(245, 158, 11, 0.15); color: #fbbf24; border-color: rgba(245, 158, 11, 0.3);">💵 ${escapeHtml(rentText)}</span>` : ''}
          <span class="spec-pill" style="background: rgba(168, 85, 247, 0.12); color: #c084fc; border-color: rgba(168, 85, 247, 0.3);">🎭 ${escapeHtml(styleName)}</span>
          <span class="spec-pill">⏱️ ${escapeHtml(durationText)}</span>
        </div>

        ${item.notes ? `<div class="saved-prop-notes">📝 ${escapeHtml(item.notes)}</div>` : ''}

        <div class="saved-prop-actions">
          <button type="button" class="btn-prop-load" onclick="loadSavedProperty('${item.id}')" title="Nạp căn nhà này vào hệ thống tạo video">
            📂 Mở căn này
          </button>
          <button type="button" class="btn-secondary" style="padding: 0.4rem 0.65rem; font-size: 0.76rem; color: #34d399; border-color: rgba(16, 185, 129, 0.4);" onclick="closeSavedPropertiesModal(); openPostingChecklistForProperty('${item.id}')" title="Xem tiến độ đăng các nền tảng của căn nhà này">
            ✅ Checklist
          </button>
          <button type="button" class="btn-secondary" style="padding: 0.4rem 0.65rem; font-size: 0.76rem;" onclick="copySavedPropertyRaw('${item.id}')" title="Sao chép nội dung thông tin thô">
            📋 Copy thô
          </button>
          <button type="button" class="btn-secondary" style="padding: 0.4rem 0.65rem; font-size: 0.76rem; color: #ef4444; border-color: rgba(239, 68, 68, 0.3);" onclick="deleteSavedProperty('${item.id}')" title="Xóa căn này khỏi kho">
            🗑️ Xóa
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function copySavedPropertyRaw(id) {
  const list = getSavedProperties();
  const item = list.find(p => p.id === id);
  if (!item) return;
  copyTextToClipboard(item.rawText || '', 'thông tin thô của căn nhà');
}

function openSavedPropertiesModal() {
  if (typeof document === 'undefined') return;
  const ws = document.getElementById('subsystemSavedPropsWorkspace');
  if (ws && ws.style.display !== 'flex' && typeof switchSubsystem === 'function') {
    switchSubsystem('savedprops');
  }
  const modal = document.getElementById('savedPropertiesModal');
  if (!modal) return;
  populateSavedPropsDistrictFilter();
  renderSavedPropertiesList();
  modal.classList.add('open');
  modal.classList.add('visible');
  modal.style.display = 'flex';
}

function closeSavedPropertiesModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('savedPropertiesModal');
  if (!modal) return;
  modal.classList.remove('open');
  modal.classList.remove('visible');
  modal.style.display = 'none';
  const ws = document.getElementById('subsystemSavedPropsWorkspace');
  if (ws) ws.style.display = 'none';
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('dashboard');
  }
}

function openSaveCurrentModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('saveCurrentPropertyModal');
  if (!modal) return;

  let prop = AppState.currentPropertyData;
  let rawText = '';
  if (AppState.currentInputTab === 'manual') {
    try {
      prop = collectManualFormData();
      const rawEl = document.getElementById('rawInfoInput');
      rawText = rawEl ? rawEl.value : '';
    } catch (e) {}
  } else {
    const rawEl = document.getElementById('rawInfoInput');
    rawText = rawEl ? rawEl.value : '';
    if (!prop && rawText.trim()) {
      try {
        prop = extractPropertyData(rawText);
      } catch (e) {}
    }
  }

  const activeId = AppState.currentSavedPropertyId;
  const list = getSavedProperties();
  const existingProp = activeId ? list.find(p => p.id === activeId) : null;

  const titleInput = document.getElementById('savePropTitleInput');
  const noteInput = document.getElementById('savePropNoteInput');
  const btnUpdate = document.getElementById('btnUpdateExistingProp');
  const badge = document.getElementById('savePropSummaryBadge');

  if (existingProp) {
    if (titleInput) titleInput.value = existingProp.title;
    if (noteInput) noteInput.value = existingProp.notes || '';
    if (btnUpdate) {
      btnUpdate.style.display = 'inline-flex';
      btnUpdate.innerHTML = '🔄 Cập nhật căn này';
    }
  } else {
    let autoTitle = 'Căn nhà mới';
    if (prop) {
      const street = (prop.location && prop.location.street) || '';
      const dist = (prop.location && prop.location.district) || '';
      const area = (prop.area && prop.area.landArea) ? `${prop.area.landArea}m²` : '';
      const price = (prop.price && prop.price.askingPrice) ? `${prop.price.askingPrice}` : '';
      const parts = [];
      if (street || dist) parts.push([street, dist].filter(Boolean).join(', '));
      if (area) parts.push(area);
      if (price) parts.push(`(${price})`);
      if (parts.length > 0) autoTitle = parts.join(' - ');
    }
    if (titleInput) titleInput.value = autoTitle;
    if (noteInput) noteInput.value = '';
    if (btnUpdate) btnUpdate.style.display = 'none';
  }

  if (badge) {
    const loc = (prop && prop.location && prop.location.street) ? `${prop.location.street}${prop.location.district ? ', ' + prop.location.district : ''}` : 'Chưa có vị trí';
    const pr = (prop && prop.price && prop.price.askingPrice) ? prop.price.askingPrice : 'Chưa có giá';
    const ar = (prop && prop.area && prop.area.landArea) ? `${prop.area.landArea}m²` : 'Chưa có DT';
    const styleName = (STYLE_DEFINITIONS[AppState.currentStyle] && STYLE_DEFINITIONS[AppState.currentStyle].name) || 'Data Selling';
    const paceName = getPaceLabel(AppState.currentPace);

    badge.innerHTML = `
      <div><strong>Vị trí & Giá:</strong> ${escapeHtml(loc)} • 💰 <span style="color:#34d399; font-weight:700;">${escapeHtml(pr)}</span> • 📐 ${escapeHtml(ar)}</div>
      <div style="font-size: 0.74rem; color: #64748b;"><strong>Kịch bản:</strong> ${escapeHtml(styleName)} • ⏱️ ${AppState.currentDuration}s (${escapeHtml(paceName)})</div>
    `;
  }

  modal.classList.add('open');
  modal.classList.add('visible');
  modal.style.display = 'flex';
  if (titleInput) titleInput.focus();
}

function closeSaveCurrentModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('saveCurrentPropertyModal');
  if (!modal) return;
  modal.classList.remove('open');
  modal.classList.remove('visible');
  modal.style.display = 'none';
}

function savePropertyConfirmed(isUpdate) {
  const titleInput = document.getElementById('savePropTitleInput');
  const noteInput = document.getElementById('savePropNoteInput');
  const title = (titleInput && titleInput.value.trim()) || ('Căn nhà ' + new Date().toLocaleDateString('vi-VN'));
  const notes = (noteInput && noteInput.value.trim()) || '';

  let rawText = '';
  const rawEl = document.getElementById('rawInfoInput');
  if (rawEl && rawEl.value.trim()) {
    rawText = rawEl.value.trim();
  } else if (AppState.currentInputTab === 'manual') {
    try {
      collectManualFormData();
      if (rawEl && rawEl.value.trim()) rawText = rawEl.value.trim();
    } catch (e) {}
  }
  if (!rawText) rawText = SAMPLE_RAW_DATA;

  let propData = AppState.currentPropertyData;
  if (!propData) {
    try {
      propData = extractPropertyData(rawText);
    } catch (e) {
      propData = {};
    }
  }

  const list = getSavedProperties();

  if (isUpdate && AppState.currentSavedPropertyId) {
    const idx = list.findIndex(p => p.id === AppState.currentSavedPropertyId);
    if (idx !== -1) {
      list[idx].title = title;
      list[idx].notes = notes;
      list[idx].rawText = rawText;
      list[idx].propertyData = propData;
      list[idx].style = AppState.currentStyle;
      list[idx].duration = AppState.currentDuration;
      list[idx].pace = AppState.currentPace;
      list[idx].updatedAt = new Date().toISOString();
      savePropertiesList(list);
      showToast(`Đã cập nhật căn "${title}"!`, '🔄');
      closeSaveCurrentModal();
      populateSavedPropsDistrictFilter();
      renderSavedPropertiesList();
      return;
    }
  }

  const newId = 'prop_' + Date.now() + '_' + Math.random().toString(36).substring(2, 7);
  const newEntry = {
    id: newId,
    title,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    notes,
    inputMode: AppState.currentInputTab,
    rawText,
    propertyData: propData,
    style: AppState.currentStyle,
    duration: AppState.currentDuration,
    pace: AppState.currentPace
  };

  list.unshift(newEntry);
  AppState.currentSavedPropertyId = newId;
  savePropertiesList(list);
  showToast(`Đã lưu "${title}" vào kho bản thảo!`, '💾');
  closeSaveCurrentModal();
  populateSavedPropsDistrictFilter();
  renderSavedPropertiesList();
}

function loadSavedProperty(id) {
  const list = getSavedProperties();
  const item = list.find(p => p.id === id);
  if (!item) {
    showToast('Không tìm thấy căn nhà được chọn!', '⚠️');
    return;
  }

  AppState.currentSavedPropertyId = item.id;

  if (item.duration) AppState.currentDuration = item.duration;
  if (item.pace) AppState.currentPace = item.pace;
  updateDurationUI();

  if (item.style && STYLE_DEFINITIONS[item.style]) {
    AppState.currentStyle = item.style;
    const styleSel = document.getElementById('userSelectedStyle');
    if (styleSel) styleSel.value = item.style;
    const modeUser = document.getElementById('styleModeUser');
    if (modeUser) modeUser.checked = true;
    const modeAi = document.getElementById('styleModeAi');
    if (modeAi) modeAi.checked = false;
    AppState.styleMode = 'user';
  }

  const rawInput = document.getElementById('rawInfoInput');
  if (rawInput && item.rawText) {
    rawInput.value = item.rawText;
  }

  if (item.propertyData) {
    fillManualFormFromPropertyData(item.propertyData);
  }

  switchInputTab(item.inputMode || 'raw');
  handleAnalyzeAndGenerate();

  if (item.style && STYLE_DEFINITIONS[item.style]) {
    changeVideoStyle(item.style);
  }

  closeSavedPropertiesModal();

  showToast(`Đã nạp thành công căn: ${item.title}`, '📂');
}

function deleteSavedProperty(id) {
  const list = getSavedProperties();
  const item = list.find(p => p.id === id);
  const itemName = item ? item.title : 'căn nhà này';

  if (typeof confirm === 'function') {
    const ok = confirm(`Bạn có chắc chắn muốn xóa "${itemName}" khỏi kho lưu trữ?`);
    if (!ok) return;
  }

  const updatedList = list.filter(p => p.id !== id);
  if (AppState.currentSavedPropertyId === id) {
    AppState.currentSavedPropertyId = null;
  }
  savePropertiesList(updatedList);
  populateSavedPropsDistrictFilter();
  renderSavedPropertiesList();
  showToast(`Đã xóa "${itemName}" khỏi kho!`, '🗑️');
}

function clearAllSavedProperties() {
  if (typeof confirm === 'function') {
    const ok = confirm('CẢNH BÁO: Bạn có chắc chắn muốn xóa TOÀN BỘ kho nhà đã lưu? Thao tác này sẽ xóa sạch dữ liệu trên trình duyệt!');
    if (!ok) return;
  }

  AppState.currentSavedPropertyId = null;
  savePropertiesList([]);
  populateSavedPropsDistrictFilter();
  renderSavedPropertiesList();
  showToast('Đã dọn sạch toàn bộ kho nhà!', '🧹');
}

function exportSavedPropertiesJson() {
  const list = getSavedProperties();
  const count = list.length;
  const jsonStr = JSON.stringify(list, null, 2);
  const blob = new Blob([jsonStr], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const dateTag = new Date().toISOString().slice(0, 10);
  a.href = url;
  a.download = `auto_video_kho_nha_${dateTag}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast(`Đã xuất file sao lưu (${count} căn nhà)!`, '⬇️');
}

function importSavedPropertiesJson(event) {
  const file = event.target && event.target.files && event.target.files[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const content = e.target.result;
      const imported = JSON.parse(content);
      if (!Array.isArray(imported)) {
        showToast('File JSON không hợp lệ (không phải mảng danh sách căn nhà)!', '❌');
        return;
      }

      const currentList = getSavedProperties();
      const currentIds = new Set(currentList.map(p => p.id));
      let addedCount = 0;
      let updatedCount = 0;

      imported.forEach(item => {
        if (!item.id || !item.title) return;
        if (currentIds.has(item.id)) {
          const idx = currentList.findIndex(p => p.id === item.id);
          if (idx !== -1) {
            currentList[idx] = item;
            updatedCount++;
          }
        } else {
          currentList.push(item);
          addedCount++;
        }
      });

      savePropertiesList(currentList);
      populateSavedPropsDistrictFilter();
      renderSavedPropertiesList();
      showToast(`Đã phục hồi: Thêm mới ${addedCount}, Cập nhật ${updatedCount} căn!`, '⬆️');
    } catch (err) {
      console.error(err);
      showToast('Lỗi khi đọc file JSON sao lưu!', '❌');
    } finally {
      if (event.target) event.target.value = '';
    }
  };
  reader.readAsText(file);
}

