function determineAutoFormula(prop) {
  if (!prop) return 'aida';
  const priceValNum = (prop.price && (prop.price.priceValue || parseFloat(prop.price.askingPrice))) || 0;
  const nh = prop.newHouseFeatures || {};
  const isLuxury = (priceValNum >= 20) || nh.hasElevator || nh.handover === 'full_interior';
  const hasCashflow = (prop.exploitation && prop.exploitation.monthlyRent) || (prop.financial && prop.financial.rentalIncome) || (prop.rooms && (prop.rooms.totalRooms >= 6 || prop.rooms.bedrooms >= 6)) || (prop.features && prop.features.rooms >= 6);
  const isUrgent = prop.price && (prop.price.isNegotiable || prop.price.urgentSale);

  if (isLuxury) return 'four_p';
  if (hasCashflow) return 'fab';
  if (isUrgent) return 'pas';
  if ((prop.alley && prop.alley.isCarAccessible) || (prop.access && (prop.access.carAccessible || prop.access.alleyWidth >= 4))) return 'bab';
  return 'aida';
}

function determineAutoPsychology(prop) {
  if (!prop) return 'tham';
  const nh = prop.newHouseFeatures || {};
  const price = (prop.price && (prop.price.priceValue || parseFloat(prop.price.askingPrice))) || 0;

  if (price >= 20 || nh.hasElevator || nh.hasSkyGarden || nh.hasSauna || nh.handover === 'full_interior') {
    return 'ngao_man';
  }
  if ((prop.exploitation && prop.exploitation.monthlyRent) || (prop.financial && prop.financial.rentalIncome) || nh.giftInterior || (prop.dimensions && prop.dimensions.width >= 7)) {
    return 'tham';
  }
  if (prop.dimensions && prop.dimensions.width && prop.dimensions.length && ((prop.alley && prop.alley.isCarAccessible) || (prop.access && prop.access.carAccessible))) {
    return 'san';
  }
  if (prop.legal && (prop.legal.hasCompletion || prop.legal.hasCompletedDocs)) {
    return 'nghi_ngo';
  }
  return 'si';
}

function getPropertyDisplayFacts(prop) {
  if (!prop) return {};

  const street = prop.location && prop.location.street ? prop.location.street : 'Trung tâm';
  let ward = prop.location && prop.location.ward ? prop.location.ward : '';
  const district = prop.location && prop.location.district ? prop.location.district : 'TP.HCM';
  const fullAddress = [street, ward, district].filter(Boolean).join(', ');

  const width = prop.dimensions && prop.dimensions.width ? prop.dimensions.width : null;
  const length = prop.dimensions && prop.dimensions.length ? prop.dimensions.length : null;
  const rearW = prop.dimensions && prop.dimensions.rearWidth ? prop.dimensions.rearWidth : null;
  const dimensionStr = width && length ? `${width}m${rearW ? ` (nở hậu ${rearW}m)` : ''} x ${length}m` : (width ? `Ngang ${width}m` : '');

  const landArea = prop.area && prop.area.landArea ? `${prop.area.landArea}m²` : '';
  const totalFloor = prop.area && prop.area.totalFloorArea ? `${prop.area.totalFloorArea}m²` : '';
  
  const floors = (prop.structure && (prop.structure.floorDescription || (prop.structure.floors ? `${prop.structure.floors} tầng` : ''))) || (prop.floors && (prop.floors.description || (prop.floors.numFloors ? `${prop.floors.numFloors} tầng` : ''))) || '';
  
  let rooms = '';
  const bedroomCount = (prop.rooms && prop.rooms.bedrooms) || null;
  const totalRoomsCount = (prop.rooms && prop.rooms.totalRooms) || (prop.features && prop.features.rooms) || null;
  if (bedroomCount) {
    rooms = `${bedroomCount} phòng ngủ`;
  } else if (totalRoomsCount) {
    rooms = `${totalRoomsCount} phòng`;
  }

  let wc = '';
  const wcCount = (prop.rooms && prop.rooms.bathrooms) || (prop.features && prop.features.wc) || null;
  if (wcCount) {
    wc = `${wcCount} WC`;
  }

  let priceVal = 'Giá thương lượng';
  if (prop.price && (prop.price.priceValue !== null || prop.price.askingPrice)) {
    if (prop.price.priceValue !== null && prop.price.priceValue !== undefined) {
      if (prop.price.priceValue >= 1) {
        priceVal = `${prop.price.priceValue} Tỷ`;
      } else if (prop.price.priceValue > 0) {
        priceVal = `${Math.round(prop.price.priceValue * 1000)} Triệu`;
      }
    } else if (prop.price.askingPrice) {
      const rawP = String(prop.price.askingPrice).trim();
      if (/tỷ|tỉ/i.test(rawP)) {
        priceVal = rawP.replace(/\s*(?:tỷ|tỉ)$/i, '') + ' Tỷ';
      } else if (/triệu|tr/i.test(rawP)) {
        priceVal = rawP.replace(/\s*(?:triệu|tr)$/i, '') + ' Triệu';
      } else {
        priceVal = `${rawP} Tỷ`;
      }
    }
  }

  const pricePerM2 = prop.price && prop.price.pricePerM2 ? `${prop.price.pricePerM2} tr/m²` : '';
  const rental = (prop.exploitation && prop.exploitation.monthlyRent) || (prop.financial && prop.financial.rentalIncome) || '';

  const alley = (prop.alley && prop.alley.type) || (prop.access && prop.access.alleyDescription) || (prop.alley && prop.alley.isCarAccessible ? 'Hẻm xe hơi thông thoáng' : 'Hẻm sạch sẽ an ninh');
  const distance = (prop.alley && prop.alley.distanceToStreet) ? (prop.alley.distanceToStreet.startsWith('Cách') ? prop.alley.distanceToStreet : `Cách mặt tiền ${prop.alley.distanceToStreet}`) : (prop.access && prop.access.distanceToMainRoad ? `Cách mặt tiền ${prop.access.distanceToMainRoad}m` : '');

  const nh = prop.newHouseFeatures || {};
  const highlightFeatures = [];
  if (nh.isNew100) highlightFeatures.push('Nhà mới 100% chưa qua sử dụng');
  if (nh.hasElevator) highlightFeatures.push(`Thang máy nhập khẩu ${nh.elevatorType || 'cao cấp'}`);
  if (nh.handover === 'full_interior') highlightFeatures.push('Full nội thất cao cấp chỉ xách vali vào ở');
  if (nh.giftInterior) highlightFeatures.push('Tặng lại toàn bộ nội thất cho khách thiện chí');
  if (nh.hasGarageInside) highlightFeatures.push('Gara ô tô rộng rãi trong nhà');
  if (nh.hasSkyGarden) highlightFeatures.push('Sky Garden sân thượng view cực chill');
  if (nh.hasMasterCloset) highlightFeatures.push('Phòng Master khép kín phong cách hiện đại');
  if (nh.hasSmartHome) highlightFeatures.push('Trang bị hệ thống Smart Home thông minh');

  const legalDoc = (prop.legal && prop.legal.documentType) || 'Sổ hồng riêng';
  const hasComp = Boolean((prop.legal && (prop.legal.hasCompletion || prop.legal.hasCompletedDocs)) || nh.hasCompletionDone);
  const legalStr = hasComp ? `${legalDoc}, đã hoàn công đầy đủ, công chứng ngay` : `${legalDoc} chính chủ, pháp lý chuẩn chỉnh`;
  const orientation = (prop.orientation && prop.orientation.direction) ? (prop.orientation.direction.toLowerCase().startsWith('hướng') ? prop.orientation.direction : `Hướng ${prop.orientation.direction}`) : '';

  return {
    street,
    ward,
    district,
    fullAddress,
    dimensionStr,
    width,
    length,
    landArea,
    totalFloor,
    floors,
    rooms,
    wc,
    priceVal,
    pricePerM2,
    rental,
    alley,
    distance,
    orientation,
    highlightFeatures,
    legalStr,
    nh
  };
}

