function switchProfileSubtab(mode) {
  const btnAll = document.getElementById('btnSubtabAll');
  const btnBroker = document.getElementById('btnSubtabBroker');
  const btnAuthor = document.getElementById('btnSubtabAuthor');
  const btnRecruit = document.getElementById('btnSubtabRecruit');
  const brokerSec = document.getElementById('profileBrokerSection');
  const authorSec = document.getElementById('profileAuthorSection');
  const recruitSec = document.getElementById('profileRecruitSection');

  if (btnAll) btnAll.classList.remove('active');
  if (btnBroker) btnBroker.classList.remove('active');
  if (btnAuthor) btnAuthor.classList.remove('active');
  if (btnRecruit) btnRecruit.classList.remove('active');

  if (mode === 'broker') {
    if (btnBroker) btnBroker.classList.add('active');
    if (brokerSec) brokerSec.style.display = 'grid';
    if (authorSec) authorSec.style.display = 'none';
    if (recruitSec) recruitSec.style.display = 'none';
  } else if (mode === 'author') {
    if (btnAuthor) btnAuthor.classList.add('active');
    if (brokerSec) brokerSec.style.display = 'none';
    if (authorSec) authorSec.style.display = 'block';
    if (recruitSec) recruitSec.style.display = 'none';
  } else if (mode === 'recruit') {
    if (btnRecruit) btnRecruit.classList.add('active');
    if (brokerSec) brokerSec.style.display = 'none';
    if (authorSec) authorSec.style.display = 'none';
    if (recruitSec) recruitSec.style.display = 'block';
  } else {
    if (btnAll) btnAll.classList.add('active');
    if (brokerSec) brokerSec.style.display = 'grid';
    if (authorSec) authorSec.style.display = 'block';
    if (recruitSec) recruitSec.style.display = 'block';
  }
}

function openRecruitSection() {
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('profile');
  }
  if (typeof switchProfileSubtab === 'function') {
    switchProfileSubtab('recruit');
  }
  if (typeof document !== 'undefined') {
    const el = document.getElementById('profileRecruitSection');
    if (el && typeof el.scrollIntoView === 'function') {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}


