let currentArsenalContext = 'video'; // 'video' hoặc 'copywriting'
let currentLegalCategory = 'ALL';
let currentStoryCategory = 'ALL';

function openLegalHookModal(context = 'video') {
  currentArsenalContext = context;
  renderLegalHooksList();
  const m = document.getElementById('legalHookModal');
  if (m) m.style.display = 'flex';
}

function closeLegalHookModal() {
  const m = document.getElementById('legalHookModal');
  if (m) m.style.display = 'none';
}

function filterLegalHooks(cat) {
  currentLegalCategory = cat;
  const btns = document.querySelectorAll('#legalHookFilterBar .arsenal-filter-btn');
  btns.forEach(b => {
    if (b.textContent.includes(cat) || (cat === 'ALL' && b.textContent.includes('Tất Cả'))) {
      b.classList.add('active');
    } else {
      b.classList.remove('active');
    }
  });
  renderLegalHooksList();
}

function renderLegalHooksList() {
  const wrap = document.getElementById('legalHooksListWrap');
  if (!wrap) return;
  const filtered = currentLegalCategory === 'ALL' 
    ? LEGAL_HOOKS_2026 
    : LEGAL_HOOKS_2026.filter(item => item.cat === currentLegalCategory);

  wrap.innerHTML = filtered.map(item => {
    const isSelected = AppState.selectedLegalHookId === item.id;
    return `
      <div class="arsenal-card ${isSelected ? 'active-selected' : ''}">
        <div class="arsenal-card-header">
          <span class="arsenal-card-badge gold">${item.icon} ${item.cat}</span>
          <span style="font-size: 0.74rem; color: #94a3b8;">${item.tag}</span>
        </div>
        <div class="arsenal-card-hook">"${item.hook}"</div>
        <div class="arsenal-card-sub">${item.sub}</div>
        <div class="arsenal-card-actions">
          <button type="button" class="btn-arsenal-act apply-video" onclick="applyLegalHook('${item.id}', 'video')">
            <span>🎬</span> Dùng Cho Video
          </button>
          <button type="button" class="btn-arsenal-act apply-copy" onclick="applyLegalHook('${item.id}', 'copywriting')">
            <span>✍️</span> Dùng Cho Bài Viết
          </button>
          <button type="button" class="btn-arsenal-act copy-btn" onclick="copyArsenalText('${item.hook.replace(/'/g, "\\'")}')">
            <span>📋</span> Copy Hook
          </button>
        </div>
      </div>
    `;
  }).join('');
}

function applyLegalHook(hookId, targetContext) {
  const item = LEGAL_HOOKS_2026.find(x => x.id === hookId);
  if (!item) return;

  AppState.selectedLegalHookId = hookId;
  AppState.selectedLegalHook = item.hook;

  closeLegalHookModal();

  if (targetContext === 'video') {
    // Switch to video and auto-select legal style
    if (typeof switchSubsystem === 'function') switchSubsystem('video');
    const styleSel = document.getElementById('userSelectedStyle');
    if (styleSel) {
      styleSel.value = 'legal_law2026';
    }
    const rUser = document.getElementById('styleModeUser');
    if (rUser) {
      rUser.checked = true;
      if (typeof onStyleModeChange === 'function') onStyleModeChange();
    }
    showToast('⚖️ Đã nạp Hook Pháp Luật 2026 vào Kịch Bản Video!', '🎬');
    if (typeof generateScripts === 'function') generateScripts();
  } else {
    // Switch to copywriting
    if (typeof switchSubsystem === 'function') switchSubsystem('copywriting');
    showToast('⚖️ Đã nạp Hook Pháp Luật 2026 vào Bài Viết MXH!', '✍️');
    if (typeof renderCopywritingWorkspace === 'function') renderCopywritingWorkspace();
  }
}

