function applyDamaging(dmgId, targetContext) {
  const item = DAMAGING_ADMISSION_STORIES.find(d => d.id === dmgId);
  if (!item) return;

  AppState.selectedDamagingId = dmgId;
  AppState.selectedDamagingHook = item.hook;
  AppState.selectedDamagingItem = item;

  closeDamagingModal();

  if (targetContext === 'video') {
    if (typeof switchSubsystem === 'function') switchSubsystem('video');
    const styleSel = document.getElementById('userSelectedStyle');
    if (styleSel) styleSel.value = 'damaging_admission';
    const rUser = document.getElementById('styleModeUser');
    if (rUser) {
      rUser.checked = true;
      if (typeof onStyleModeChange === 'function') onStyleModeChange();
    }
    showToast('🥊 Đã nạp Phong Cách Chê Nhược Điểm vào Video!', '🔥');
    if (typeof generateScripts === 'function') generateScripts();
  } else {
    if (typeof switchSubsystem === 'function') switchSubsystem('copywriting');
    if (typeof selectCopyPsychology === 'function') selectCopyPsychology('damaging');
    showToast('🥊 Đã nạp Phong Cách Chê Nhược Điểm vào Bài Viết!', '🔥');
  }
}

function copyArsenalText(txt) {
  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(txt).then(() => {
      showToast('📋 Đã copy vào bộ nhớ tạm!', '✨');
    }).catch(() => {
      showToast('📋 Đã chọn nội dung!', '✨');
    });
  } else {
    showToast('📋 Đã chọn nội dung!', '✨');
  }
}


// ========================================================
// CONTROLLER: CẨM NANG HƯỚNG DẪN SỬ DỤNG (GUIDE WORKSPACE)
// ========================================================
function switchGuideTab(tabKey) {
  const tabs = ['quick', 'features', 'secrets', 'faq', 'contact'];
  tabs.forEach(t => {
    const btn = document.getElementById('btnGuideTab' + t.charAt(0).toUpperCase() + t.slice(1));
    const pane = document.getElementById('guideTabPane' + t.charAt(0).toUpperCase() + t.slice(1));
    if (btn) btn.classList.remove('active');
    if (pane) pane.style.display = 'none';
  });

  const activeBtn = document.getElementById('btnGuideTab' + tabKey.charAt(0).toUpperCase() + tabKey.slice(1));
  const activePane = document.getElementById('guideTabPane' + tabKey.charAt(0).toUpperCase() + tabKey.slice(1));
  if (activeBtn) activeBtn.classList.add('active');
  if (activePane) activePane.style.display = 'flex';
}

function filterGuideContent(query) {
  if (!query) query = '';
  const q = query.toLowerCase().trim();
  
  // If searching, switch to features tab to show all matches
  if (q.length > 0) {
    const paneFeatures = document.getElementById('guideTabPaneFeatures');
    if (paneFeatures && paneFeatures.style.display === 'none') {
      switchGuideTab('features');
    }
  }

  const featCards = document.querySelectorAll('.guide-feat-card');
  featCards.forEach(card => {
    const text = card.textContent.toLowerCase();
    const tag = (card.getAttribute('data-guide-tag') || '').toLowerCase();
    if (!q || text.includes(q) || tag.includes(q)) {
      card.style.display = 'flex';
    } else {
      card.style.display = 'none';
    }
  });

  const faqItems = document.querySelectorAll('.guide-faq-item');
  faqItems.forEach(item => {
    const text = item.textContent.toLowerCase();
    if (!q || text.includes(q)) {
      item.style.display = 'flex';
    } else {
      item.style.display = 'none';
    }
  });
}

function openGuideWorkspace(tabKey) {
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('guide');
  }
  if (tabKey) {
    switchGuideTab(tabKey);
  }
}


function copyCharityAccount() {
  const acc = '4541827';
  const btn = document.getElementById('btnCopyCharityAcc');
  if (btn) {
    const originalText = btn.innerHTML;
    btn.innerHTML = '<span>✅</span> Đã copy!';
    setTimeout(() => {
      btn.innerHTML = originalText;
    }, 2000);
  }
  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(acc).then(() => {
      showToast('💖 Đã copy số tài khoản: 4541827 (ACB - CTY TNHH DNXH MAI TAM)', '📋');
    }).catch(() => {
      showToast('💖 STK: 4541827 (ACB - CTY TNHH DNXH MAI TAM)', '📋');
    });
  } else {
    showToast('💖 STK: 4541827 (ACB - CTY TNHH DNXH MAI TAM)', '📋');
  }
}

