let crmRemindersCache = null;
let crmInteractionsCache = null;
let crmClientsCache = null;
let currentCrmReminderFilter = 'all';

function formatScriptWithProfile(rawScript, clientName = '', propertyName = '') {
  let brokerName = 'em';
  let brokerPhone = '';
  if (AppState && AppState.userProfile) {
    if (AppState.userProfile.fullName) brokerName = AppState.userProfile.fullName;
    if (AppState.userProfile.phone) brokerPhone = AppState.userProfile.phone;
  }
  let cName = clientName || 'anh/chị';
  let prop = propertyName || 'căn nhà';

  return rawScript
    .replace(/\{KH\}/g, cName)
    .replace(/\{MôiGiới\}/g, brokerName)
    .replace(/\{SĐT\}/g, brokerPhone || 'hotline')
    .replace(/\{BĐS\}/g, prop);
}

function getCrmReminders() {
  if (crmRemindersCache) return crmRemindersCache;
  if (typeof localStorage !== 'undefined') {
    const saved = localStorage.getItem(STORAGE_KEY_CRM_REMINDERS);
    if (saved) {
      try {
        crmRemindersCache = JSON.parse(saved);
        return crmRemindersCache;
      } catch (e) {}
    }
  }
  crmRemindersCache = [...CRM_SAMPLE_REMINDERS];
  return crmRemindersCache;
}

function saveCrmReminders(list) {
  crmRemindersCache = list;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_CRM_REMINDERS, JSON.stringify(list));
    } catch (e) {}
  }
  updateCrmHeaderBadges();
  renderCrmReminders();
}

