function updateCrmHeaderBadges() {
  const reminders = getCrmReminders();
  const interactions = getCrmInteractions();
  const clients = getCrmClients();
  const now = new Date();
  const todayStr = now.toISOString().slice(0, 10);

  let dueCount = 0;
  let upcomingCount = 0;
  let doneCount = 0;

  reminders.forEach(r => {
    if (r.done) {
      doneCount++;
    } else {
      const rDate = new Date(r.datetime);
      if (isNaN(rDate.getTime()) || rDate < now || (r.datetime && r.datetime.slice(0, 10) === todayStr)) {
        dueCount++;
      } else {
        upcomingCount++;
      }
    }
  });

  const headerBadge = document.getElementById('headerCrmCount');
  if (headerBadge) headerBadge.textContent = dueCount;

  const topBadge = document.getElementById('badgeCrmDueTop');
  if (topBadge) {
    topBadge.textContent = dueCount > 0 ? `⏰ ${dueCount} Cần Xử Lý` : '80% Chốt Deal';
  }

  const statClients = document.getElementById('statCrmTotalClients');
  if (statClients) statClients.textContent = clients.length;

  const statDue = document.getElementById('statCrmDueCount');
  if (statDue) statDue.textContent = dueCount;

  const statInter = document.getElementById('statCrmTotalInteractions');
  if (statInter) statInter.textContent = interactions.length;

  const countAll = document.getElementById('countRemindersAll');
  if (countAll) countAll.textContent = reminders.length;

  const countDue = document.getElementById('countRemindersDue');
  if (countDue) countDue.textContent = dueCount;

  const countUpcoming = document.getElementById('countRemindersUpcoming');
  if (countUpcoming) countUpcoming.textContent = upcomingCount;

  const countDone = document.getElementById('countRemindersDone');
  if (countDone) countDone.textContent = doneCount;
}

function switchCrmSubtab(tabKey) {
  if (tabKey === 'checklist') {
    switchSubsystem('checklist');
    return;
  }

  const btnReminders = document.getElementById('btnCrmSubtabReminders');
  const btnHistory = document.getElementById('btnCrmSubtabHistory');
  const btnScripts = document.getElementById('btnCrmSubtabScripts');
  const btnSpin = document.getElementById('btnCrmSubtabSpin');
  const btnDocVi = document.getElementById('btnCrmSubtabDocVi');

  const paneReminders = document.getElementById('crmTabPaneReminders');
  const paneHistory = document.getElementById('crmTabPaneHistory');
  const paneScripts = document.getElementById('crmTabPaneScripts');
  const paneSpin = document.getElementById('crmTabPaneSpin');
  const paneDocVi = document.getElementById('crmTabPaneDocVi');

  if (btnReminders) btnReminders.classList.remove('active');
  if (btnHistory) btnHistory.classList.remove('active');
  if (btnScripts) btnScripts.classList.remove('active');
  if (btnSpin) btnSpin.classList.remove('active');
  if (btnDocVi) btnDocVi.classList.remove('active');

  if (paneReminders) paneReminders.style.display = 'none';
  if (paneHistory) paneHistory.style.display = 'none';
  if (paneScripts) paneScripts.style.display = 'none';
  if (paneSpin) paneSpin.style.display = 'none';
  if (paneDocVi) paneDocVi.style.display = 'none';

  if (tabKey === 'history') {
    if (btnHistory) btnHistory.classList.add('active');
    if (paneHistory) paneHistory.style.display = 'flex';
    refreshClientDropdown();
  } else if (tabKey === 'scripts') {
    if (btnScripts) btnScripts.classList.add('active');
    if (paneScripts) paneScripts.style.display = 'flex';
    renderCrmScripts();
  } else if (tabKey === 'spin') {
    if (btnSpin) btnSpin.classList.add('active');
    if (paneSpin) paneSpin.style.display = 'flex';
    initSpinSellingModule();
  } else if (tabKey === 'docvi') {
    if (btnDocVi) btnDocVi.classList.add('active');
    if (paneDocVi) paneDocVi.style.display = 'flex';
    initDocViModule();
  } else {
    if (btnReminders) btnReminders.classList.add('active');
    if (paneReminders) paneReminders.style.display = 'flex';
    renderCrmReminders();
  }
}

function setCrmReminderFilter(filter) {
  currentCrmReminderFilter = filter;
  const pills = ['crmFilterAll', 'crmFilterDue', 'crmFilterUpcoming', 'crmFilterDone'];
  pills.forEach(pId => {
    const el = document.getElementById(pId);
    if (el) el.classList.remove('active');
  });

  const activePill = document.getElementById(
    filter === 'due' ? 'crmFilterDue' :
    filter === 'upcoming' ? 'crmFilterUpcoming' :
    filter === 'done' ? 'crmFilterDone' : 'crmFilterAll'
  );
  if (activePill) activePill.classList.add('active');

  renderCrmReminders();
}

function renderCrmReminders() {
  const container = document.getElementById('crmReminderListWrap');
  if (!container) return;

  const reminders = getCrmReminders();
  const now = new Date();
  const todayStr = now.toISOString().slice(0, 10);

  let filtered = reminders.filter(r => {
    if (currentCrmReminderFilter === 'done') return r.done;
    if (currentCrmReminderFilter === 'all') return true;
    if (r.done) return false;

    const rDate = new Date(r.datetime);
    const isDue = isNaN(rDate.getTime()) || rDate < now || (r.datetime && r.datetime.slice(0, 10) === todayStr);
    if (currentCrmReminderFilter === 'due') return isDue;
    if (currentCrmReminderFilter === 'upcoming') return !isDue;
    return true;
  });

  if (filtered.length === 0) {
    container.innerHTML = `
      <div class="crm-empty-state">
        <div class="empty-icon">⏰</div>
        <div class="empty-title">Chưa có nhắc nhở nào</div>
        <div class="empty-desc">Thêm nhắc nhở follow-up KH bên trên!</div>
      </div>
    `;
    return;
  }

  const html = filtered.map(r => {
    const rDate = new Date(r.datetime);
    const isOverdue = !r.done && (rDate < now && (!r.datetime || r.datetime.slice(0, 10) !== todayStr));
    const isToday = !r.done && (r.datetime && r.datetime.slice(0, 10) === todayStr);

    let statusClass = 'status-upcoming';
    let badgeHtml = '<span class="badge-status upcoming">🟢 Sắp tới</span>';

    if (r.done) {
      statusClass = 'status-done';
      badgeHtml = '<span class="badge-status done">✅ Đã xong</span>';
    } else if (isOverdue) {
      statusClass = 'status-overdue';
      badgeHtml = '<span class="badge-status overdue">🔴 Quá hạn</span>';
    } else if (isToday) {
      statusClass = 'status-today';
      badgeHtml = '<span class="badge-status today">🟡 Hôm nay</span>';
    }

    const typeLabel = CRM_TYPE_LABELS[r.type] || r.type || 'Nhắc nhở';
    const cleanPhone = (r.phone || '').replace(/[^0-9]/g, '');

    let formattedDt = (r.datetime || '').replace('T', ' ');
    if (!isNaN(rDate.getTime())) {
      const hh = String(rDate.getHours()).padStart(2, '0');
      const mm = String(rDate.getMinutes()).padStart(2, '0');
      const dd = String(rDate.getDate()).padStart(2, '0');
      const mo = String(rDate.getMonth() + 1).padStart(2, '0');
      const yyyy = rDate.getFullYear();
      formattedDt = `${hh}:${mm} — ${dd}/${mo}/${yyyy}`;
    }

    return `
      <div class="crm-reminder-card ${statusClass}">
        <div class="crm-reminder-top">
          <div class="crm-reminder-client-title">
            <span>👤</span> ${escapeHtml(r.clientName)}
            ${cleanPhone ? `
              <span style="opacity: 0.4">•</span>
              <a href="tel:${cleanPhone}" class="crm-reminder-phone" title="Bấm để gọi">📞 ${escapeHtml(r.phone)}</a>
              <a href="https://zalo.me/${cleanPhone}" target="_blank" class="crm-reminder-phone" style="color: #34d399;" title="Bấm để chat Zalo">💬 Zalo</a>
            ` : ''}
          </div>
          <div class="crm-reminder-badges">
            <span class="badge-status" style="background: rgba(255,255,255,0.06); color: #cbd5e1; border: 1px solid rgba(255,255,255,0.1);">${typeLabel}</span>
            ${badgeHtml}
          </div>
        </div>

        <div class="crm-reminder-body">
          ${r.property ? `<div class="crm-reminder-prop">🏠 BĐS: <strong>${escapeHtml(r.property)}</strong></div>` : ''}
          ${r.notes ? `<div class="crm-reminder-notes">"${escapeHtml(r.notes)}"</div>` : ''}
        </div>

        <div class="crm-reminder-footer">
          <div class="crm-reminder-time-tag">
            <span>🕒</span> Hạn nhắc: <strong>${formattedDt}</strong>
          </div>
          <div class="crm-reminder-btns">
            <button type="button" class="btn-crm-pill ${r.done ? '' : 'success'}" onclick="toggleReminderDone('${r.id}')" title="Đánh dấu đã xong / chưa xong">
              ${r.done ? '↩️ Chưa xong' : '✅ Hoàn thành'}
            </button>
            <button type="button" class="btn-crm-pill" onclick="copyReminderScript('${r.id}')" title="Copy kịch bản nhắn tin cho khách này">
              📋 Script Zalo
            </button>
            <button type="button" class="btn-crm-pill" onclick="goToClientTimeline('${escapeHtml(r.clientName)}')" title="Xem hoặc ghi thêm vào timeline tương tác">
              📝 Timeline
            </button>
            <button type="button" class="btn-crm-pill danger" onclick="deleteReminder('${r.id}')" title="Xóa nhắc nhở này">
              🗑️ Xóa
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function ensureClientExists(name, phone, property) {
  if (!name) return;
  const clients = getCrmClients();
  const found = clients.find(c => c.name.toLowerCase() === name.toLowerCase());
  if (!found) {
    clients.push({
      id: 'cli_' + Date.now(),
      name,
      phone: phone || '',
      property: property || ''
    });
    saveCrmClients(clients);
  } else {
    let changed = false;
    if (phone && !found.phone) { found.phone = phone; changed = true; }
    if (property && !found.property) { found.property = property; changed = true; }
    if (changed) saveCrmClients(clients);
  }
}

function handleAddReminder() {
  const nameInput = document.getElementById('crmInputName');
  const phoneInput = document.getElementById('crmInputPhone');
  const propInput = document.getElementById('crmInputProperty');
  const typeSelect = document.getElementById('crmSelectType');
  const dtInput = document.getElementById('crmInputDatetime');
  const notesInput = document.getElementById('crmInputNotes');

  const clientName = nameInput ? nameInput.value.trim() : '';
  const datetime = dtInput ? dtInput.value : '';

  if (!clientName) {
    showToast('⚠️ Vui lòng nhập Tên KH!', '⚠️');
    if (nameInput) nameInput.focus();
    return;
  }
  if (!datetime) {
    showToast('⚠️ Vui lòng chọn Ngày & Giờ nhắc!', '⚠️');
    if (dtInput) dtInput.focus();
    return;
  }

  const phone = phoneInput ? phoneInput.value.trim() : '';
  const property = propInput ? propInput.value.trim() : '';
  const type = typeSelect ? typeSelect.value : 'followup_after_viewing';
  const notes = notesInput ? notesInput.value.trim() : '';

  const newReminder = {
    id: 'rem_' + Date.now(),
    clientName,
    phone,
    property,
    type,
    datetime,
    notes,
    done: false,
    createdAt: new Date().toISOString()
  };

  const reminders = getCrmReminders();
  reminders.unshift(newReminder);
  saveCrmReminders(reminders);

  ensureClientExists(clientName, phone, property);

  if (nameInput) nameInput.value = '';
  if (phoneInput) phoneInput.value = '';
  if (propInput) propInput.value = '';
  if (notesInput) notesInput.value = '';
  setQuickReminderTime(2, 'hours');

  showToast(`⏰ Đã đặt nhắc lịch cho ${clientName} thành công!`, '✅');
}

function toggleReminderDone(id) {
  const reminders = getCrmReminders();
  const item = reminders.find(r => r.id === id);
  if (item) {
    item.done = !item.done;
    saveCrmReminders(reminders);
    showToast(item.done ? '✅ Đã hoàn thành nhắc nhở!' : '↩️ Đã chuyển về chưa xong!', '✅');
  }
}

function deleteReminder(id) {
  const reminders = getCrmReminders().filter(r => r.id !== id);
  saveCrmReminders(reminders);
  showToast('🗑️ Đã xóa nhắc nhở!', '🗑️');
}

function clearDoneReminders() {
  const reminders = getCrmReminders();
  const remaining = reminders.filter(r => !r.done);
  const countCleared = reminders.length - remaining.length;
  if (countCleared === 0) {
    showToast('ℹ️ Không có nhắc lịch đã xong nào để xóa!', 'ℹ️');
    return;
  }
  saveCrmReminders(remaining);
  showToast(`🗑️ Đã xóa ${countCleared} nhắc lịch đã xong!`, '🗑️');
}

function setQuickReminderTime(amount, unit) {
  const dtInput = document.getElementById('crmInputDatetime');
  if (!dtInput) return;
  const now = new Date();
  if (unit === 'hours') {
    now.setHours(now.getHours() + amount);
  } else if (unit === 'days') {
    now.setDate(now.getDate() + amount);
  }
  const yyyy = now.getFullYear();
  const mm = String(now.getMonth() + 1).padStart(2, '0');
  const dd = String(now.getDate()).padStart(2, '0');
  const hh = String(now.getHours()).padStart(2, '0');
  const mi = String(now.getMinutes()).padStart(2, '0');
  dtInput.value = `${yyyy}-${mm}-${dd}T${hh}:${mi}`;
}

function fillCrmReminderSample() {
  const nameInput = document.getElementById('crmInputName');
  const phoneInput = document.getElementById('crmInputPhone');
  const propInput = document.getElementById('crmInputProperty');
  const typeSelect = document.getElementById('crmSelectType');
  const notesInput = document.getElementById('crmInputNotes');

  if (nameInput) nameInput.value = 'Anh Minh';
  if (phoneInput) phoneInput.value = '0938.123.456';
  if (propInput) propInput.value = 'Nhà phố Q7, 6.5 tỷ';
  if (typeSelect) typeSelect.value = 'followup_after_viewing';
  if (notesInput) notesInput.value = 'KH thích nhà gần trường, hẻm xe hơi. Đang cân nhắc hướng Tây, hỏi quy hoạch lộ giới.';
  setQuickReminderTime(2, 'hours');
  showToast('✨ Đã điền thông tin mẫu Anh Minh Q7!', '✨');
}

function quickApplyStageToReminder(stageIndex) {
  const stages = [
    { type: 'followup_after_viewing', hours: 2, note: 'Follow-up mốc 1: Cảm ơn sau xem nhà + gửi thêm ảnh/sổ + hỏi cảm nhận' },
    { type: 'followup_after_viewing', days: 3, note: 'Follow-up mốc 2 (Ngày 3): Bóc tách băn khoăn: Giá, vị trí hay pháp lý?' },
    { type: 'send_market_news', days: 7, note: 'Follow-up mốc 3 (Ngày 7): Cập nhật tin thị trường + căn tương tự giữ nóng' },
    { type: 'periodic_care', days: 14, note: 'Follow-up mốc 4 (Ngày 14): Hỏi thăm định kỳ, giữ kết nối chân thành' },
    { type: 'new_match_property', hours: 1, note: 'Follow-up mốc 5: Báo căn mới phù hợp — "Em nghĩ ngay đến anh/chị khi thấy căn này"' }
  ];

  const stage = stages[stageIndex - 1];
  if (!stage) return;

  const typeSelect = document.getElementById('crmSelectType');
  const notesInput = document.getElementById('crmInputNotes');
  if (typeSelect) typeSelect.value = stage.type;
  if (notesInput) notesInput.value = stage.note;

  if (stage.hours) setQuickReminderTime(stage.hours, 'hours');
  else if (stage.days) setQuickReminderTime(stage.days, 'days');

  const formCard = document.getElementById('crmReminderForm');
  if (formCard) formCard.scrollIntoView({ behavior: 'smooth', block: 'center' });

  showToast(`⏰ Đã áp dụng mốc ${stageIndex} vào form nhắc lịch!`, '⏰');
}

function copyStageScript(stageIndex) {
  const scriptItem = CRM_FOLLOWUP_SCRIPTS.find(s => s.stage === stageIndex);
  if (!scriptItem) return;

  const formatted = formatScriptWithProfile(scriptItem.template, 'anh/chị', 'căn nhà');
  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(formatted).then(() => {
      showToast(`📋 Đã copy kịch bản Mốc ${stageIndex} vào clipboard!`, '📋');
    }).catch(() => {
      showToast(`📋 Đã sao chép kịch bản Mốc ${stageIndex}!`, '📋');
    });
  } else {
    showToast(`📋 Đã sao chép kịch bản Mốc ${stageIndex}!`, '📋');
  }
}

function copyReminderScript(reminderId) {
  const reminders = getCrmReminders();
  const item = reminders.find(r => r.id === reminderId);
  if (!item) return;

  let stageIndex = 1;
  if (item.type === 'send_market_news') stageIndex = 3;
  else if (item.type === 'periodic_care') stageIndex = 4;
  else if (item.type === 'new_match_property') stageIndex = 5;
  else if (item.type === 'meet_negotiate' || item.type === 'check_legal') stageIndex = 2;

  const scriptItem = CRM_FOLLOWUP_SCRIPTS.find(s => s.stage === stageIndex) || CRM_FOLLOWUP_SCRIPTS[0];
  const formatted = formatScriptWithProfile(scriptItem.template, item.clientName, item.property);

  if (typeof navigator !== 'undefined' && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(formatted).then(() => {
      showToast(`📋 Đã copy script riêng cho ${item.clientName}! Sẵn sàng dán vào Zalo!`, '💬');
    });
  } else {
    showToast(`📋 Đã copy script riêng cho ${item.clientName}!`, '💬');
  }
}

function refreshClientDropdown() {
  const select = document.getElementById('crmSelectClient');
  if (!select) return;

  const clients = getCrmClients();
  const currentVal = select.value;

  select.innerHTML = '<option value="">-- Chọn KH --</option>' +
    clients.map(c => `
      <option value="${escapeHtml(c.name)}" ${currentVal === c.name ? 'selected' : ''}>
        ${escapeHtml(c.name)} ${c.phone ? '• ' + escapeHtml(c.phone) : ''} ${c.property ? '• ' + escapeHtml(c.property) : ''}
      </option>
    `).join('');

  if (currentVal) {
    onSelectClientChange();
  }
}

function onSelectClientChange() {
  const select = document.getElementById('crmSelectClient');
  if (!select) return;
  const clientName = select.value;

  const profileCard = document.getElementById('crmClientProfileCard');
  const avatarLetter = document.getElementById('clientAvatarLetter');
  const nameTitle = document.getElementById('clientDisplayName');
  const phoneLink = document.getElementById('clientPhoneLink');
  const zaloLink = document.getElementById('clientZaloLink');
  const propBadge = document.getElementById('clientPropertyBadge');

  if (!clientName) {
    if (profileCard) profileCard.style.display = 'none';
    renderClientTimeline(null);
    return;
  }

  const clients = getCrmClients();
  const client = clients.find(c => c.name.toLowerCase() === clientName.toLowerCase()) || { name: clientName };

  if (profileCard) profileCard.style.display = 'flex';
  if (avatarLetter) avatarLetter.textContent = clientName.charAt(0).toUpperCase();
  if (nameTitle) nameTitle.textContent = clientName;

  const cleanPhone = (client.phone || '').replace(/[^0-9]/g, '');
  if (phoneLink) {
    phoneLink.textContent = client.phone || 'Chưa có SĐT';
    phoneLink.href = cleanPhone ? `tel:${cleanPhone}` : '#';
  }
  if (zaloLink) {
    zaloLink.href = cleanPhone ? `https://zalo.me/${cleanPhone}` : '#';
    zaloLink.style.display = cleanPhone ? 'inline' : 'none';
  }
  if (propBadge) {
    propBadge.textContent = client.property || 'BĐS đang quan tâm';
  }

  renderClientTimeline(clientName);
}

function renderClientTimeline(clientName) {
  const container = document.getElementById('crmTimelineContainer');
  const countBadge = document.getElementById('clientInteractionsCountBadge');
  if (!container) return;

  if (!clientName) {
    if (countBadge) countBadge.textContent = '0 sự kiện';
    container.innerHTML = `
      <div class="crm-empty-state">
        <div class="empty-icon">📋</div>
        <div class="empty-title">Chưa chọn khách hàng</div>
        <div class="empty-desc">Vui lòng chọn khách hàng ở menu trên để xem lịch sử tương tác & timeline.</div>
      </div>
    `;
    return;
  }

  const interactions = getCrmInteractions().filter(i => (i.clientName || '').toLowerCase() === clientName.toLowerCase());

  if (countBadge) countBadge.textContent = `${interactions.length} sự kiện`;

  if (interactions.length === 0) {
    container.innerHTML = `
      <div class="crm-empty-state">
        <div class="empty-icon">📝</div>
        <div class="empty-title">Chưa có tương tác nào với ${escapeHtml(clientName)}</div>
        <div class="empty-desc">Bấm <strong>"+ Ghi Nhận Tương Tác"</strong> bên trên để lưu lại lần gọi điện, nhắn tin hoặc dẫn xem nhà đầu tiên!</div>
      </div>
    `;
    return;
  }

  const html = interactions.map(i => {
    const chMeta = CRM_CHANNEL_LABELS[i.channel] || { label: 'Tương tác', icon: '📞' };
    const reactMeta = CRM_REACTION_LABELS[i.reaction] || { label: 'Quan tâm', class: 'warm' };

    let dtFormatted = (i.datetime || '').replace('T', ' ');
    const d = new Date(i.datetime);
    if (!isNaN(d.getTime())) {
      const hh = String(d.getHours()).padStart(2, '0');
      const mm = String(d.getMinutes()).padStart(2, '0');
      const dd = String(d.getDate()).padStart(2, '0');
      const mo = String(d.getMonth() + 1).padStart(2, '0');
      const yyyy = d.getFullYear();
      dtFormatted = `${hh}:${mm} — ${dd}/${mo}/${yyyy}`;
    }

    return `
      <div class="crm-timeline-item reaction-${reactMeta.class}">
        <div class="crm-timeline-node"></div>
        <div class="crm-timeline-header">
          <div class="crm-timeline-meta">
            <span class="timeline-channel">${chMeta.icon} ${chMeta.label}</span>
            <span style="opacity: 0.4">•</span>
            <span class="timeline-date">🕒 ${dtFormatted}</span>
          </div>
          <div style="display: flex; align-items: center; gap: 0.4rem;">
            <span class="crm-timeline-reaction-badge ${reactMeta.class}">${reactMeta.label}</span>
            <button type="button" class="btn-crm-pill danger" onclick="deleteInteraction('${i.id}')" title="Xóa ghi nhận này" style="padding: 0.15rem 0.4rem;">&times;</button>
          </div>
        </div>

        <div class="crm-timeline-body">${escapeHtml(i.content)}</div>

        ${i.nextStep ? `
          <div class="crm-timeline-next-step">
            <span>🎯</span> <strong>Bước tiếp theo:</strong> ${escapeHtml(i.nextStep)}
          </div>
        ` : ''}
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function toggleNewInteractionForm(forceShow) {
  const formCard = document.getElementById('crmInteractionFormCard');
  if (!formCard) return;

  const currentDisplay = formCard.style.display;
  const isShow = forceShow !== undefined ? forceShow : (currentDisplay === 'none');
  formCard.style.display = isShow ? 'block' : 'none';

  if (isShow) {
    const dtInput = document.getElementById('crmInterDatetime');
    if (dtInput) {
      const now = new Date();
      const yyyy = now.getFullYear();
      const mm = String(now.getMonth() + 1).padStart(2, '0');
      const dd = String(now.getDate()).padStart(2, '0');
      const hh = String(now.getHours()).padStart(2, '0');
      const mi = String(now.getMinutes()).padStart(2, '0');
      dtInput.value = `${yyyy}-${mm}-${dd}T${hh}:${mi}`;
    }
    const content = document.getElementById('crmInterContent');
    if (content) content.focus();
  }
}

function handleAddInteraction() {
  const select = document.getElementById('crmSelectClient');
  const clientName = select ? select.value : '';

  if (!clientName) {
    showToast('⚠️ Vui lòng chọn một khách hàng trước khi ghi nhận tương tác!', '⚠️');
    return;
  }

  const dtInput = document.getElementById('crmInterDatetime');
  const chSelect = document.getElementById('crmInterChannel');
  const contentInput = document.getElementById('crmInterContent');
  const nextInput = document.getElementById('crmInterNextStep');
  const reactionRadio = document.querySelector('input[name="crmClientReaction"]:checked');

  const content = contentInput ? contentInput.value.trim() : '';
  if (!content) {
    showToast('⚠️ Vui lòng nhập nội dung cuộc trao đổi!', '⚠️');
    if (contentInput) contentInput.focus();
    return;
  }

  const newInter = {
    id: 'inter_' + Date.now(),
    clientName,
    datetime: dtInput ? dtInput.value : new Date().toISOString(),
    channel: chSelect ? chSelect.value : 'call',
    reaction: reactionRadio ? reactionRadio.value : 'warm',
    content,
    nextStep: nextInput ? nextInput.value.trim() : ''
  };

  const interactions = getCrmInteractions();
  interactions.unshift(newInter);
  saveCrmInteractions(interactions);

  if (contentInput) contentInput.value = '';
  if (nextInput) nextInput.value = '';
  toggleNewInteractionForm(false);

  renderClientTimeline(clientName);
  showToast(`💾 Đã lưu tương tác với ${clientName} vào Timeline!`, '✅');
}

function deleteInteraction(id) {
  const interactions = getCrmInteractions().filter(i => i.id !== id);
  saveCrmInteractions(interactions);
  const select = document.getElementById('crmSelectClient');
  if (select && select.value) {
    renderClientTimeline(select.value);
  }
  showToast('🗑️ Đã xóa bản ghi tương tác!', '🗑️');
}

function openNewClientPrompt() {
  const name = prompt('Nhập tên khách hàng mới: (VD: Anh Minh)');
  if (!name || !name.trim()) return;

  const phone = prompt('Nhập số điện thoại khách hàng (tùy chọn):', '');
  const prop = prompt('BĐS quan tâm (tùy chọn):', '');

  ensureClientExists(name.trim(), phone ? phone.trim() : '', prop ? prop.trim() : '');

  const select = document.getElementById('crmSelectClient');
  if (select) {
    select.value = name.trim();
    onSelectClientChange();
  }

  showToast(`👤 Đã thêm khách hàng "${name.trim()}"!`, '✅');
}

function quickAddReminderForCurrentClient() {
  const select = document.getElementById('crmSelectClient');
  const clientName = select ? select.value : '';
  if (!clientName) return;

  const clients = getCrmClients();
  const client = clients.find(c => c.name.toLowerCase() === clientName.toLowerCase()) || { name: clientName };

  switchCrmSubtab('reminders');

  const nameInput = document.getElementById('crmInputName');
  const phoneInput = document.getElementById('crmInputPhone');
  const propInput = document.getElementById('crmInputProperty');

  if (nameInput) nameInput.value = client.name;
  if (phoneInput) phoneInput.value = client.phone || '';
  if (propInput) propInput.value = client.property || '';
  setQuickReminderTime(2, 'hours');

  const formCard = document.getElementById('crmReminderForm');
  if (formCard) formCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
  showToast(`⏰ Đã tạo sẵn form nhắc lịch cho ${client.name}!`, '⏰');
}

function goToClientTimeline(clientName) {
  if (!clientName) return;
  switchCrmSubtab('history');

  const select = document.getElementById('crmSelectClient');
  if (select) {
    select.value = clientName;
    onSelectClientChange();
  }
}

function renderCrmScripts() {
  const container = document.getElementById('crmScriptsGrid');
  if (!container) return;

  const html = CRM_FOLLOWUP_SCRIPTS.map(s => {
    const formatted = formatScriptWithProfile(s.template, '{Tên KH}', '{Căn nhà}');
    return `
      <div class="crm-script-card">
        <div class="crm-script-title">
          <span>📌</span> ${escapeHtml(s.title)}
        </div>
        <div class="crm-script-timing">
          <strong>🕒 Thời điểm:</strong> ${escapeHtml(s.timing)}
        </div>
        <div style="font-size: 0.78rem; color: #94a3b8;">
          <strong>🎯 Mục đích:</strong> ${escapeHtml(s.purpose)}
        </div>
        <div class="crm-script-body">${escapeHtml(formatted)}</div>
        <div class="crm-script-footer">
          <button type="button" class="btn-stage-tool primary" onclick="copyStageScript(${s.stage})" title="Copy mẫu kịch bản này">
            📋 Copy Kịch Bản
          </button>
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function initCrmModule() {
  const dtInput = document.getElementById('crmInputDatetime');
  if (dtInput && !dtInput.value) {
    setQuickReminderTime(2, 'hours');
  }

  updateCrmHeaderBadges();
  renderCrmReminders();
  refreshClientDropdown();
  renderCrmScripts();
  initSpinSellingModule();
  initDocViModule();
  updateChecklistHeaderBadge();
  renderMiniPostingTracker();
}

