let currentSpinAnswers = {};
let currentSpinStageFilter = 'all';
let currentSpinClient = '';

function getSpinSurveys() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_CRM_SPIN_SURVEYS);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function saveSpinSurveys(surveys) {
  try {
    localStorage.setItem(STORAGE_KEY_CRM_SPIN_SURVEYS, JSON.stringify(surveys));
  } catch (e) {
    console.error('Error saving SPIN surveys:', e);
  }
}

function initSpinSellingModule() {
  reloadSpinClientsDropdown();
  renderSpinQuestions();
  updateSpinCounters();
}

function reloadSpinClientsDropdown() {
  const select = document.getElementById('spinSelectClient');
  if (!select) return;

  const currentVal = select.value;
  const clients = typeof getCrmClients === 'function' ? getCrmClients() : [];

  let optionsHtml = '<option value="">-- Chọn KH --</option>';
  clients.forEach(c => {
    const selected = (c.name === currentVal) ? 'selected' : '';
    const meta = [c.phone, c.property].filter(Boolean).join(' • ');
    optionsHtml += `<option value="${escapeHtml(c.name)}" ${selected}>${escapeHtml(c.name)}${meta ? ' (' + escapeHtml(meta) + ')' : ''}</option>`;
  });

  select.innerHTML = optionsHtml;
}

function onSpinClientSelected(clientName) {
  const nameInput = document.getElementById('spinInputClientName');
  if (nameInput) {
    nameInput.value = clientName || '';
  }
  currentSpinClient = clientName || '';

  if (!clientName) return;

  const surveys = getSpinSurveys();
  if (surveys[clientName] && surveys[clientName].answers) {
    currentSpinAnswers = { ...surveys[clientName].answers };
    renderSpinQuestions();
    updateSpinCounters();
    if (typeof showToast === 'function') {
      showToast(`📂 Đã nạp dữ liệu SPIN đã lưu của ${clientName}!`, '📂');
    }
  }
}

function onSpinClientNameInput(name) {
  currentSpinClient = (name || '').trim();
}

function filterSpinStage(stage) {
  currentSpinStageFilter = stage || 'all';

  // Update card active states
  ['S', 'P', 'I', 'N'].forEach(s => {
    const card = document.getElementById('spinCardStage' + s);
    if (card) {
      if (currentSpinStageFilter === s) {
        card.classList.add('active');
      } else {
        card.classList.remove('active');
      }
    }
  });

  // Update filter pills
  const pills = {
    'all': 'spinFilterAll',
    'S': 'spinFilterS',
    'P': 'spinFilterP',
    'I': 'spinFilterI',
    'N': 'spinFilterN'
  };
  Object.keys(pills).forEach(key => {
    const pill = document.getElementById(pills[key]);
    if (pill) {
      if (currentSpinStageFilter === key) {
        pill.classList.add('active');
      } else {
        pill.classList.remove('active');
      }
    }
  });

  renderSpinQuestions();
}

function renderSpinQuestions() {
  const container = document.getElementById('spinQuestionsContainer');
  if (!container) return;

  const filtered = SPIN_QUESTIONS.filter(q => {
    if (currentSpinStageFilter === 'all') return true;
    return q.stage === currentSpinStageFilter;
  });

  if (filtered.length === 0) {
    container.innerHTML = '<div style="text-align: center; color: #94a3b8; padding: 2rem;">Không có câu hỏi nào.</div>';
    return;
  }

  const html = filtered.map(q => {
    const ans = currentSpinAnswers[q.id] || '';
    const isAnswered = ans.trim().length > 0;
    const stageLower = q.stage.toLowerCase();

    return `
      <div class="spin-question-item stage-${stageLower} ${isAnswered ? 'answered' : ''}" id="spinQItem_${q.id}">
        <div class="spin-q-header">
          <div class="spin-q-tags">
            <span class="spin-q-stage-badge ${stageLower}">${escapeHtml(q.stageNum)} · ${escapeHtml(q.stageName)}</span>
            <span class="spin-q-number">Câu ${q.num < 10 ? '0' + q.num : q.num}/20</span>
          </div>
          <div class="spin-q-actions">
            <button type="button" class="btn-spin-q-fill" onclick="fillSpinSampleItem('${q.id}')" title="Điền câu trả lời mẫu thực chiến cho câu này">
              ✨ Mẫu
            </button>
            <button type="button" class="btn-spin-q-clear" onclick="clearSpinQuestionItem('${q.id}')" title="Xóa câu trả lời này">
              ✕
            </button>
          </div>
        </div>

        <div class="spin-q-text">
          ${escapeHtml(q.question)}
        </div>

        <div class="spin-q-purpose">
          <span>💡 Mục đích:</span> ${escapeHtml(q.purpose)}
        </div>

        <textarea
          class="spin-q-answer-textarea"
          id="spinAns_${q.id}"
          placeholder="Nhập câu trả lời của KH hoặc bấm nút Mẫu..."
          oninput="handleSpinAnswerInput('${q.id}', this.value)"
        >${escapeHtml(ans)}</textarea>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function handleSpinAnswerInput(qId, val) {
  if (val && val.trim()) {
    currentSpinAnswers[qId] = val.trim();
  } else {
    delete currentSpinAnswers[qId];
  }

  const itemEl = document.getElementById('spinQItem_' + qId);
  if (itemEl) {
    if (val && val.trim()) {
      itemEl.classList.add('answered');
    } else {
      itemEl.classList.remove('answered');
    }
  }

  updateSpinCounters();
}

function updateSpinCounters() {
  const countS = SPIN_QUESTIONS.filter(q => q.stage === 'S' && (currentSpinAnswers[q.id] || '').trim()).length;
  const countP = SPIN_QUESTIONS.filter(q => q.stage === 'P' && (currentSpinAnswers[q.id] || '').trim()).length;
  const countI = SPIN_QUESTIONS.filter(q => q.stage === 'I' && (currentSpinAnswers[q.id] || '').trim()).length;
  const countN = SPIN_QUESTIONS.filter(q => q.stage === 'N' && (currentSpinAnswers[q.id] || '').trim()).length;
  const total = countS + countP + countI + countN;

  const badgeS = document.getElementById('spinStageCountS');
  const badgeP = document.getElementById('spinStageCountP');
  const badgeI = document.getElementById('spinStageCountI');
  const badgeN = document.getElementById('spinStageCountN');

  if (badgeS) badgeS.textContent = `${countS}/6`;
  if (badgeP) badgeP.textContent = `${countP}/5`;
  if (badgeI) badgeI.textContent = `${countI}/5`;
  if (badgeN) badgeN.textContent = `${countN}/4`;

  const percent = Math.round((total / 20) * 100);
  const progText = document.getElementById('spinTotalProgressText');
  const progFill = document.getElementById('spinProgressFill');

  if (progText) progText.textContent = `${total}/20 câu (${percent}%)`;
  if (progFill) progFill.style.width = `${percent}%`;
}

function fillSpinSampleItem(qId) {
  const q = SPIN_QUESTIONS.find(item => item.id === qId);
  if (!q) return;

  currentSpinAnswers[qId] = q.sample;

  const textarea = document.getElementById('spinAns_' + qId);
  if (textarea) textarea.value = q.sample;

  const itemEl = document.getElementById('spinQItem_' + qId);
  if (itemEl) itemEl.classList.add('answered');

  updateSpinCounters();
  if (typeof showToast === 'function') {
    showToast(`✨ Đã điền câu trả lời mẫu cho câu ${q.num}!`, '💬');
  }
}

function clearSpinQuestionItem(qId) {
  delete currentSpinAnswers[qId];

  const textarea = document.getElementById('spinAns_' + qId);
  if (textarea) textarea.value = '';

  const itemEl = document.getElementById('spinQItem_' + qId);
  if (itemEl) itemEl.classList.remove('answered');

  updateSpinCounters();
}

function fillSpinSampleAll() {
  SPIN_QUESTIONS.forEach(q => {
    currentSpinAnswers[q.id] = q.sample;
  });

  const select = document.getElementById('spinSelectClient');
  const nameInput = document.getElementById('spinInputClientName');

  if (nameInput && !nameInput.value.trim()) {
    nameInput.value = 'Anh Minh';
    currentSpinClient = 'Anh Minh';
  }
  if (select && select.querySelector('option[value="Anh Minh"]')) {
    select.value = 'Anh Minh';
  }

  renderSpinQuestions();
  updateSpinCounters();

  if (typeof showToast === 'function') {
    showToast('✨ Đã điền 20 câu trả lời mẫu thực tế của Anh Minh (Mua nhà Phú Nhuận ~5 tỷ)!', '🔄');
  }
}

function resetSpinForm() {
  currentSpinAnswers = {};

  const select = document.getElementById('spinSelectClient');
  const nameInput = document.getElementById('spinInputClientName');
  if (select) select.value = '';
  if (nameInput) nameInput.value = '';
  currentSpinClient = '';

  closeSpinAnalysisPanel();
  renderSpinQuestions();
  updateSpinCounters();

  if (typeof showToast === 'function') {
    showToast('🗑️ Đã làm mới form khảo sát SPIN!', '🔄');
  }
}

function saveSpinAnswersForCurrentClient() {
  const nameInput = document.getElementById('spinInputClientName');
  const select = document.getElementById('spinSelectClient');
  const clientName = (nameInput && nameInput.value.trim()) || (select && select.value.trim()) || currentSpinClient;

  if (!clientName) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Vui lòng nhập hoặc chọn Tên Khách Hàng trước khi lưu!', '⚠️');
    }
    if (nameInput) nameInput.focus();
    return;
  }

  const answeredCount = Object.keys(currentSpinAnswers).filter(k => (currentSpinAnswers[k] || '').trim()).length;
  if (answeredCount === 0) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Bạn chưa trả lời câu nào trong 20 câu SPIN!', '⚠️');
    }
    return;
  }

  // 1. Lưu vào danh sách khảo sát SPIN LocalStorage
  const surveys = getSpinSurveys();
  surveys[clientName] = {
    clientName: clientName,
    answers: { ...currentSpinAnswers },
    answeredCount: answeredCount,
    updatedAt: new Date().toISOString()
  };
  saveSpinSurveys(surveys);

  // 2. Thêm khách vào danh sách CRM nếu chưa có
  if (typeof getCrmClients === 'function' && typeof saveCrmClients === 'function') {
    const clients = getCrmClients();
    const exists = clients.some(c => c.name.toLowerCase() === clientName.toLowerCase());
    if (!exists) {
      clients.push({
        id: 'cli_' + Date.now(),
        name: clientName,
        phone: '',
        property: currentSpinAnswers.s4 ? `Ngân sách: ${currentSpinAnswers.s4}` : 'Khảo sát SPIN'
      });
      saveCrmClients(clients);
      reloadSpinClientsDropdown();
    }
  }

  // 3. Tự động ghi một lượt tương tác vào Timeline CRM
  if (typeof getCrmInteractions === 'function' && typeof saveCrmInteractions === 'function') {
    const interactions = getCrmInteractions();
    const budget = currentSpinAnswers.s4 || '~5 tỷ';
    const loc = currentSpinAnswers.s3 || 'Phú Nhuận';
    const pain = currentSpinAnswers.p4 || 'Sợ rủi ro pháp lý & thị trường biến động';

    const newInter = {
      id: 'inter_spin_' + Date.now(),
      clientName: clientName,
      channel: 'meeting',
      reaction: 'hot',
      datetime: new Date().toISOString().slice(0, 16),
      content: `[SPIN Selling] Đã hoàn thành khảo sát ${answeredCount}/20 câu hỏi khám phá nhu cầu.\n• Nhu cầu: Mua ở thật, khu vực làm việc ${loc}, ngân sách: ${budget}.\n• Nỗi đau cốt lõi: ${pain}.\n• Cam kết: Muốn xem ngay nếu tìm được căn đúng khu, đúng giá, pháp lý chuẩn 100%.`,
      nextStep: 'Lọc 2-3 căn nhà đúng tầm giá và pháp lý sạch để hẹn dẫn xem ngay trong tuần.'
    };
    interactions.unshift(newInter);
    saveCrmInteractions(interactions);
    if (typeof renderCrmReminders === 'function') renderCrmReminders();
    if (typeof refreshClientDropdown === 'function') refreshClientDropdown();
  }

  if (typeof showToast === 'function') {
    showToast(`💾 Đã lưu hồ sơ SPIN của ${clientName} & đồng bộ sang CRM Timeline!`, '✅');
  }
}

function copySpinInterviewTranscript() {
  const nameInput = document.getElementById('spinInputClientName');
  const clientName = (nameInput && nameInput.value.trim()) || currentSpinClient || 'Khách Hàng';
  const answeredCount = Object.keys(currentSpinAnswers).filter(k => (currentSpinAnswers[k] || '').trim()).length;

  let text = `=========================================\n`;
  text += `🔄 BIÊN BẢN KHẢO SÁT NHU CẦU KHÁCH HÀNG — SPIN SELLING\n`;
  text += `Khách hàng: ${clientName}\n`;
  text += `Tiến độ: ${answeredCount}/20 câu hỏi mở đã hoàn thành\n`;
  text += `Thời gian: ${new Date().toLocaleString('vi-VN')}\n`;
  text += `=========================================\n\n`;

  const stages = [
    { key: 'S', name: 'GIAI ĐOẠN S: SITUATION (TÌM HIỂU THỰC TRẠNG)' },
    { key: 'P', name: 'GIAI ĐOẠN P: PROBLEM (KHƠI GỢI NỖI ĐAU & RÀO CẢN)' },
    { key: 'I', name: 'GIAI ĐOẠN I: IMPLICATION (KHUẾCH ĐẠI HỆ QUẢ)' },
    { key: 'N', name: 'GIAI ĐOẠN N: NEED-PAYOFF (GIẢI PHÁP & CHỐT CAM KẾT)' }
  ];

  stages.forEach(st => {
    text += `📌 ${st.name}\n`;
    text += `-----------------------------------------\n`;
    const qs = SPIN_QUESTIONS.filter(q => q.stage === st.key);
    qs.forEach(q => {
      const ans = currentSpinAnswers[q.id] || '(Chưa trả lời)';
      text += `[${q.stageNum}] ${q.question}\n`;
      text += `👉 Trả lời: ${ans}\n\n`;
    });
  });

  text += `=========================================\n`;
  text += `💡 LỜI KHUYÊN MÔI GIỚI (TỪ EBOOK THỰC CHIẾN):\n`;
  text += `- Hỏi đúng thứ tự S → P → I → N để khách hàng tự nhận thức nỗi đau và tự chốt mua.\n`;
  text += `- Áp dụng Ma Trận Tâm Lý & Kịch bản phá khóa để chuẩn bị sẵn căn nhà phù hợp nhất trước khi dẫn xem thực tế.\n`;
  text += `=========================================`;

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép toàn bộ biên bản phỏng vấn SPIN vào Clipboard!', '📋');
      }
    }).catch(() => {
      fallbackCopyText(text);
    });
  } else {
    fallbackCopyText(text);
  }
}

function analyzeSpinPsychology() {
  const panel = document.getElementById('spinAnalysisPanel');
  const content = document.getElementById('spinAnalysisContent');
  if (!panel || !content) return;

  const s1 = currentSpinAnswers.s1 || 'Đang ở nhà thuê';
  const s2 = currentSpinAnswers.s2 || 'Gia đình vợ chồng 1 con';
  const s3 = currentSpinAnswers.s3 || 'Làm ở Phú Nhuận, thuê ở Q12 (xa)';
  const s4 = currentSpinAnswers.s4 || 'Ngân sách ~5 tỷ (có vay NH)';
  const s6 = currentSpinAnswers.s6 || 'Mua nhà để ở';

  const p1 = currentSpinAnswers.p1 || 'Đi làm xa, bất tiện';
  const p2 = currentSpinAnswers.p2 || 'Bất an vì thuê nhà nhiều năm';
  const p4 = currentSpinAnswers.p4 || 'Lo ngại pháp lý, thị trường giá biến động, sợ lừa đảo';

  const i1 = currentSpinAnswers.i1 || 'Tiền thuê mất trắng cho chủ nhà';
  const i3 = currentSpinAnswers.i3 || 'Sợ giá BĐS tăng 15-20% năm sau khó mua';

  const n1 = currentSpinAnswers.n1 || 'Muốn xem ngay nếu căn chuẩn';
  const n2 = currentSpinAnswers.n2 || 'Ưu tiên vị trí, pháp lý, giá';
  const n3 = currentSpinAnswers.n3 || 'Quyết định mua';

  const html = `
    <div class="spin-analysis-grid">
      <!-- 1. Chân dung & Hồ sơ nhu cầu -->
      <div class="spin-insight-card">
        <div class="spin-insight-title purple">
          <span>🎯</span> CHÂN DUNG & NĂNG LỰC TÀI CHÍNH
        </div>
        <div class="spin-insight-body">
          • <strong>Mục đích:</strong> ${escapeHtml(s6)} (Mua ở thật, nhu cầu cấp thiết).<br>
          • <strong>Quy mô gia đình:</strong> ${escapeHtml(s2)} (Cần không gian sinh hoạt riêng cho con).<br>
          • <strong>Vị trí tối ưu:</strong> Nơi làm việc tại <strong>${escapeHtml(s3)}</strong>.<br>
          • <strong>Ngân sách & Đòn bẩy:</strong> <strong>${escapeHtml(s4)}</strong>.
        </div>
      </div>

      <!-- 2. Nỗi đau & Nỗi sợ cốt lõi -->
      <div class="spin-insight-card">
        <div class="spin-insight-title rose">
          <span>💔</span> NỖI ĐAU & RÀO CẢN TÂM LÝ (PAIN POINTS)
        </div>
        <div class="spin-insight-body">
          • <strong>Nỗi đau hàng ngày:</strong> ${escapeHtml(p1)}, chỗ ở hiện tại <strong>${escapeHtml(s1)}</strong>.<br>
          • <strong>Áp lực tâm lý:</strong> ${escapeHtml(p2)}, tiền thuê <strong>${escapeHtml(i1)}</strong>.<br>
          • <strong>Nỗi sợ sâu kín nhất:</strong> <strong>${escapeHtml(p4)}</strong>.<br>
          • <strong>Nỗi sợ lỡ cơ hội (FOMO):</strong> ${escapeHtml(i3)}.
        </div>
      </div>

      <!-- 3. Phân loại theo Ebook 2: Ma Trận Tâm Lý -->
      <div class="spin-insight-card">
        <div class="spin-insight-title amber">
          <span>🧠</span> PHÂN LOẠI TÂM LÝ (EBOOK 02 MA TRẬN TÂM LÝ)
        </div>
        <div class="spin-insight-body">
          • <strong>Nhóm Trội 1: 🔍 NGHI NGỜ (Trang 10 Ebook 2)</strong> — Khách đặc biệt sợ rủi ro pháp lý & lừa đảo. Cần cung cấp sổ hồng, quy hoạch chi tiết 1/500 và dẫn đến gặp chủ nhà trực tiếp để xóa tan nghi ngờ.<br>
          • <strong>Nhóm Trội 2: 🔥 SÂN / SỢ MẤT CƠ HỘI (Trang 8 Ebook 2)</strong> — Khách rất tiếc tiền thuê và sợ giá BĐS tăng 15-20% năm sau. Cần kích hoạt sự khan hiếm của căn nhà đẹp trong tầm giá 5 tỷ.
        </div>
      </div>

      <!-- 4. Chiến lược phá khóa & Kịch bản chốt cọc -->
      <div class="spin-insight-card">
        <div class="spin-insight-title emerald">
          <span>🗝️</span> CHIẾN THUẬT PHÁ KHÓA & CHỐT DEAL (EBOOK 03)
        </div>
        <div class="spin-insight-body">
          • <strong>Bước 1 - Định Hướng Lại Nhà:</strong> Chọn ngay 1 căn hẻm thoáng (3m-4m) tại Phú Nhuận hoặc vùng giáp ranh, tài chính đúng 5 tỷ để giải quyết dứt điểm việc đi làm gần.<br>
          • <strong>Bước 2 - Phá Khóa Pháp Lý:</strong> Gửi hình sổ hồng hoàn công đầy đủ trước khi dẫn xem. Khách thấy pháp lý sạch là tự động cởi mở tâm lý.<br>
          • <strong>Bước 3 - Kịch Bản Chốt Trong Tuần:</strong> Khách đã trả lời <em>"${escapeHtml(n1)}"</em> và <em>"${escapeHtml(n3)}"</em> — Chuẩn bị sẵn phiếu đặt cọc và ưu đãi hỗ trợ gói vay ngân hàng ngay khi kết thúc buổi xem nhà!
        </div>
      </div>
    </div>

    <div style="display: flex; gap: 0.6rem; justify-content: flex-end; margin-top: 0.6rem; flex-wrap: wrap;">
      <button type="button" class="btn-spin-action success" onclick="saveSpinAnswersForCurrentClient()">
        💾 Lưu & Đồng Bộ Vào CRM
      </button>
      <button type="button" class="btn-spin-action purple" onclick="copySpinInterviewTranscript()">
        📋 Sao Chép Báo Cáo
      </button>
    </div>
  `;

  content.innerHTML = html;
  panel.style.display = 'flex';
  panel.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

  if (typeof showToast === 'function') {
    showToast('🧠 Đã phân tích tâm lý & chiến lược chốt deal thành công!', '🧠');
  }
}

function closeSpinAnalysisPanel() {
  const panel = document.getElementById('spinAnalysisPanel');
  if (panel) panel.style.display = 'none';
}

function openSpinSellingDirect() {
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('crm');
  }
  if (typeof switchCrmSubtab === 'function') {
    switchCrmSubtab('spin');
  }
  const el = document.getElementById('crmTabPaneSpin');
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function openSpinForSelectedCrmClient() {
  const select = document.getElementById('crmSelectClient');
  const clientName = select ? select.value : '';

  openSpinSellingDirect();

  if (clientName) {
    const spinSelect = document.getElementById('spinSelectClient');
    if (spinSelect) spinSelect.value = clientName;
    onSpinClientSelected(clientName);
  }
}

