let currentDocViAnswers = {};
let currentDocViClient = '';

function getDocViSurveys() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_CRM_DOCVI_SURVEYS);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function saveDocViSurveys(surveys) {
  try {
    localStorage.setItem(STORAGE_KEY_CRM_DOCVI_SURVEYS, JSON.stringify(surveys));
  } catch (e) {
    console.error('Error saving DocVi surveys:', e);
  }
}

function initDocViModule() {
  reloadDocViClientsDropdown();
  renderDocViQuestions();
  updateDocViResults();
}

function reloadDocViClientsDropdown() {
  const select = document.getElementById('docViSelectClient');
  if (!select) return;

  const currentVal = select.value;
  const clients = typeof getCrmClients === 'function' ? getCrmClients() : [];

  let optionsHtml = '<option value="">-- Chọn KH CRM --</option>';
  clients.forEach(c => {
    const selected = (c.name === currentVal) ? 'selected' : '';
    const meta = [c.phone, c.property].filter(Boolean).join(' • ');
    optionsHtml += `<option value="${escapeHtml(c.name)}" ${selected}>${escapeHtml(c.name)}${meta ? ' (' + escapeHtml(meta) + ')' : ''}</option>`;
  });

  select.innerHTML = optionsHtml;
}

function onDocViClientSelected(clientName) {
  const nameInput = document.getElementById('docViInputClientName');
  if (nameInput) {
    nameInput.value = clientName || '';
  }
  currentDocViClient = clientName || '';

  if (!clientName) return;

  const surveys = getDocViSurveys();
  if (surveys[clientName] && surveys[clientName].answers) {
    currentDocViAnswers = { ...surveys[clientName].answers };
    renderDocViQuestions();
    updateDocViResults();
    if (typeof showToast === 'function') {
      showToast(`📂 Đã nạp kết quả đọc vị của ${clientName}!`, '📂');
    }
  }
}

function onDocViClientNameInput(name) {
  currentDocViClient = (name || '').trim();
}

function renderDocViQuestions() {
  const container = document.getElementById('docViQuestionsContainer');
  if (!container) return;

  const html = DOCVI_QUESTIONS.map(q => {
    const selectedOpt = currentDocViAnswers[q.id];
    const isAnswered = Boolean(selectedOpt);

    const optionsHtml = q.options.map(opt => {
      const isSelected = (selectedOpt === opt.id);
      return `
        <button
          type="button"
          class="docvi-option-btn ${isSelected ? 'selected' : ''}"
          onclick="selectDocViOption(${q.id}, '${opt.id}')"
        >
          <div class="docvi-radio-circle">
            <div class="docvi-radio-dot"></div>
          </div>
          <div class="docvi-opt-text">${escapeHtml(opt.text)}</div>
        </button>
      `;
    }).join('');

    return `
      <div class="docvi-question-card ${isAnswered ? 'answered' : ''}" id="docViCard_${q.id}">
        <div class="docvi-q-title">
          <span class="q-icon">❓</span> ${escapeHtml(q.title)}
        </div>
        <div class="docvi-options-stack">
          ${optionsHtml}
        </div>
      </div>
    `;
  }).join('');

  container.innerHTML = html;
}

function selectDocViOption(qId, optId) {
  currentDocViAnswers[qId] = optId;

  // Update DOM directly for instant reactivity
  const card = document.getElementById('docViCard_' + qId);
  if (card) {
    card.classList.add('answered');
    const buttons = card.querySelectorAll('.docvi-option-btn');
    const qData = DOCVI_QUESTIONS.find(q => q.id === qId);
    if (qData) {
      buttons.forEach((btn, idx) => {
        if (qData.options[idx] && qData.options[idx].id === optId) {
          btn.classList.add('selected');
        } else {
          btn.classList.remove('selected');
        }
      });
    }
  }

  updateDocViResults();
}

function updateDocViResults() {
  const answeredKeys = Object.keys(currentDocViAnswers);
  const answeredCount = answeredKeys.length;

  const countBadge = document.getElementById('docViAnsweredCount');
  if (countBadge) countBadge.textContent = `${answeredCount}/10`;

  const emptyState = document.getElementById('docViEmptyState');
  const resultsBody = document.getElementById('docViResultsBody');

  if (answeredCount === 0) {
    if (emptyState) emptyState.style.display = 'block';
    if (resultsBody) resultsBody.style.display = 'none';
    return;
  }

  if (emptyState) emptyState.style.display = 'none';
  if (resultsBody) resultsBody.style.display = 'flex';

  // Calculate psychological scores
  const scores = {
    nghingo: 0,
    tham: 0,
    san: 0,
    si: 0,
    ngaoman: 0
  };

  answeredKeys.forEach(qId => {
    const q = DOCVI_QUESTIONS.find(item => item.id === Number(qId));
    if (!q) return;
    const chosenOptId = currentDocViAnswers[qId];
    const opt = q.options.find(o => o.id === chosenOptId);
    if (opt && opt.traits) {
      Object.keys(opt.traits).forEach(trait => {
        scores[trait] = (scores[trait] || 0) + opt.traits[trait];
      });
    }
  });

  const totalScore = Object.values(scores).reduce((a, b) => a + b, 0) || 1;

  // Sort traits by highest score
  const sortedTraits = Object.keys(scores).sort((a, b) => scores[b] - scores[a]);
  const primaryTraitKey = sortedTraits[0];
  const primaryProfile = DOCVI_PROFILES[primaryTraitKey] || DOCVI_PROFILES.nghingo;
  const primaryPercent = Math.round((scores[primaryTraitKey] / totalScore) * 100);

  // 1. Primary Highlight Banner
  const bannerEl = document.getElementById('docViPrimaryBanner');
  if (bannerEl) {
    bannerEl.style.borderColor = primaryProfile.color;
    bannerEl.innerHTML = `
      <div class="docvi-primary-icon">${primaryProfile.icon}</div>
      <div class="docvi-primary-info">
        <div class="docvi-primary-kicker">TÂM LÝ CHỦ ĐẠO CHIẾM ${primaryPercent}% SỰ QUYẾT ĐỊNH</div>
        <div class="docvi-primary-name" style="color: ${primaryProfile.color};">${primaryProfile.name}</div>
        <div class="docvi-primary-desc">${primaryProfile.summary}</div>
      </div>
    `;
  }

  // 2. Matrix Breakdown Bars
  const barsEl = document.getElementById('docViMatrixBars');
  if (barsEl) {
    const barsHtml = sortedTraits.map(key => {
      const prof = DOCVI_PROFILES[key];
      const pct = Math.round((scores[key] / totalScore) * 100);
      return `
        <div class="docvi-matrix-row">
          <div class="docvi-matrix-label" style="color: ${prof.color};">
            <span>${prof.icon}</span> ${prof.name.split('—')[0].trim()}
          </div>
          <div class="docvi-matrix-track">
            <div class="docvi-matrix-fill" style="width: ${pct}%; background: ${prof.color};"></div>
          </div>
          <div class="docvi-matrix-percent">${pct}%</div>
        </div>
      `;
    }).join('');
    barsEl.innerHTML = barsHtml;
  }

  // 3. Detail Grid (Communication, Core Motives, Closing Script)
  const gridEl = document.getElementById('docViDetailGrid');
  if (gridEl) {
    gridEl.innerHTML = `
      <!-- Card 1: Ngôn ngữ tiếp cận -->
      <div class="docvi-detail-card primary">
        <div class="docvi-detail-title">
          <span>🗣️</span> NGÔN NGỮ TIẾP CẬN (TĂNG TỶ LỆ CHỐT 3X)
        </div>
        <div class="docvi-detail-body">
          <div style="margin-bottom: 0.45rem;">
            <strong style="color: #34d399;">✅ TỪ KHÓA NÊN DÙNG:</strong><br>
            ${primaryProfile.shouldUse.map(u => `• "${u}"`).join('<br>')}
          </div>
          <div>
            <strong style="color: #f43f5e;">❌ TUYỆT ĐỐI TRÁNH NÓI:</strong><br>
            ${primaryProfile.shouldAvoid.map(a => `• ${a}`).join('<br>')}
          </div>
        </div>
      </div>

      <!-- Card 2: Tử huyệt cảm xúc -->
      <div class="docvi-detail-card warning">
        <div class="docvi-detail-title">
          <span>🗝️</span> TỬ HUYỆT CẢM XÚC & ĐỘNG CƠ CỐT LÕI
        </div>
        <div class="docvi-detail-body">
          <p style="margin-bottom: 0.45rem;">
            <strong>🎯 ĐỘNG CƠ MUA HÀNG:</strong><br>
            ${primaryProfile.motive}
          </p>
          <p>
            <strong>🧠 ĐẶC ĐIỂM HÀNH VI:</strong><br>
            ${primaryProfile.summary}
          </p>
        </div>
      </div>

      <!-- Card 3: Kịch bản chốt deal -->
      <div class="docvi-detail-card success">
        <div class="docvi-detail-title">
          <span>🎯</span> KỊCH BẢN CHỐT DEAL TRONG TUẦN (EBOOK 03)
        </div>
        <div class="docvi-detail-body">
          <p style="margin-bottom: 0.45rem;">
            <strong>⚡ CHIẾN THUẬT PHÁ KHÓA:</strong><br>
            ${primaryProfile.closingScript}
          </p>
          <p>
            <strong>📖 THAM KHẢO EBOOK:</strong><br>
            Đọc chi tiết tại <em>Module Ma Trận Tâm Lý (Phân hệ 07)</em> để trang bị trọn bộ mẫu câu bách thắng.
          </p>
        </div>
      </div>
    `;
  }
}

function applyDocViPreset(presetType) {
  let presetMap = {};
  let defaultName = 'Anh Minh';

  if (presetType === 'nghingo') {
    presetMap = { 1: 'B', 2: 'C', 3: 'C', 4: 'C', 5: 'C', 6: 'C', 7: 'C', 8: 'C', 9: 'C', 10: 'C' };
    defaultName = 'Anh Minh (Nghi Ngờ)';
  } else if (presetType === 'tham') {
    presetMap = { 1: 'A', 2: 'A', 3: 'A', 4: 'D', 5: 'A', 6: 'A', 7: 'A', 8: 'A', 9: 'A', 10: 'A' };
    defaultName = 'Anh Tuấn (Tham Rẻ)';
  } else if (presetType === 'ngaoman') {
    presetMap = { 1: 'C', 2: 'D', 3: 'B', 4: 'A', 5: 'B', 6: 'B', 7: 'D', 8: 'A', 9: 'A', 10: 'B' };
    defaultName = 'Chị Lan (Khách VIP)';
  } else if (presetType === 'san') {
    presetMap = { 1: 'D', 2: 'A', 3: 'A', 4: 'A', 5: 'A', 6: 'C', 7: 'B', 8: 'A', 9: 'A', 10: 'B' };
    defaultName = 'Anh Dũng (Sợ Lỡ Deal)';
  }

  currentDocViAnswers = { ...presetMap };

  const nameInput = document.getElementById('docViInputClientName');
  if (nameInput && !nameInput.value.trim()) {
    nameInput.value = defaultName;
    currentDocViClient = defaultName;
  }

  renderDocViQuestions();
  updateDocViResults();

  if (typeof showToast === 'function') {
    showToast(`✨ Đã nạp mẫu đọc vị: ${defaultName}!`, '🎭');
  }
}

function resetDocViQuiz() {
  currentDocViAnswers = {};

  const nameInput = document.getElementById('docViInputClientName');
  const select = document.getElementById('docViSelectClient');
  if (nameInput) nameInput.value = '';
  if (select) select.value = '';
  currentDocViClient = '';

  renderDocViQuestions();
  updateDocViResults();

  if (typeof showToast === 'function') {
    showToast('🗑️ Đã làm mới 10 câu hỏi đọc vị!', '🔄');
  }
}

function saveDocViResultsToCrm() {
  const nameInput = document.getElementById('docViInputClientName');
  const select = document.getElementById('docViSelectClient');
  const clientName = (nameInput && nameInput.value.trim()) || (select && select.value.trim()) || currentDocViClient;

  if (!clientName) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Vui lòng nhập hoặc chọn Tên Khách Hàng trước khi lưu!', '⚠️');
    }
    if (nameInput) nameInput.focus();
    return;
  }

  const answeredCount = Object.keys(currentDocViAnswers).length;
  if (answeredCount === 0) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Vui lòng trả lời ít nhất 1 câu hỏi đọc vị trước khi lưu!', '⚠️');
    }
    return;
  }

  // Calculate scores
  const scores = { nghingo: 0, tham: 0, san: 0, si: 0, ngaoman: 0 };
  Object.keys(currentDocViAnswers).forEach(qId => {
    const q = DOCVI_QUESTIONS.find(item => item.id === Number(qId));
    if (!q) return;
    const opt = q.options.find(o => o.id === currentDocViAnswers[qId]);
    if (opt && opt.traits) {
      Object.keys(opt.traits).forEach(t => {
        scores[t] = (scores[t] || 0) + opt.traits[t];
      });
    }
  });
  const totalScore = Object.values(scores).reduce((a, b) => a + b, 0) || 1;
  const sorted = Object.keys(scores).sort((a, b) => scores[b] - scores[a]);
  const primaryKey = sorted[0];
  const primaryProfile = DOCVI_PROFILES[primaryKey];
  const pct = Math.round((scores[primaryKey] / totalScore) * 100);

  // 1. Lưu vào danh sách đọc vị LocalStorage
  const surveys = getDocViSurveys();
  surveys[clientName] = {
    clientName: clientName,
    answers: { ...currentDocViAnswers },
    primaryKey: primaryKey,
    primaryName: primaryProfile.name,
    percent: pct,
    updatedAt: new Date().toISOString()
  };
  saveDocViSurveys(surveys);

  // 2. Tự động ghi vào Timeline CRM
  if (typeof getCrmInteractions === 'function' && typeof saveCrmInteractions === 'function') {
    const interactions = getCrmInteractions();
    const newInter = {
      id: 'inter_docvi_' + Date.now(),
      clientName: clientName,
      channel: 'meeting',
      reaction: primaryKey === 'san' || primaryKey === 'tham' ? 'hot' : 'warm',
      datetime: new Date().toISOString().slice(0, 16),
      content: `[Đọc Vị KH] Hoàn thành trắc nghiệm 10 câu hành vi.\n• Nhóm tâm lý nổi trội: ${primaryProfile.name} (${pct}%).\n• Tử huyệt cảm xúc: ${primaryProfile.motive}\n• Từ khóa khuyên dùng: "${primaryProfile.shouldUse[0]}"`,
      nextStep: `Áp dụng kịch bản phá khóa: ${primaryProfile.closingScript}`
    };
    interactions.unshift(newInter);
    saveCrmInteractions(interactions);
    if (typeof renderCrmReminders === 'function') renderCrmReminders();
    if (typeof refreshClientDropdown === 'function') refreshClientDropdown();
  }

  if (typeof showToast === 'function') {
    showToast(`💾 Đã lưu kết quả đọc vị của ${clientName} & đồng bộ sang CRM!`, '✅');
  }
}

function copyDocViAnalysisReport() {
  const nameInput = document.getElementById('docViInputClientName');
  const clientName = (nameInput && nameInput.value.trim()) || currentDocViClient || 'Khách Hàng';
  const answeredCount = Object.keys(currentDocViAnswers).length;

  if (answeredCount === 0) {
    if (typeof showToast === 'function') {
      showToast('⚠️ Chưa có câu trả lời nào để sao chép!', '⚠️');
    }
    return;
  }

  // Calculate scores
  const scores = { nghingo: 0, tham: 0, san: 0, si: 0, ngaoman: 0 };
  Object.keys(currentDocViAnswers).forEach(qId => {
    const q = DOCVI_QUESTIONS.find(item => item.id === Number(qId));
    if (!q) return;
    const opt = q.options.find(o => o.id === currentDocViAnswers[qId]);
    if (opt && opt.traits) {
      Object.keys(opt.traits).forEach(t => {
        scores[t] = (scores[t] || 0) + opt.traits[t];
      });
    }
  });
  const totalScore = Object.values(scores).reduce((a, b) => a + b, 0) || 1;
  const sorted = Object.keys(scores).sort((a, b) => scores[b] - scores[a]);
  const primaryKey = sorted[0];
  const primaryProfile = DOCVI_PROFILES[primaryKey];
  const pct = Math.round((scores[primaryKey] / totalScore) * 100);

  let text = `=========================================\n`;
  text += `🎭 BÁO CÁO ĐỌC VỊ TÂM LÝ KHÁCH HÀNG BĐS\n`;
  text += `Khách hàng: ${clientName}\n`;
  text += `Tiến độ: ${answeredCount}/10 câu hỏi hành vi đã trả lời\n`;
  text += `Thời gian: ${new Date().toLocaleString('vi-VN')}\n`;
  text += `=========================================\n\n`;

  text += `🏆 TÂM LÝ CHỦ ĐẠO: ${primaryProfile.name} (${pct}%)\n`;
  text += `📌 Tổng quan: ${primaryProfile.summary}\n\n`;

  text += `📊 CƠ CẤU 5 NHÓM TÂM LÝ:\n`;
  sorted.forEach(k => {
    const p = DOCVI_PROFILES[k];
    const pPct = Math.round((scores[k] / totalScore) * 100);
    text += `• ${p.icon} ${p.name.split('—')[0].trim()}: ${pPct}%\n`;
  });

  text += `\n🗣️ NGÔN NGỮ TIẾP CẬN NÊN DÙNG:\n`;
  primaryProfile.shouldUse.forEach(u => {
    text += `  ✅ "${u}"\n`;
  });

  text += `\n❌ NHỮNG ĐIỀU TUYỆT ĐỐI TRÁNH:\n`;
  primaryProfile.shouldAvoid.forEach(a => {
    text += `  ⛔ ${a}\n`;
  });

  text += `\n🗝️ TỬ HUYỆT CẢM XÚC: ${primaryProfile.motive}\n`;
  text += `🎯 KỊCH BẢN CHỐT TRONG TUẦN:\n${primaryProfile.closingScript}\n`;
  text += `=========================================`;

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép báo cáo đọc vị khách hàng vào Clipboard!', '📋');
      }
    }).catch(() => {
      fallbackCopyText(text);
    });
  } else {
    fallbackCopyText(text);
  }
}

function openDocViDirect() {
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('crm');
  }
  if (typeof switchCrmSubtab === 'function') {
    switchCrmSubtab('docvi');
  }
  const el = document.getElementById('crmTabPaneDocVi');
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
}

function openDocViForSelectedCrmClient() {
  const select = document.getElementById('crmSelectClient');
  const clientName = select ? select.value : '';

  openDocViDirect();

  if (clientName) {
    const docViSelect = document.getElementById('docViSelectClient');
    if (docViSelect) docViSelect.value = clientName;
    onDocViClientSelected(clientName);
  }
}

