let portalsConfigCache = null;

function getPortalsConfig() {
  if (portalsConfigCache) return portalsConfigCache;
  if (typeof localStorage !== 'undefined') {
    const raw = localStorage.getItem(STORAGE_KEY_PORTALS_CONFIG);
    if (raw) {
      try {
        portalsConfigCache = JSON.parse(raw);
        if (!Array.isArray(portalsConfigCache.activePortalKeys)) {
          portalsConfigCache.activePortalKeys = ['bds_com_vn', 'chotot'];
        }
        if (!Array.isArray(portalsConfigCache.customPortals)) {
          portalsConfigCache.customPortals = [];
        }
        return portalsConfigCache;
      } catch (e) {
        console.error('Error parsing portals config:', e);
      }
    }
  }
  portalsConfigCache = {
    activePortalKeys: ['bds_com_vn', 'chotot'],
    customPortals: []
  };
  return portalsConfigCache;
}

function getActivePostingPlatforms() {
  const config = getPortalsConfig();
  const activeKeys = new Set(config.activePortalKeys || ['bds_com_vn', 'chotot']);
  
  // All active preset portals
  const activePresets = PRESET_VIETNAM_PORTALS.filter(p => activeKeys.has(p.key));
  
  // Custom portals added by user
  const customs = (config.customPortals || []).filter(p => activeKeys.has(p.key) || p.isActive !== false);

  return [
    ...BASE_SOCIAL_VIDEO_PLATFORMS,
    ...activePresets,
    ...customs
  ];
}

const POSTING_PLATFORMS = getActivePostingPlatforms();

function syncPostingPlatforms() {
  const active = getActivePostingPlatforms();
  POSTING_PLATFORMS.length = 0;
  POSTING_PLATFORMS.push(...active);
}

function savePortalsConfig(config) {
  portalsConfigCache = config;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_PORTALS_CONFIG, JSON.stringify(config));
    } catch (e) {
      console.error('Error saving portals config:', e);
    }
  }
  syncPostingPlatforms();
  updateChecklistHeaderBadge();
  renderPostingChecklist(false);
}

