let postingChecklistDataCache = null;

function getPostingChecklistData() {
  if (postingChecklistDataCache) return postingChecklistDataCache;
  if (typeof localStorage !== 'undefined') {
    const raw = localStorage.getItem(STORAGE_KEY_POSTING_CHECKLIST);
    if (raw) {
      try {
        postingChecklistDataCache = JSON.parse(raw);
        return postingChecklistDataCache;
      } catch (e) {
        console.error('Error parsing posting checklist data:', e);
      }
    }
  }
  postingChecklistDataCache = JSON.parse(JSON.stringify(DEFAULT_SAMPLE_CHECKLIST_DATA));
  return postingChecklistDataCache;
}

function savePostingChecklistData(data) {
  postingChecklistDataCache = data;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_POSTING_CHECKLIST, JSON.stringify(data));
    } catch (e) {
      console.error('Error saving posting checklist data:', e);
    }
  }
  updateChecklistHeaderBadge();
  renderMiniPostingTracker();
}

function getCurrentChecklistProperty() {
  const data = getPostingChecklistData();
  const activeId = data.activePropertyId || 'prop_sample_1';
  let prop = data.properties[activeId];
  if (!prop) {
    const keys = Object.keys(data.properties);
    if (keys.length > 0) {
      data.activePropertyId = keys[0];
      prop = data.properties[keys[0]];
    } else {
      data.properties.prop_sample_1 = JSON.parse(JSON.stringify(DEFAULT_SAMPLE_CHECKLIST_DATA.properties.prop_sample_1));
      data.activePropertyId = 'prop_sample_1';
      prop = data.properties.prop_sample_1;
    }
  }
  if (!prop.platforms) prop.platforms = {};
  POSTING_PLATFORMS.forEach(p => {
    if (!prop.platforms[p.key]) {
      prop.platforms[p.key] = { posted: false, postedAt: '', postUrl: '', notes: '' };
    }
  });
  return prop;
}

function onChecklistPropertyChange() {
  const select = document.getElementById('checklistPropertySelect');
  if (!select) return;
  const val = select.value;
  const data = getPostingChecklistData();
  data.activePropertyId = val;
  savePostingChecklistData(data);
  renderPostingChecklist();
}

function applyCurrentPropertyToChecklist() {
  let propData = AppState.currentPropertyData;
  const rawEl = document.getElementById('rawInfoInput');
  const rawText = rawEl ? rawEl.value : '';

  if (!propData && rawText.trim()) {
    try {
      propData = extractPropertyData(rawText);
    } catch (e) {}
  }

  const loc = propData && propData.location ? [propData.location.street, propData.location.ward, propData.location.district].filter(Boolean).join(', ') : 'Căn nhà đang mở';
  const price = propData && propData.price && propData.price.askingPrice ? propData.price.askingPrice : 'Chưa có giá';
  const area = propData && propData.area && propData.area.landArea ? `${propData.area.landArea}m²` : '';
  const struct = propData && propData.structure && propData.structure.floorDescription ? propData.structure.floorDescription : '';

  const id = 'prop_current_' + Date.now();
  const title = `${loc} - ${price}`;

  const data = getPostingChecklistData();
  data.properties[id] = {
    id,
    title,
    address: loc,
    price,
    area,
    structure: struct,
    updatedAt: new Date().toISOString(),
    platforms: {}
  };
  POSTING_PLATFORMS.forEach(p => {
    data.properties[id].platforms[p.key] = { posted: false, postedAt: '', postUrl: '', notes: '' };
  });
  data.activePropertyId = id;
  savePostingChecklistData(data);
  initChecklistModule();
  showToast(`Đã đưa "${title}" vào Checklist!`, '🏠');
}

function openNewPropertyChecklistPrompt() {
  const title = prompt('Nhập tên căn nhà mới cần quản lý checklist (Ví dụ: Nhà phố Q.Bình Thạnh, 7.2 tỷ):');
  if (!title || !title.trim()) return;

  const price = prompt('Nhập giá bán (Ví dụ: 7.2 Tỷ):', '') || 'Thương lượng';
  const address = prompt('Nhập địa chỉ/quận (Ví dụ: Nơ Trang Long, Bình Thạnh):', '') || title;

  const id = 'prop_custom_' + Date.now();
  const data = getPostingChecklistData();
  data.properties[id] = {
    id,
    title: title.trim(),
    address: address.trim(),
    price: price.trim(),
    area: '',
    structure: '',
    updatedAt: new Date().toISOString(),
    platforms: {}
  };
  POSTING_PLATFORMS.forEach(p => {
    data.properties[id].platforms[p.key] = { posted: false, postedAt: '', postUrl: '', notes: '' };
  });
  data.activePropertyId = id;
  savePostingChecklistData(data);
  initChecklistModule();
  showToast(`Đã tạo checklist cho "${title}"!`, '➕');
}

function togglePlatformCheck(platformKey, isChecked) {
  const data = getPostingChecklistData();
  const prop = getCurrentChecklistProperty();

  if (!prop.platforms[platformKey]) {
    prop.platforms[platformKey] = { posted: false, postedAt: '', postUrl: '', notes: '' };
  }

  prop.platforms[platformKey].posted = isChecked;
  if (isChecked) {
    if (!prop.platforms[platformKey].postedAt) {
      prop.platforms[platformKey].postedAt = new Date().toISOString().slice(0, 16);
    }
  }
  prop.updatedAt = new Date().toISOString();

  savePostingChecklistData(data);
  renderPostingChecklist(false);
}

function updatePlatformField(platformKey, field, value) {
  const data = getPostingChecklistData();
  const prop = getCurrentChecklistProperty();

  if (!prop.platforms[platformKey]) {
    prop.platforms[platformKey] = { posted: false, postedAt: '', postUrl: '', notes: '' };
  }

  prop.platforms[platformKey][field] = value;
  prop.updatedAt = new Date().toISOString();

  savePostingChecklistData(data);
}

function markAllPlatformsPosted() {
  const data = getPostingChecklistData();
  const prop = getCurrentChecklistProperty();
  const now = new Date().toISOString().slice(0, 16);

  POSTING_PLATFORMS.forEach(p => {
    if (!prop.platforms[p.key]) prop.platforms[p.key] = {};
    prop.platforms[p.key].posted = true;
    if (!prop.platforms[p.key].postedAt) {
      prop.platforms[p.key].postedAt = now;
    }
  });
  prop.updatedAt = new Date().toISOString();

  savePostingChecklistData(data);
  renderPostingChecklist();
  showToast('✅ Đã đánh dấu tất cả 12 nền tảng đã đăng xong!', '🎉');
}

function resetCurrentPropertyChecklist() {
  if (!confirm('Bạn có chắc chắn muốn đặt lại tất cả các nền tảng về CHƯA ĐĂNG cho căn nhà này?')) return;

  const data = getPostingChecklistData();
  const prop = getCurrentChecklistProperty();

  POSTING_PLATFORMS.forEach(p => {
    if (!prop.platforms[p.key]) prop.platforms[p.key] = {};
    prop.platforms[p.key].posted = false;
    prop.platforms[p.key].postedAt = '';
    prop.platforms[p.key].postUrl = '';
    prop.platforms[p.key].notes = '';
  });
  prop.updatedAt = new Date().toISOString();

  savePostingChecklistData(data);
  renderPostingChecklist();
  showToast('🔄 Đã đặt lại checklist cho căn nhà này!', 'ℹ️');
}

function openPostingChecklist() {
  switchSubsystem('checklist');
  

if (typeof window !== 'undefined') {
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
}

function openPostingChecklistForProperty(propId) {
  const data = getPostingChecklistData();
  if (data.properties[propId]) {
    data.activePropertyId = propId;
    savePostingChecklistData(data);
  }
  openPostingChecklist();
}

function updateChecklistHeaderBadge() {
  if (typeof document === 'undefined') return;
  const prop = getCurrentChecklistProperty();
  const total = POSTING_PLATFORMS.length;
  let postedCount = 0;
  POSTING_PLATFORMS.forEach(p => {
    if (prop.platforms && prop.platforms[p.key] && prop.platforms[p.key].posted) {
      postedCount++;
    }
  });

  const pct = Math.round((postedCount / total) * 100);

  const headerBadge = document.getElementById('headerChecklistCount');
  if (headerBadge) {
    headerBadge.textContent = `${postedCount}/${total}`;
  }

  const subtabBadge = document.getElementById('badgeSubtabChecklist');
  if (subtabBadge) {
    subtabBadge.textContent = `${postedCount}/${total}`;
  }

  const subsystemBadge = document.getElementById('badgeSubsystemChecklist');
  if (subsystemBadge) {
    subsystemBadge.textContent = `${postedCount}/${total}`;
  }

  const statCoverageRatioPill = document.getElementById('statChecklistCoverageRatioPill');
  if (statCoverageRatioPill) {
    statCoverageRatioPill.textContent = `${postedCount}/${total}`;
  }

  const statChecklistCoverage = document.getElementById('statChecklistCoveragePercent');
  if (statChecklistCoverage) {
    statChecklistCoverage.textContent = `${pct}%`;
  }

  const statCoverage = document.getElementById('statCrmCoveragePercent');
  if (statCoverage) {
    statCoverage.textContent = `${pct}%`;
  }

  const miniRatio = document.getElementById('miniTrackerRatio');
  if (miniRatio) {
    miniRatio.textContent = `${postedCount}/${total} kênh`;
  }

  if (typeof calculatePostingStreak === 'function') {
    const streak = calculatePostingStreak();
    const headStreak = document.getElementById('headerStreakCountBadge');
    if (headStreak) headStreak.textContent = `🔥 ${streak.currentStreak}N`;
    const subtabStreak = document.getElementById('subtabStreakBadge');
    if (subtabStreak) subtabStreak.textContent = `🔥 ${streak.currentStreak} Ngày`;
    const tabStreakCount = document.getElementById('tabStreakCountBadge');
    if (tabStreakCount) tabStreakCount.textContent = `🔥 ${streak.currentStreak} Ngày`;
  }
}

function renderPostingChecklist(rebuildDropdown = true) {
  if (typeof document === 'undefined') return;
  const prop = getCurrentChecklistProperty();
  const data = getPostingChecklistData();

  // 1. Dropdown
  if (rebuildDropdown) {
    const select = document.getElementById('checklistPropertySelect');
    if (select) {
      let optHtml = '';
      Object.keys(data.properties).forEach(id => {
        const item = data.properties[id];
        let pCount = 0;
        POSTING_PLATFORMS.forEach(p => {
          if (item.platforms && item.platforms[p.key] && item.platforms[p.key].posted) pCount++;
        });
        const isSel = id === data.activePropertyId ? 'selected' : '';
        optHtml += `<option value="${item.id}" ${isSel}>🏠 ${escapeHtml(item.title)} (${pCount}/${POSTING_PLATFORMS.length} kênh)</option>`;
      });
      select.innerHTML = optHtml;
    }
  }

  // 2. Summary specs
  const specsBox = document.getElementById('checklistPropSpecs');
  if (specsBox) {
    specsBox.innerHTML = `
      <span class="checklist-spec-tag price">💰 ${escapeHtml(prop.price || 'Chưa có giá')}</span>
      <span class="checklist-spec-tag location">📍 ${escapeHtml(prop.address || 'Chưa rõ địa chỉ')}</span>
      ${prop.area ? `<span class="checklist-spec-tag">📐 ${escapeHtml(prop.area)}</span>` : ''}
      ${prop.structure ? `<span class="checklist-spec-tag">🏠 ${escapeHtml(prop.structure)}</span>` : ''}
    `;
  }

  const timeEl = document.getElementById('checklistPropUpdatedTime');
  if (timeEl && prop.updatedAt) {
    const d = new Date(prop.updatedAt);
    timeEl.textContent = `🕒 Cập nhật: ${d.toLocaleDateString('vi-VN')} ${d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}`;
  }

  // 3. Progress bar & Health
  const total = POSTING_PLATFORMS.length;
  let postedCount = 0;
  POSTING_PLATFORMS.forEach(p => {
    if (prop.platforms && prop.platforms[p.key] && prop.platforms[p.key].posted) postedCount++;
  });
  const percent = Math.round((postedCount / total) * 100);

  const ratioEl = document.getElementById('checklistCoverageRatio');
  if (ratioEl) ratioEl.textContent = `${postedCount} / ${total} Nền Tảng (${percent}%)`;

  const fillEl = document.getElementById('checklistProgressFill');
  if (fillEl) fillEl.style.width = `${percent}%`;

  const healthBanner = document.getElementById('checklistHealthBanner');
  const healthText = document.getElementById('checklistHealthText');
  if (healthBanner && healthText) {
    healthBanner.className = 'checklist-health-banner';
    if (percent === 0) {
      healthBanner.classList.add('low');
      healthText.innerHTML = `<strong>Chưa đăng nền tảng nào!</strong> Hãy bắt đầu đẩy tin lên Facebook, Zalo hoặc Batdongsan.com.vn để thu hút khách hàng!`;
    } else if (percent < 35) {
      healthBanner.classList.add('low');
      healthText.innerHTML = `<strong>Độ phủ thấp (${percent}%)!</strong> Mới chỉ xuất hiện trên vài kênh. Hãy tăng cường đăng lên các hội nhóm và trang rao vặt.`;
    } else if (percent < 70) {
      healthBanner.classList.add('medium');
      healthText.innerHTML = `<strong>Độ phủ khá (${percent}%)!</strong> Đã có mặt trên các kênh cốt lõi. Hãy quét thêm kịch bản Zalo VIP và video ngắn.`;
    } else if (percent < 100) {
      healthBanner.classList.add('good');
      healthText.innerHTML = `<strong>Độ phủ rất tốt (${percent}%)!</strong> Đã xuất hiện trên hầu hết mạng xã hội và sàn tin rao chính.`;
    } else {
      healthBanner.classList.add('full');
      healthText.innerHTML = `<strong>🔥 Phủ sóng toàn diện 100%!</strong> Căn nhà đã hiện diện trên toàn bộ 12 nền tảng lớn nhất. Cơ hội chốt deal tối đa!`;
    }
  }

  // 4. Categories & Platforms Rows
  const categoriesWrap = document.getElementById('checklistCategoriesWrap');
  if (categoriesWrap) {
    const groups = ['video', 'social', 'portal'];
    const catHtml = groups.map(catKey => {
      const catDef = POSTING_CATEGORIES[catKey];
      const catPlatforms = POSTING_PLATFORMS.filter(p => p.category === catKey);
      const catPosted = catPlatforms.filter(p => prop.platforms && prop.platforms[p.key] && prop.platforms[p.key].posted).length;

      const itemsHtml = catPlatforms.map(p => {
        const itemData = (prop.platforms && prop.platforms[p.key]) || { posted: false, postedAt: '', postUrl: '', notes: '' };
        const isPosted = !!itemData.posted;
        const postedAtVal = itemData.postedAt || '';
        const postUrlVal = itemData.postUrl || '';
        const notesVal = itemData.notes || '';

        return `
          <div class="checklist-item-row ${isPosted ? 'is-posted' : ''}" id="row_${p.key}">
            <!-- Col 1: Checkbox & Name -->
            <div class="checklist-col-info">
              <input type="checkbox" class="checklist-custom-checkbox" 
                id="chk_${p.key}" 
                ${isPosted ? 'checked' : ''} 
                onchange="togglePlatformCheck('${p.key}', this.checked)"
                title="Bấm để đánh dấu Đã Đăng / Chưa Đăng">
              <span class="checklist-platform-icon">${p.icon}</span>
              <div class="checklist-platform-details">
                <div class="checklist-platform-name">
                  ${escapeHtml(p.name)}
                  <span class="checklist-spec-tag" style="font-size: 0.68rem;">${escapeHtml(p.badge)}</span>
                </div>
                <div class="checklist-platform-type">${escapeHtml(p.type)}</div>
                <span class="checklist-status-badge ${isPosted ? 'posted' : 'pending'}">
                  ${isPosted ? '✅ ĐÃ ĐĂNG' : '⏳ CHƯA ĐĂNG'}
                </span>
              </div>
            </div>

            <!-- Col 2: Date & Link -->
            <div class="checklist-col-link">
              <div class="checklist-input-group">
                <span style="font-size: 0.75rem; color: #94a3b8; width: 55px; flex-shrink: 0;">📅 Giờ:</span>
                <input type="datetime-local" class="checklist-input-sm" 
                  value="${escapeHtml(postedAtVal)}" 
                  onchange="updatePlatformField('${p.key}', 'postedAt', this.value)"
                  placeholder="Ngày giờ đăng">
              </div>
              <div class="checklist-input-group">
                <span style="font-size: 0.75rem; color: #94a3b8; width: 55px; flex-shrink: 0;">🔗 Link:</span>
                <input type="url" class="checklist-input-sm" 
                  value="${escapeHtml(postUrlVal)}" 
                  onchange="updatePlatformField('${p.key}', 'postUrl', this.value)"
                  placeholder="Dán link bài viết live (nếu có)...">
                ${postUrlVal ? `<a href="${escapeHtml(postUrlVal)}" target="_blank" rel="noopener noreferrer" class="btn-checklist-open-link" title="Mở link bài viết này trong tab mới">↗️ Xem</a>` : ''}
              </div>
            </div>

            <!-- Col 3: Notes -->
            <div class="checklist-col-notes">
              <div class="checklist-input-group">
                <span style="font-size: 0.75rem; color: #94a3b8; width: 55px; flex-shrink: 0;">📝 Note:</span>
                <input type="text" class="checklist-input-sm" 
                  value="${escapeHtml(notesVal)}" 
                  onchange="updatePlatformField('${p.key}', 'notes', this.value)"
                  placeholder="Ghi chú: Lượt view, số cmt, gói tin VIP, chi phí...">
              </div>
            </div>

            <!-- Col 4: Action Tools -->
            <div class="checklist-col-actions">
              <button type="button" class="btn-checklist-tool primary" onclick="copyPlatformContent('${p.key}')" title="Sao chép nội dung kịch bản hoặc bài viết tối ưu cho ${escapeHtml(p.name)}">
                📋 Copy Content
              </button>
              <a href="${p.url}" target="_blank" rel="noopener noreferrer" class="btn-checklist-tool launch" title="Mở trang tạo bài của ${escapeHtml(p.name)}">
                🚀 Mở Trang Đăng ↗
              </a>
              ${p.category === 'portal' ? (p.isCustom ? `
                <button type="button" class="btn-delete-portal-row" onclick="deleteCustomPortal('${p.key}')" title="Xóa sàn riêng này khỏi danh sách">
                  🗑️ Xóa
                </button>
              ` : `
                <button type="button" class="btn-delete-portal-row" onclick="hideOrDeactivatePortal('${p.key}')" title="Ẩn sàn này nếu bạn không dùng">
                  👁️ Ẩn
                </button>
              `) : ''}
            </div>
          </div>
        `;
      }).join('');

      const isPortalCat = catKey === 'portal';

      return `
        <div class="checklist-category-card">
          <div class="checklist-category-header">
            <div class="checklist-category-title">
              ${catDef.title}
            </div>
            ${isPortalCat ? `
              <div class="portal-category-tools">
                <button type="button" class="btn-portal-manage" onclick="openPortalConfigModal()" title="Tùy chọn danh sách các sàn BĐS bạn hay dùng hoặc thêm sàn mới">
                  ⚙️ Tùy Chỉnh Sàn Bạn Dùng (${catPlatforms.length} sàn)
                </button>
                <div class="checklist-category-count">
                  Đã đăng: ${catPosted} / ${catPlatforms.length} sàn
                </div>
              </div>
            ` : `
              <div class="checklist-category-count">
                Đã đăng: ${catPosted} / ${catPlatforms.length} nền tảng
              </div>
            `}
          </div>
          <div class="checklist-items-list">
            ${itemsHtml}
            ${isPortalCat ? `
              <div class="portal-add-dashed-card" onclick="openPortalConfigModal()" title="Bấm để bật thêm các sàn phổ biến hoặc thêm website riêng">
                <div class="portal-add-dashed-left">
                  <span style="font-size: 1.4rem;">➕</span>
                  <div>
                    <div class="portal-add-dashed-title">Bạn hay đăng tin trên sàn nào khác? (Alonhadat, Meey Land, Guland, Homedy, Sàn riêng...)</div>
                    <div class="portal-add-dashed-desc">Bấm vào đây để chọn trong 12 sàn lớn nhất VN hoặc thêm website / group riêng của công ty bạn!</div>
                  </div>
                </div>
                <span class="btn-portal-manage">⚙️ Tùy biến sàn &rarr;</span>
              </div>
            ` : ''}
          </div>
        </div>
      `;
    }).join('');

    categoriesWrap.innerHTML = catHtml;
  }

  updateChecklistHeaderBadge();
  renderMiniPostingTracker();
}

// ==========================================
// 15.3. QUẢN LÝ TÙY CHỌN & THÊM SÀN RAO VẶT BĐS RIÊNG
// ==========================================
function openPortalConfigModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('portalConfigModal');
  if (!modal) return;
  modal.style.display = 'flex';
  renderPortalConfigModal();
}

function closePortalConfigModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('portalConfigModal');
  if (modal) modal.style.display = 'none';
}

function renderPortalConfigModal() {
  if (typeof document === 'undefined') return;
  const config = getPortalsConfig();
  const activeKeys = new Set(config.activePortalKeys || ['bds_com_vn', 'chotot']);

  // 1. Render 12 Presets
  const presetsGrid = document.getElementById('portalPresetsGrid');
  if (presetsGrid) {
    presetsGrid.innerHTML = PRESET_VIETNAM_PORTALS.map(p => {
      const isActive = activeKeys.has(p.key);
      return `
        <div class="portal-preset-card ${isActive ? 'is-active' : ''}" onclick="togglePresetPortal('${p.key}')" title="Bấm để Bật / Tắt sàn ${escapeHtml(p.name)}">
          <div class="portal-preset-left">
            <span class="portal-preset-icon">${p.icon}</span>
            <div style="min-width: 0;">
              <div class="portal-preset-name">${escapeHtml(p.name)}</div>
              <div class="portal-preset-desc">${escapeHtml(p.type)}</div>
            </div>
          </div>
          <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 0.25rem;">
            <span class="portal-preset-badge">${escapeHtml(p.badge)}</span>
            <input type="checkbox" class="checklist-custom-checkbox" 
              ${isActive ? 'checked' : ''} 
              onclick="event.stopPropagation(); togglePresetPortal('${p.key}')" 
              style="width: 17px; height: 17px; margin: 0; cursor: pointer;">
          </div>
        </div>
      `;
    }).join('');
  }

  // 2. Render Custom Portals if any
  const customSection = document.getElementById('customPortalsSection');
  const customGrid = document.getElementById('customPortalsGrid');
  const customs = config.customPortals || [];
  if (customSection && customGrid) {
    if (customs.length > 0) {
      customSection.style.display = 'block';
      customGrid.innerHTML = customs.map(p => {
        return `
          <div class="portal-preset-card is-active">
            <div class="portal-preset-left">
              <span class="portal-preset-icon">${p.icon || '🌐'}</span>
              <div style="min-width: 0;">
                <div class="portal-preset-name">${escapeHtml(p.name)}</div>
                <div class="portal-preset-desc">${escapeHtml(p.url || 'Sàn riêng')}</div>
              </div>
            </div>
            <div style="display: flex; align-items: center; gap: 0.5rem;">
              <span class="portal-preset-badge" style="background: rgba(245, 158, 11, 0.2); color: #fbbf24;">${escapeHtml(p.badge || 'Sàn Riêng')}</span>
              <button type="button" class="btn-delete-portal-row" onclick="event.stopPropagation(); deleteCustomPortal('${p.key}')" title="Xóa sàn riêng này">
                🗑️
              </button>
            </div>
          </div>
        `;
      }).join('');
    } else {
      customSection.style.display = 'none';
      customGrid.innerHTML = '';
    }
  }
}

function togglePresetPortal(portalKey) {
  const config = getPortalsConfig();
  const set = new Set(config.activePortalKeys || ['bds_com_vn', 'chotot']);
  if (set.has(portalKey)) {
    if (set.size <= 1) {
      showToast('⚠️ Bạn cần giữ ít nhất 1 sàn rao vặt để theo dõi độ phủ sóng!', '⚠️');
      return;
    }
    set.delete(portalKey);
  } else {
    set.add(portalKey);
  }
  config.activePortalKeys = Array.from(set);
  savePortalsConfig(config);
  renderPortalConfigModal();
  showToast('✅ Đã cập nhật danh sách sàn theo dõi!', '⚙️');
}

function quickSelectTopPortals() {
  const config = getPortalsConfig();
  config.activePortalKeys = ['bds_com_vn', 'chotot', 'alonhadat'];
  savePortalsConfig(config);
  renderPortalConfigModal();
  showToast('⚡ Đã chọn Top 3 sàn BĐS phổ biến nhất (BĐS + Chợ Tốt + Alonhadat)!', '🚀');
}

function quickSelectAllPortals() {
  const config = getPortalsConfig();
  config.activePortalKeys = PRESET_VIETNAM_PORTALS.map(p => p.key);
  savePortalsConfig(config);
  renderPortalConfigModal();
  showToast('🌟 Đã bật toàn bộ 12 sàn rao vặt BĐS hàng đầu Việt Nam!', '🎉');
}

function resetPortalsConfig() {
  const config = getPortalsConfig();
  config.activePortalKeys = ['bds_com_vn', 'chotot'];
  savePortalsConfig(config);
  renderPortalConfigModal();
  showToast('🔄 Đã khôi phục cài đặt sàn mặc định (Batdongsan + Chợ Tốt)!', 'ℹ️');
}

function handleAddNewCustomPortal() {
  const nameEl = document.getElementById('customPortalNameInput');
  const urlEl = document.getElementById('customPortalUrlInput');
  const badgeEl = document.getElementById('customPortalBadgeInput');
  const iconEl = document.getElementById('customPortalIconSelect');

  const name = nameEl ? nameEl.value.trim() : '';
  const url = urlEl ? urlEl.value.trim() : '';
  const badge = badgeEl && badgeEl.value.trim() ? badgeEl.value.trim() : 'Sàn Riêng';
  const icon = iconEl ? iconEl.value : '🌐';

  if (!name || !url) {
    showToast('⚠️ Vui lòng nhập đầy đủ tên sàn và link website!', '⚠️');
    return;
  }

  const key = 'custom_' + Date.now();
  const newPortal = {
    key,
    category: 'portal',
    name,
    icon,
    type: 'Sàn BĐS riêng tùy chỉnh',
    badge,
    url,
    contentTarget: 'website_listing',
    isCustom: true,
    isActive: true
  };

  const config = getPortalsConfig();
  if (!Array.isArray(config.customPortals)) config.customPortals = [];
  config.customPortals.push(newPortal);
  if (!config.activePortalKeys.includes(key)) {
    config.activePortalKeys.push(key);
  }

  savePortalsConfig(config);

  if (nameEl) nameEl.value = '';
  if (urlEl) urlEl.value = '';

  renderPortalConfigModal();
  showToast(`🎉 Đã thêm sàn riêng "${name}" vào danh sách theo dõi!`, '✅');
}

function deleteCustomPortal(portalKey) {
  if (typeof confirm !== 'undefined' && !confirm('Bạn có chắc muốn xóa sàn riêng này khỏi danh sách?')) return;
  const config = getPortalsConfig();
  config.customPortals = (config.customPortals || []).filter(p => p.key !== portalKey);
  config.activePortalKeys = (config.activePortalKeys || []).filter(k => k !== portalKey);
  savePortalsConfig(config);
  renderPortalConfigModal();
  showToast('🗑️ Đã xóa sàn riêng khỏi danh sách!', 'ℹ️');
}

function hideOrDeactivatePortal(portalKey) {
  const config = getPortalsConfig();
  const set = new Set(config.activePortalKeys || ['bds_com_vn', 'chotot']);
  if (set.size <= 1) {
    showToast('⚠️ Cần giữ lại ít nhất 1 sàn trong danh sách!', '⚠️');
    return;
  }
  set.delete(portalKey);
  config.activePortalKeys = Array.from(set);
  savePortalsConfig(config);
  showToast('👁️ Đã ẩn sàn khỏi danh sách. Bạn có thể bật lại bất cứ lúc nào trong "Tùy Chỉnh Sàn"!', 'ℹ️');
}

function renderMiniPostingTracker() {
  if (typeof document === 'undefined') return;
  const chipsWrap = document.getElementById('miniTrackerChipsWrap');
  if (!chipsWrap) return;
  const prop = getCurrentChecklistProperty();

  chipsWrap.innerHTML = POSTING_PLATFORMS.map(p => {
    const isPosted = !!(prop.platforms && prop.platforms[p.key] && prop.platforms[p.key].posted);
    return `
      <div class="mini-tracker-chip ${isPosted ? 'active' : ''}" 
        onclick="togglePlatformCheck('${p.key}', ${!isPosted})" 
        title="Bấm để chuyển trạng thái Đã Đăng / Chưa Đăng">
        <span>${p.icon}</span>
        <span>${escapeHtml(p.name.split(' ')[0])}</span>
        <span>${isPosted ? '✅' : '⚪'}</span>
      </div>
    `;
  }).join('');
}

function copyPlatformContent(platformKey) {
  const pDef = POSTING_PLATFORMS.find(p => p.key === platformKey);
  if (!pDef) return;

  let textToCopy = '';
  if (pDef.contentTarget === 'video') {
    const scriptEl = document.getElementById('outputScript');
    if (scriptEl && scriptEl.value && scriptEl.value.trim()) {
      textToCopy = scriptEl.value.trim();
    } else {
      textToCopy = 'Kịch bản Video BĐS 14 Khối Chuẩn:\n\n' + (SAMPLE_RAW_DATA || '');
    }
  } else {
    const copyEl = document.getElementById('copyOutputTextarea');
    if (copyEl && copyEl.value && copyEl.value.trim()) {
      textToCopy = copyEl.value.trim();
    } else {
      textToCopy = 'Bài viết BĐS Đa Kênh:\n\n' + (SAMPLE_RAW_DATA || '');
    }
  }

  copyTextToClipboard(textToCopy, `nội dung cho ${pDef.name}`);
}

function copyChecklistReport() {
  const prop = getCurrentChecklistProperty();
  const total = POSTING_PLATFORMS.length;
  const postedList = [];
  const pendingList = [];

  POSTING_PLATFORMS.forEach(p => {
    const itemData = (prop.platforms && prop.platforms[p.key]) || {};
    if (itemData.posted) {
      let info = `• ${p.icon} ${p.name}`;
      if (itemData.postedAt) {
        const d = new Date(itemData.postedAt);
        info += ` (Đã đăng ${d.toLocaleDateString('vi-VN')} ${d.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })})`;
      }
      if (itemData.postUrl) info += `\n  🔗 Link: ${itemData.postUrl}`;
      if (itemData.notes) info += `\n  📝 ${itemData.notes}`;
      postedList.push(info);
    } else {
      pendingList.push(`• ${p.icon} ${p.name} (${p.type})`);
    }
  });

  const percent = Math.round((postedList.length / total) * 100);
  const now = new Date();
  const timeStr = `${now.toLocaleDateString('vi-VN')} lúc ${now.toLocaleTimeString('vi-VN', { hour: '2-digit', minute: '2-digit' })}`;

  const report = [
    `📊 BÁO CÁO TIẾN ĐỘ PHỦ SÓNG BĐS ĐA NỀN TẢNG`,
    `🏠 Sản phẩm: ${prop.title.toUpperCase()}`,
    `📍 Vị trí: ${prop.address || 'TP.HCM'}`,
    `💰 Mức giá: ${prop.price || 'Thương lượng'}`,
    `📅 Thời điểm báo cáo: ${timeStr}`,
    `--------------------------------------------------`,
    `🎯 MỨC ĐỘ PHỦ SÓNG: ${postedList.length}/${total} NỀN TẢNG (${percent}%)`,
    ``,
    `✅ CÁC KÊNH ĐÃ LÊN BÀI & TIẾP CẬN KHÁCH:`,
    postedList.length > 0 ? postedList.join('\n\n') : '(Chưa có kênh nào được đánh dấu)',
    ``,
    `⏳ CÁC KÊNH ĐANG TIẾP TỤC TRIỂN KHAI:`,
    pendingList.length > 0 ? pendingList.join('\n') : '(Đã hoàn thành xuất sắc 100% tất cả các kênh!)',
    ``,
    `👉 Báo cáo được tạo tự động từ CONTENT SO DO PRO SUITE 2026. Em sẽ tiếp tục theo dõi lượt tương tác và cập nhật ngay khi có khách hàng quan tâm hẹn xem nhà!`
  ].join('\n');

  copyTextToClipboard(report, 'báo cáo tiến độ phủ sóng gửi chủ nhà');
  return report;
}

function downloadChecklistReportTxt() {
  const prop = getCurrentChecklistProperty();
  const total = POSTING_PLATFORMS.length;
  const postedList = [];
  const pendingList = [];

  POSTING_PLATFORMS.forEach(p => {
    const itemData = (prop.platforms && prop.platforms[p.key]) || {};
    if (itemData.posted) {
      let info = `• ${p.icon} ${p.name}`;
      if (itemData.postedAt) info += ` (Đăng lúc: ${itemData.postedAt})`;
      if (itemData.postUrl) info += ` - Link: ${itemData.postUrl}`;
      if (itemData.notes) info += ` - Ghi chú: ${itemData.notes}`;
      postedList.push(info);
    } else {
      pendingList.push(`• ${p.icon} ${p.name}`);
    }
  });

  const percent = Math.round((postedList.length / total) * 100);
  const now = new Date().toISOString().slice(0, 10);

  const report = [
    `BÁO CÁO TIẾN ĐỘ PHỦ SÓNG BĐS ĐA NỀN TẢNG`,
    `Sản phẩm: ${prop.title}`,
    `Vị trí: ${prop.address}`,
    `Mức giá: ${prop.price}`,
    `Ngày xuất báo cáo: ${now}`,
    `Tiến độ: ${postedList.length}/${total} (${percent}%)`,
    `--------------------------------------------------`,
    `KÊNH ĐÃ ĐĂNG:`,
    postedList.join('\n'),
    `--------------------------------------------------`,
    `KÊNH CHƯA ĐĂNG:`,
    pendingList.join('\n')
  ].join('\n');

  if (typeof document !== 'undefined') {
    const blob = new Blob([report], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Bao_Cao_Phu_Song_${prop.title.replace(/[^a-zA-Z0-9_\u00C0-\u1EF9]/g, '_')}_${now}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('📥 Đã tải file báo cáo tiến độ (.txt)!', '💾');
  }
  return report;
}

function initChecklistModule() {
  const currentSubtab = (AppState.calendar && AppState.calendar.currentSubtab) || 'checklist';
  switchChecklistSubtab(currentSubtab);
  updateChecklistHeaderBadge();
  renderMiniPostingTracker();
}

// ========================================================
// PHÂN HỆ 03: CALENDAR ĐĂNG TIN, STREAK & DASHBOARD THỐNG KÊ
// ========================================================

if (typeof AppState !== 'undefined' && !AppState.calendar) {
  const _now = new Date();
  AppState.calendar = {
    year: _now.getFullYear(),
    month: _now.getMonth(), // 0 - 11
    selectedDate: `${_now.getFullYear()}-${String(_now.getMonth() + 1).padStart(2, '0')}-${String(_now.getDate()).padStart(2, '0')}`,
    currentSubtab: 'checklist'
  };
}

function switchChecklistSubtab(subtabKey) {
  if (typeof AppState !== 'undefined') {
    if (!AppState.calendar) AppState.calendar = {};
    AppState.calendar.currentSubtab = subtabKey;
  }

  if (typeof document === 'undefined') return;

  const btnChecklist = document.getElementById('btnChecklistSubtabChecklist');
  const btnCalendar = document.getElementById('btnChecklistSubtabCalendar');
  const btnAnalytics = document.getElementById('btnChecklistSubtabAnalytics');

  const paneChecklist = document.getElementById('checklistTabPaneChecklist');
  const paneCalendar = document.getElementById('checklistTabPaneCalendar');
  const paneAnalytics = document.getElementById('checklistTabPaneAnalytics');

  // Reset active classes
  if (btnChecklist) btnChecklist.classList.remove('active');
  if (btnCalendar) btnCalendar.classList.remove('active');
  if (btnAnalytics) btnAnalytics.classList.remove('active');

  if (paneChecklist) paneChecklist.style.display = 'none';
  if (paneCalendar) paneCalendar.style.display = 'none';
  if (paneAnalytics) paneAnalytics.style.display = 'none';

  if (subtabKey === 'calendar') {
    if (btnCalendar) btnCalendar.classList.add('active');
    if (paneCalendar) paneCalendar.style.display = 'flex';
    renderPostingCalendar();
  } else if (subtabKey === 'analytics') {
    if (btnAnalytics) btnAnalytics.classList.add('active');
    if (paneAnalytics) paneAnalytics.style.display = 'flex';
    renderPostingAnalytics();
  } else {
    if (btnChecklist) btnChecklist.classList.add('active');
    if (paneChecklist) paneChecklist.style.display = 'flex';
    renderPostingChecklist(false);
  }
}

function openPostingCalendar() {
  switchSubsystem('checklist');
  switchChecklistSubtab('calendar');
  if (typeof document !== 'undefined') {
    const el = document.getElementById('subsystemChecklistWorkspace');
    if (el && typeof el.scrollIntoView === 'function') {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}

function openPostingAnalytics() {
  switchSubsystem('checklist');
  switchChecklistSubtab('analytics');
  if (typeof document !== 'undefined') {
    const el = document.getElementById('subsystemChecklistWorkspace');
    if (el && typeof el.scrollIntoView === 'function') {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }
}

function getPostingEventsList() {
  const data = getPostingChecklistData();
  const props = data.properties || {};
  const events = [];
  const platformsByKey = {};
  POSTING_PLATFORMS.forEach(p => { platformsByKey[p.key] = p; });

  Object.keys(props).forEach(propId => {
    const prop = props[propId];
    if (!prop || !prop.platforms) return;
    Object.keys(prop.platforms).forEach(pKey => {
      const pData = prop.platforms[pKey];
      if (pData && pData.posted) {
        const postedAt = pData.postedAt || prop.updatedAt || new Date().toISOString();
        const dateStr = postedAt.substring(0, 10);
        const pMeta = platformsByKey[pKey] || {
          key: pKey,
          name: pKey,
          icon: '🌐',
          category: 'portal',
          badge: 'Kênh BĐS'
        };
        events.push({
          id: `${propId}_${pKey}_${dateStr}`,
          propertyId: propId,
          propertyTitle: prop.title || 'Căn nhà chưa đặt tên',
          propertyAddress: prop.address || '',
          propertyPrice: prop.price || '',
          platformKey: pKey,
          platformName: pMeta.name,
          platformIcon: pMeta.icon,
          platformCategory: pMeta.category || 'portal',
          platformBadge: pMeta.badge || '',
          postedAt: postedAt,
          dateStr: dateStr,
          postUrl: pData.postUrl || '',
          notes: pData.notes || ''
        });
      }
    });
  });

  events.sort((a, b) => (b.postedAt || '').localeCompare(a.postedAt || ''));
  return events;
}

function calculatePostingStreak() {
  const events = getPostingEventsList();
  const activeDates = new Set(events.map(e => e.dateStr));

  const now = new Date();
  const formatDate = (d) => {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
  };

  const todayStr = formatDate(now);
  const hasPostedToday = activeDates.has(todayStr);

  let currentStreak = 0;
  let checkDate = new Date(now);
  if (!hasPostedToday) {
    checkDate.setDate(checkDate.getDate() - 1);
  }

  while (true) {
    const dStr = formatDate(checkDate);
    if (activeDates.has(dStr)) {
      currentStreak++;
      checkDate.setDate(checkDate.getDate() - 1);
    } else {
      break;
    }
  }

  const sortedDates = Array.from(activeDates).sort();
  let longestStreak = 0;
  let tempStreak = 0;
  let prevDateObj = null;

  for (const dStr of sortedDates) {
    const curDateObj = new Date(dStr + 'T00:00:00');
    if (!prevDateObj) {
      tempStreak = 1;
    } else {
      const diffDays = Math.round((curDateObj - prevDateObj) / (1000 * 60 * 60 * 24));
      if (diffDays === 1) {
        tempStreak++;
      } else if (diffDays > 1) {
        tempStreak = 1;
      }
    }
    if (tempStreak > longestStreak) longestStreak = tempStreak;
    prevDateObj = curDateObj;
  }

  if (currentStreak === 0 && sortedDates.length > 0) {
    let fallbackStreak = 0;
    let curCheck = new Date(sortedDates[sortedDates.length - 1] + 'T00:00:00');
    while (true) {
      const ds = formatDate(curCheck);
      if (activeDates.has(ds)) {
        fallbackStreak++;
        curCheck.setDate(curCheck.getDate() - 1);
      } else {
        break;
      }
    }
    currentStreak = fallbackStreak;
  }

  if (currentStreak > longestStreak) longestStreak = currentStreak;

  let levelTitle = 'Người Khởi Động';
  let levelBadge = 'Tập Sự 🌱';
  let levelIcon = '🌱';
  let levelColor = '#34d399';
  let levelAdvice = 'Hãy duy trì đăng ít nhất 1 tin/video mỗi ngày để thuật toán nhận diện tài khoản tích cực!';

  if (currentStreak >= 15) {
    levelTitle = 'Huyền Thoại Content BĐS';
    levelBadge = 'Huyền Thoại 💎';
    levelIcon = '💎';
    levelColor = '#a855f7';
    levelAdvice = 'Đẳng cấp vượt trội! Bạn đang nằm trong Top 1% môi giới duy trì phủ sóng liên tục đỉnh cao.';
  } else if (currentStreak >= 8) {
    levelTitle = 'Bậc Thầy Phủ Sóng';
    levelBadge = 'Bậc Thầy 🥇';
    levelIcon = '🥇';
    levelColor = '#fbbf24';
    levelAdvice = 'Nhịp độ hoàn hảo! Khách hàng tiềm năng và tương tác tự nhiên đang đổ về rất đều đặn.';
  } else if (currentStreak >= 4) {
    levelTitle = 'Chiến Binh Đăng Tin';
    levelBadge = 'Chiến Binh 🥈';
    levelIcon = '🥈';
    levelColor = '#38bdf8';
    levelAdvice = 'Đà tiến triển xuất sắc! Giữ vững chuỗi để sớm đạt mốc 8 ngày - Bậc Thầy Phủ Sóng.';
  } else if (currentStreak >= 1) {
    levelTitle = 'Tia Lửa Mới Bật';
    levelBadge = 'Khởi Sắc 🔥';
    levelIcon = '🔥';
    levelColor = '#f97316';
    levelAdvice = 'Ngọn lửa đã thắp sáng! Tiếp tục ngày mai để kích hoạt chuỗi Chiến Binh Đăng Tin!';
  } else {
    levelTitle = 'Chưa Kích Hoạt Streak';
    levelBadge = 'Bắt Đầu Ngay 🚀';
    levelIcon = '🚀';
    levelColor = '#94a3b8';
    levelAdvice = 'Đăng ngay 1 bài hoặc video hôm nay để bắt đầu chuỗi streak rực rỡ!';
  }

  return {
    currentStreak,
    longestStreak,
    hasPostedToday,
    totalActiveDays: activeDates.size,
    totalPosts: events.length,
    levelTitle,
    levelBadge,
    levelIcon,
    levelColor,
    levelAdvice
  };
}

function getContentAnalyticsData() {
  const events = getPostingEventsList();
  const data = getPostingChecklistData();
  const props = data.properties || {};
  const propKeys = Object.keys(props);
  const totalProps = propKeys.length;

  let activePropsCount = 0;
  let totalCoveragePctSum = 0;
  const totalPlatformsCount = POSTING_PLATFORMS.length;

  const propertyMatrix = [];
  propKeys.forEach(pId => {
    const prop = props[pId];
    if (!prop) return;
    let postedChannels = 0;
    const coveredChips = [];
    const missingChips = [];

    POSTING_PLATFORMS.forEach(p => {
      const isPosted = prop.platforms && prop.platforms[p.key] && prop.platforms[p.key].posted;
      if (isPosted) {
        postedChannels++;
        coveredChips.push(p);
      } else {
        missingChips.push(p);
      }
    });

    if (postedChannels > 0) activePropsCount++;
    const propPct = totalPlatformsCount > 0 ? Math.round((postedChannels / totalPlatformsCount) * 100) : 0;
    totalCoveragePctSum += propPct;

    propertyMatrix.push({
      id: pId,
      title: prop.title || 'Căn nhà',
      price: prop.price || '',
      address: prop.address || '',
      postedCount: postedChannels,
      totalCount: totalPlatformsCount,
      percent: propPct,
      coveredChips,
      missingChips
    });
  });

  const avgCoverage = totalProps > 0 ? Math.round(totalCoveragePctSum / totalProps) : 0;

  let videoCount = 0;
  let socialCount = 0;
  let portalCount = 0;

  events.forEach(e => {
    if (e.platformCategory === 'video') videoCount++;
    else if (e.platformCategory === 'social') socialCount++;
    else portalCount++;
  });

  const totalEvents = events.length;
  const videoPct = totalEvents > 0 ? Math.round((videoCount / totalEvents) * 100) : 0;
  const socialPct = totalEvents > 0 ? Math.round((socialCount / totalEvents) * 100) : 0;
  const portalPct = totalEvents > 0 ? Math.round((portalCount / totalEvents) * 100) : 0;

  const platformCounts = {};
  POSTING_PLATFORMS.forEach(p => {
    platformCounts[p.key] = {
      meta: p,
      count: 0
    };
  });
  events.forEach(e => {
    if (platformCounts[e.platformKey]) {
      platformCounts[e.platformKey].count++;
    }
  });

  const platformStats = Object.values(platformCounts).sort((a, b) => b.count - a.count);
  const topPlatform = platformStats.length > 0 && platformStats[0].count > 0 ? platformStats[0].meta.name : 'Chưa có';

  const streak = calculatePostingStreak();
  const healthScore = Math.min(100, Math.round((avgCoverage * 0.45) + (Math.min(streak.currentStreak, 14) / 14 * 35) + (Math.min(totalEvents, 20) / 20 * 20)));

  return {
    totalPosts: totalEvents,
    activePropsCount,
    totalProps,
    avgCoverage,
    topPlatform,
    healthScore,
    categoryCounts: {
      video: { count: videoCount, percent: videoPct },
      social: { count: socialCount, percent: socialPct },
      portal: { count: portalCount, percent: portalPct }
    },
    platformStats,
    propertyMatrix,
    streak
  };
}

function changeCalendarMonth(delta) {
  if (!AppState.calendar) {
    const _now = new Date();
    AppState.calendar = { year: _now.getFullYear(), month: _now.getMonth() };
  }
  let newMonth = AppState.calendar.month + delta;
  let newYear = AppState.calendar.year;
  if (newMonth < 0) {
    newMonth = 11;
    newYear--;
  } else if (newMonth > 11) {
    newMonth = 0;
    newYear++;
  }
  AppState.calendar.month = newMonth;
  AppState.calendar.year = newYear;
  renderPostingCalendar();
}

function goToCalendarToday() {
  const _now = new Date();
  if (!AppState.calendar) AppState.calendar = {};
  AppState.calendar.year = _now.getFullYear();
  AppState.calendar.month = _now.getMonth();
  AppState.calendar.selectedDate = `${_now.getFullYear()}-${String(_now.getMonth() + 1).padStart(2, '0')}-${String(_now.getDate()).padStart(2, '0')}`;
  renderPostingCalendar();
}

function selectCalendarDate(dateStr) {
  if (!AppState.calendar) AppState.calendar = {};
  AppState.calendar.selectedDate = dateStr;

  if (typeof document === 'undefined') return;
  const cells = document.querySelectorAll('.calendar-day-cell');
  cells.forEach(c => {
    if (c.getAttribute('data-date') === dateStr) {
      c.classList.add('is-selected');
    } else {
      c.classList.remove('is-selected');
    }
  });

  renderCalendarDayDetails(dateStr);
}

function renderPostingCalendar() {
  if (typeof document === 'undefined') return;

  if (!AppState.calendar) {
    const _now = new Date();
    AppState.calendar = {
      year: _now.getFullYear(),
      month: _now.getMonth(),
      selectedDate: `${_now.getFullYear()}-${String(_now.getMonth() + 1).padStart(2, '0')}-${String(_now.getDate()).padStart(2, '0')}`
    };
  }

  const { year, month, selectedDate } = AppState.calendar;
  const streak = calculatePostingStreak();

  // 1. Render Streak Dashboard Banner
  const bannerEl = document.getElementById('streakDashboardBanner');
  if (bannerEl) {
    bannerEl.innerHTML = `
      <div class="streak-card highlight">
        <div class="streak-card-top">
          <span class="streak-card-label" style="color: #fb923c;">Chuỗi Đăng Liên Tiếp</span>
          <span class="streak-card-icon streak-flame-anim">🔥</span>
        </div>
        <div class="streak-card-val" style="color: #fdba74;">
          ${streak.currentStreak} Ngày
        </div>
        <div class="streak-card-sub">
          ${streak.hasPostedToday ? '✅ Hôm nay bạn đã lên bài phủ sóng!' : '⏳ Đăng ngay bài hôm nay để giữ streak!'}
        </div>
      </div>

      <div class="streak-card">
        <div class="streak-card-top">
          <span class="streak-card-label">Kỷ Lục Chuỗi Dài Nhất</span>
          <span class="streak-card-icon">🏆</span>
        </div>
        <div class="streak-card-val" style="color: #fbbf24;">
          ${streak.longestStreak} Ngày
        </div>
        <div class="streak-card-sub">
          Danh hiệu: <strong style="color: ${streak.levelColor}">${streak.levelBadge}</strong>
        </div>
      </div>

      <div class="streak-card">
        <div class="streak-card-top">
          <span class="streak-card-label">Ngày Hoạt Động (Total)</span>
          <span class="streak-card-icon">🗓️</span>
        </div>
        <div class="streak-card-val" style="color: #38bdf8;">
          ${streak.totalActiveDays} Ngày
        </div>
        <div class="streak-card-sub">
          Số ngày có bài đăng được ghi nhận
        </div>
      </div>

      <div class="streak-card">
        <div class="streak-card-top">
          <span class="streak-card-label">Tổng Lượt Đăng Đa Kênh</span>
          <span class="streak-card-icon">🚀</span>
        </div>
        <div class="streak-card-val" style="color: #34d399;">
          ${streak.totalPosts} Lượt
        </div>
        <div class="streak-card-sub">
          Phủ khắp Video, Social & Sàn BĐS
        </div>
      </div>
    `;
  }

  // 2. Render Month Title
  const monthTitleEl = document.getElementById('calendarMonthTitle');
  if (monthTitleEl) {
    const monthNumStr = String(month + 1).padStart(2, '0');
    monthTitleEl.textContent = `Tháng ${monthNumStr} / ${year}`;
  }

  // 3. Render Calendar Grid Table
  const tbodyEl = document.getElementById('calendarGridTbody');
  if (tbodyEl) {
    const events = getPostingEventsList();
    const eventsByDate = {};
    events.forEach(e => {
      if (!eventsByDate[e.dateStr]) eventsByDate[e.dateStr] = [];
      eventsByDate[e.dateStr].push(e);
    });

    const now = new Date();
    const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

    const firstDay = new Date(year, month, 1);
    const startDayIndex = (firstDay.getDay() + 6) % 7; // Monday = 0
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const daysInPrevMonth = new Date(year, month, 0).getDate();

    let rowsHtml = '';
    let currentDayCount = 1;
    let nextMonthDayCount = 1;

    for (let row = 0; row < 6; row++) {
      let cellsHtml = '';
      for (let col = 0; col < 7; col++) {
        const cellIndex = row * 7 + col;
        let dayNum = 0;
        let isCurrentMonth = true;
        let cellDateStr = '';

        if (cellIndex < startDayIndex) {
          isCurrentMonth = false;
          dayNum = daysInPrevMonth - startDayIndex + cellIndex + 1;
          const prevMonthNum = month === 0 ? 12 : month;
          const prevYear = month === 0 ? year - 1 : year;
          cellDateStr = `${prevYear}-${String(prevMonthNum).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
        } else if (currentDayCount <= daysInMonth) {
          dayNum = currentDayCount;
          cellDateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
          currentDayCount++;
        } else {
          isCurrentMonth = false;
          dayNum = nextMonthDayCount++;
          const nextMonthNum = month === 11 ? 1 : month + 2;
          const nextYear = month === 11 ? year + 1 : year;
          cellDateStr = `${nextYear}-${String(nextMonthNum).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
        }

        const isToday = cellDateStr === todayStr;
        const isSelected = cellDateStr === selectedDate;
        const dayEvents = eventsByDate[cellDateStr] || [];
        const hasPosts = dayEvents.length > 0;
        const distinctPlatforms = new Set(dayEvents.map(e => e.platformKey)).size;

        let heatClass = '';
        if (hasPosts) {
          if (dayEvents.length >= 6) heatClass = 'has-posts heat-3';
          else if (dayEvents.length >= 3) heatClass = 'has-posts heat-2';
          else heatClass = 'has-posts heat-1';
        }

        const otherMonthClass = !isCurrentMonth ? 'is-other-month' : '';
        const todayClass = isToday ? 'is-today' : '';
        const selectedClass = isSelected ? 'is-selected' : '';

        const icons = Array.from(new Set(dayEvents.map(e => e.platformIcon))).slice(0, 4).join(' ');

        cellsHtml += `
          <td class="calendar-day-cell ${otherMonthClass} ${todayClass} ${selectedClass} ${heatClass}" 
              data-date="${cellDateStr}" 
              onclick="selectCalendarDate('${cellDateStr}')"
              title="${cellDateStr}: ${dayEvents.length} lượt đăng">
            <div class="calendar-day-header">
              <span class="calendar-day-num">${dayNum}</span>
              ${isToday ? '<span style="font-size: 0.65rem; color: #2dd4bf; font-weight: 800;">Nay</span>' : ''}
            </div>
            ${hasPosts ? `
              <div class="calendar-chips-container">
                <span class="calendar-post-chip ${dayEvents.length >= 6 ? 'heat-3' : ''}">
                  ⚡ ${dayEvents.length} bài
                </span>
                <div style="font-size: 0.72rem; line-height: 1; margin-top: 2px;">
                  ${icons}
                </div>
              </div>
            ` : ''}
          </td>
        `;
      }
      rowsHtml += `<tr>${cellsHtml}</tr>`;
      if (currentDayCount > daysInMonth && row >= 4) break;
    }
    tbodyEl.innerHTML = rowsHtml;
  }

  // 4. Render Day Details Drawer
  renderCalendarDayDetails(selectedDate || todayStr);
}

function renderCalendarDayDetails(dateStr) {
  if (typeof document === 'undefined') return;
  const drawer = document.getElementById('calendarDayDrawer');
  if (!drawer) return;

  const events = getPostingEventsList();
  const dayEvents = events.filter(e => e.dateStr === dateStr);

  const parts = (dateStr || '').split('-');
  const displayDate = parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : dateStr;

  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const isToday = dateStr === todayStr;

  if (dayEvents.length === 0) {
    drawer.innerHTML = `
      <div class="calendar-day-drawer-header">
        <div class="calendar-day-drawer-title">
          <span>📅</span> Ngày ${escapeHtml(displayDate)} ${isToday ? '<span style="color:#2dd4bf;font-size:0.8rem;margin-left:0.5rem;">(Hôm nay)</span>' : ''}
        </div>
        <button type="button" class="btn-main-action" onclick="openQuickLogModal('${dateStr}')" style="font-size: 0.8rem; padding: 0.4rem 0.9rem;">
          ➕ Thêm Lượt Đăng Cho Ngày Này
        </button>
      </div>
      <div style="text-align: center; padding: 1.5rem; color: var(--text-muted); font-size: 0.88rem;">
        <div>☕ Chưa có bài đăng nào được ghi nhận cho ngày này.</div>
        <div style="font-size: 0.78rem; margin-top: 0.35rem; color: #64748b;">
          Đăng bài đều đặn mỗi ngày giúp tài khoản của bạn luôn giữ vị thế ưu tiên trên thuật toán!
        </div>
      </div>
    `;
    return;
  }

  const distinctPlatforms = new Set(dayEvents.map(e => e.platformKey)).size;
  const distinctProps = new Set(dayEvents.map(e => e.propertyId)).size;

  const cardsHtml = dayEvents.map(e => {
    return `
      <div class="calendar-day-post-card">
        <div class="calendar-post-prop-name">${escapeHtml(e.propertyTitle)}</div>
        <div style="font-size: 0.74rem; color: #94a3b8;">${escapeHtml(e.propertyAddress)}</div>
        <div class="calendar-post-platform-row">
          <span style="font-size: 0.82rem; font-weight: 700; color: #34d399; display: flex; align-items: center; gap: 0.3rem;">
            <span>${e.platformIcon}</span> ${escapeHtml(e.platformName)}
          </span>
          <span class="calendar-post-time">🕒 ${(e.postedAt || '').slice(11, 16) || 'Trong ngày'}</span>
        </div>
        ${e.postUrl ? `
          <div style="margin-top: 0.2rem;">
            <a href="${escapeHtml(e.postUrl)}" target="_blank" rel="noopener noreferrer" class="btn-checklist-open-link" style="font-size: 0.74rem;">
              🔗 Xem bài live ↗
            </a>
          </div>
        ` : ''}
        ${e.notes ? `
          <div style="font-size: 0.74rem; color: #cbd5e1; background: rgba(0,0,0,0.25); padding: 0.3rem 0.5rem; border-radius: 4px;">
            📝 ${escapeHtml(e.notes)}
          </div>
        ` : ''}
      </div>
    `;
  }).join('');

  drawer.innerHTML = `
    <div class="calendar-day-drawer-header">
      <div class="calendar-day-drawer-title">
        <span>📅</span> Ngày ${escapeHtml(displayDate)} ${isToday ? '<span style="color:#2dd4bf;font-size:0.8rem;margin-left:0.5rem;">(Hôm nay)</span>' : ''}
        <span class="checklist-spec-tag" style="background: rgba(16, 185, 129, 0.2); color: #34d399; margin-left: 0.5rem;">
          ${dayEvents.length} Lượt Đăng • ${distinctPlatforms} Nền Tảng • ${distinctProps} Căn Nhà
        </span>
      </div>
      <button type="button" class="btn-main-action" onclick="openQuickLogModal('${dateStr}')" style="font-size: 0.8rem; padding: 0.4rem 0.9rem;">
        ➕ Thêm Lượt Đăng Nữa
      </button>
    </div>
    <div class="calendar-day-posts-list">
      ${cardsHtml}
    </div>
  `;
}

function openQuickLogModal(defaultDate = '', defaultPropId = '') {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('quickLogPostModal');
  if (!modal) return;

  const dateInput = document.getElementById('quickLogDateInput');
  const propSelect = document.getElementById('quickLogPropSelect');
  const grid = document.getElementById('quickLogPlatformsGrid');

  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

  if (dateInput) {
    dateInput.value = defaultDate || todayStr;
  }

  const data = getPostingChecklistData();
  const props = data.properties || {};

  if (propSelect) {
    propSelect.innerHTML = Object.keys(props).map(pId => {
      const p = props[pId];
      const isSel = (defaultPropId && defaultPropId === pId) || (!defaultPropId && pId === data.activePropertyId);
      return `<option value="${p.id}" ${isSel ? 'selected' : ''}>${escapeHtml(p.title)} (${escapeHtml(p.price || '')})</option>`;
    }).join('');
  }

  if (grid) {
    grid.innerHTML = POSTING_PLATFORMS.map(p => {
      return `
        <label style="display: flex; align-items: center; justify-content: space-between; padding: 0.45rem 0.6rem; background: rgba(30,41,59,0.6); border: 1px solid rgba(255,255,255,0.06); border-radius: 6px; cursor: pointer;">
          <div style="display: flex; align-items: center; gap: 0.4rem; min-width: 0;">
            <span>${p.icon}</span>
            <span style="font-size: 0.8rem; font-weight: 700; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${escapeHtml(p.name)}</span>
          </div>
          <input type="checkbox" name="quickLogPlatformCheckbox" value="${p.key}" class="checklist-custom-checkbox" style="width: 16px; height: 16px; margin: 0;">
        </label>
      `;
    }).join('');
  }

  modal.style.display = 'flex';
}

function closeQuickLogModal() {
  if (typeof document === 'undefined') return;
  const modal = document.getElementById('quickLogPostModal');
  if (modal) modal.style.display = 'none';
}

function handleSaveQuickLogPost() {
  const dateInput = document.getElementById('quickLogDateInput');
  const propSelect = document.getElementById('quickLogPropSelect');
  const urlInput = document.getElementById('quickLogUrlInput');
  const notesInput = document.getElementById('quickLogNotesInput');

  const dateVal = dateInput ? dateInput.value : '';
  const propId = propSelect ? propSelect.value : '';
  const postUrl = urlInput ? urlInput.value.trim() : '';
  const notes = notesInput ? notesInput.value.trim() : '';

  if (!dateVal || !propId) {
    showToast('⚠️ Vui lòng chọn đầy đủ ngày và căn nhà!', '⚠️');
    return;
  }

  const checkboxes = document.querySelectorAll('input[name="quickLogPlatformCheckbox"]:checked');
  if (checkboxes.length === 0) {
    showToast('⚠️ Vui lòng tích chọn ít nhất 1 nền tảng bạn đã đăng!', '⚠️');
    return;
  }

  const data = getPostingChecklistData();
  const prop = data.properties[propId];
  if (!prop) return;
  if (!prop.platforms) prop.platforms = {};

  const nowTime = new Date().toTimeString().slice(0, 5);
  const postedAt = `${dateVal}T${nowTime}`;

  checkboxes.forEach(cb => {
    const pKey = cb.value;
    prop.platforms[pKey] = {
      posted: true,
      postedAt: postedAt,
      postUrl: postUrl || (prop.platforms[pKey] && prop.platforms[pKey].postUrl) || '',
      notes: notes || (prop.platforms[pKey] && prop.platforms[pKey].notes) || ''
    };
  });

  prop.updatedAt = new Date().toISOString();
  savePostingChecklistData(data);
  closeQuickLogModal();

  showToast(`✅ Đã lưu ${checkboxes.length} lượt đăng và cập nhật Streak!`, '🔥');

  renderPostingCalendar();
  if (AppState.calendar && AppState.calendar.currentSubtab === 'analytics') {
    renderPostingAnalytics();
  }
}

