function copyAnalyticsExecutiveReport() {
  const analytics = getContentAnalyticsData();
  const streak = analytics.streak;
  const user = typeof getUserProfile === 'function' ? getUserProfile() : { fullName: 'Môi Giới BĐS', phone: '' };

  const now = new Date();
  const dateStr = `${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`;

  const propsSummary = analytics.propertyMatrix.map((p, idx) => {
    return `${idx + 1}. ${p.title} (${p.price}): Đạt ${p.postedCount}/${p.totalCount} kênh (${p.percent}%)`;
  }).join('\n');

  const report = [
    `📊 BÁO CÁO TỔNG QUAN PHỦ SÓNG CONTENT BĐS ĐA NỀN TẢNG`,
    `Người lập: ${user.fullName || 'Môi Giới'} ${user.phone ? '• ' + user.phone : ''}`,
    `Ngày xuất báo cáo: ${dateStr}`,
    `--------------------------------------------------`,
    `🔥 CHUỖI ĐĂNG LIÊN TIẾP (STREAK): ${streak.currentStreak} NGÀY LIÊN TIẾP`,
    `🏆 Cấp bậc: ${streak.levelBadge} - ${streak.levelTitle}`,
    `🚀 Tổng lượt đăng toàn hệ thống: ${analytics.totalPosts} lượt`,
    `🏠 BĐS đang phủ sóng: ${analytics.activePropsCount} / ${analytics.totalProps} căn nhà`,
    `🌐 Độ phủ sóng trung bình: ${analytics.avgCoverage}%`,
    `🥇 Kênh hoạt động năng nổ nhất: ${analytics.topPlatform}`,
    `🎯 Điểm sức khỏe chiến dịch: ${analytics.healthScore}/100`,
    `--------------------------------------------------`,
    `📈 CƠ CẤU 3 TRỤ CỘT TRUYỀN THÔNG:`,
    `• 🎬 Mạng Video Ngắn: ${analytics.categoryCounts.video.count} bài (${analytics.categoryCounts.video.percent}%)`,
    `• 👥 Mạng Xã Hội: ${analytics.categoryCounts.social.count} bài (${analytics.categoryCounts.social.percent}%)`,
    `• 🌐 Sàn Rao Vặt BĐS: ${analytics.categoryCounts.portal.count} bài (${analytics.categoryCounts.portal.percent}%)`,
    `--------------------------------------------------`,
    `🏠 TIẾN ĐỘ TỪNG BẤT ĐỘNG SẢN:`,
    propsSummary || '(Chưa có dữ liệu)',
    `--------------------------------------------------`,
    `CONTENT SO DO © 2026 — STUDIO VIDEO & BÀI VIẾT BĐS ĐA KÊNH`
  ].join('\n');

  if (typeof navigator !== 'undefined' && navigator.clipboard) {
    navigator.clipboard.writeText(report).then(() => {
      showToast('📋 Đã copy báo cáo tổng quan vào clipboard!', '✅');
    }).catch(() => {
      showToast('📋 Đã tạo xong báo cáo tổng quan!', '✅');
    });
  } else {
    showToast('📋 Đã tạo xong báo cáo tổng quan!', '✅');
  }

  return report;
}

function downloadAnalyticsReportCsv() {
  const events = getPostingEventsList();
  const header = ['Căn Nhà', 'Địa Chỉ', 'Mức Giá', 'Nền Tảng', 'Nhóm Kênh', 'Thời Gian Đăng', 'Link Bài Đăng', 'Ghi Chú'];

  const rows = events.map(e => [
    `"${(e.propertyTitle || '').replace(/"/g, '""')}"`,
    `"${(e.propertyAddress || '').replace(/"/g, '""')}"`,
    `"${(e.propertyPrice || '').replace(/"/g, '""')}"`,
    `"${(e.platformName || '').replace(/"/g, '""')}"`,
    `"${(e.platformCategory || '').replace(/"/g, '""')}"`,
    `"${(e.postedAt || '').replace(/"/g, '""')}"`,
    `"${(e.postUrl || '').replace(/"/g, '""')}"`,
    `"${(e.notes || '').replace(/"/g, '""')}"`
  ]);

  const csvContent = '\uFEFF' + [header.join(','), ...rows.map(r => r.join(','))].join('\n');

  if (typeof document !== 'undefined') {
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    const now = new Date().toISOString().slice(0, 10);
    a.download = `Bao_Cao_Thong_Ke_Content_BDS_${now}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast('📥 Đã tải file CSV / Excel báo cáo thống kê!', '💾');
  }

  return csvContent;
}

