let activeLibraryBookId = 1;
let activeFlipbookPage = 1;

function selectLibraryBook(bookId) {
  const book = LIBRARY_BOOKS_DATA[bookId];
  if (!book) return;
  activeLibraryBookId = bookId;
  activeFlipbookPage = book.defaultPage || 1;

  // 1. Update 3 Top Cards
  for (let id = 1; id <= 3; id++) {
    const card = document.getElementById('bookCard' + id);
    const badge = document.getElementById('bookBadge' + id);
    if (card) {
      if (id === bookId) {
        card.className = `library-book-card book-${id} active`;
        if (badge) badge.innerHTML = '💻 Đang xem';
      } else {
        card.className = `library-book-card book-${id}`;
        if (badge) badge.innerHTML = '👆 Bấm để xem';
      }
    }
  }

  // 2. Render Sub-banner
  const bannerWrap = document.getElementById('libraryBannerWrap');
  if (bannerWrap) {
    bannerWrap.innerHTML = `
      <div class="library-book-banner" style="border-left: 4px solid ${book.themeColor};">
        <div class="book-banner-left">
          <div class="book-banner-title" style="color: ${book.themeColor};">${book.bannerTitle}</div>
          <div class="book-banner-quote">${book.bannerQuote}</div>
        </div>
        <div class="book-banner-right">
          <button type="button" class="btn-banner-fullscreen ${book.btnClass}" onclick="openFlipbookFullscreen()" title="Mở đọc toàn màn hình">
            <span>📷</span> Toàn màn hình
          </button>
        </div>
      </div>
    `;
  }

  // 3. Render Controls (Pills for Book 1 / 5 Psych Cards for Book 2 / 4 Action Cards for Book 3)
  const controlsWrap = document.getElementById('libraryDynamicControlsWrap');
  if (controlsWrap) {
    if (bookId === 1) {
      // 10 Modules Pills
      controlsWrap.innerHTML = `
        <div class="book1-modules-wrap">
          ${book.modules.map((m, idx) => `
            <button type="button" class="module-pill-btn ${idx === 0 ? 'active' : ''}" onclick="jumpToFlipbookPage(${m.page}, this)">
              ${m.name}
            </button>
          `).join('')}
        </div>
      `;
    } else if (bookId === 2) {
      // 5 Buyer Psychology Cards
      controlsWrap.innerHTML = `
        <div class="book2-cards-grid">
          ${book.cards.map((c, idx) => `
            <div class="book2-card-item ${c.cardClass} ${idx === 0 ? 'active' : ''}" onclick="jumpToFlipbookPage(${c.page}, this)">
              <div class="book2-card-icon">${c.icon}</div>
              <div class="book2-card-title">${c.name}</div>
              <div class="book2-card-sub">${c.sub}</div>
            </div>
          `).join('')}
        </div>
      `;
    } else if (bookId === 3) {
      // 4 Action Cards
      controlsWrap.innerHTML = `
        <div class="book3-cards-grid">
          ${book.cards.map((c, idx) => `
            <div class="book3-card-item ${c.cardClass} ${idx === 0 ? 'active' : ''}" onclick="jumpToFlipbookPage(${c.page}, this)">
              <div class="book3-card-icon">${c.icon}</div>
              <div class="book3-card-title">${c.name}</div>
              <div class="book3-card-sub">${c.sub}</div>
            </div>
          `).join('')}
        </div>
      `;
    }
  }

  // 4. Update Reader Header
  const readerTitle = document.getElementById('flipbookReaderTitle');
  if (readerTitle) {
    readerTitle.innerHTML = `
      <span class="reader-icon">${book.icon}</span>
      <span class="reader-book-name">${book.title}</span>
      <span class="reader-author">· ${book.author}</span>
    `;
  }

  // 5. Update Iframe Src
  const iframe = document.getElementById('libraryFlipbookIframe');
  if (iframe) {
    iframe.src = book.baseUrl + '#page/' + activeFlipbookPage;
  }

  if (typeof showToast === 'function') {
    showToast(`📚 Đang mở: ${book.title}`, '📖');
  }
}

function jumpToFlipbookPage(pageNumber, btnElement) {
  activeFlipbookPage = pageNumber;
  const book = LIBRARY_BOOKS_DATA[activeLibraryBookId] || LIBRARY_BOOKS_DATA[1];
  const iframe = document.getElementById('libraryFlipbookIframe');
  if (iframe) {
    iframe.src = book.baseUrl + '#page/' + pageNumber;
  }

  // Update active pill or card
  const container = document.getElementById('libraryDynamicControlsWrap');
  if (container) {
    const activeItems = container.querySelectorAll('.active');
    activeItems.forEach(el => el.classList.remove('active'));
  }
  if (btnElement) {
    btnElement.classList.add('active');
  }

  if (typeof showToast === 'function') {
    showToast(`📖 Đang mở: ${book.title} — Trang ${pageNumber}`, '📖');
  }
}

function openFlipbookFullscreen() {
  const book = LIBRARY_BOOKS_DATA[activeLibraryBookId] || LIBRARY_BOOKS_DATA[1];
  const url = book.baseUrl + (activeFlipbookPage ? '#page/' + activeFlipbookPage : '#page/1');
  if (typeof window !== 'undefined') {
    window.open(url, '_blank');
  }
}

function toggleFlipbookContainerFullscreen() {
  const container = document.getElementById('flipbookReaderContainer');
  if (!container || typeof document === 'undefined') return;
  if (!document.fullscreenElement) {
    if (container.requestFullscreen) {
      container.requestFullscreen().catch(err => {
        console.error('Fullscreen request failed:', err);
      });
    }
  } else {
    if (document.exitFullscreen) {
      document.exitFullscreen().catch(err => {
        console.error('Exit fullscreen failed:', err);
      });
    }
  }
}

function openFlipbookExternal() {
  openFlipbookFullscreen();
}

function initLibraryModule() {
  selectLibraryBook(activeLibraryBookId || 1);
  initReflexTraining();
  initMatrix6Module();
  initZaloScriptsModule();
}

