function generatePreFlightBriefing() {
  const psychEl = document.getElementById('briefingPsychType');
  const houseEl = document.getElementById('briefingHouseType');
  const outputWrap = document.getElementById('briefingOutputWrap');
  if (!psychEl || !houseEl || !outputWrap) return;

  const psych = psychEl.value || 'tham';
  const house = houseEl.value || 'hem_thoang';

  const briefings = {
    tham: {
      route: 'Dẫn khách đi qua trục đường chính sầm uất, chỉ cho khách thấy các căn mặt tiền đang cho thuê 30-50tr/tháng để neo giá trị cao, sau đó rẽ vào hẻm căn nhà mình bán để khách thấy mức giá rẻ bất ngờ.',
      icebreaker: '“Chào anh! Anh đi đường tới đây thấy thuận tiện không? Khu này đang tăng giá ầm ầm mà căn mình sắp xem chủ hạ sâu đến mức em phải giật mình!”',
      standingPoint: 'Đứng ngay giữa phòng khách hoặc tầng lửng, chỗ có tầm nhìn bao quát toàn bộ diện tích sàn để khách cảm nhận trọn vẹn số mét vuông họ nhận được trên từng đồng tiền.',
      closingQuestion: '“Căn này tính ra đơn giá m2 rẻ hơn căn đầu hẻm 15 triệu/m². Nếu chủ bớt thêm tí lộc nữa, anh có muốn đặt cọc giữ chỗ ngay kẻo lái buôn họ gom mất không anh?”'
    },
    san: {
      route: 'Dẫn khách đi tuyến đường thẳng tắp, sạch sẽ, né bãi rác hoặc đoạn hẹp để không làm khách phật ý hoặc mất kiên nhẫn.',
      icebreaker: '“Chào anh! Nhìn phong thái của anh là em biết anh là người cực kỳ quyết đoán và bận rộn, em chỉ xin đúng 10 phút tập trung vào các điểm đắt giá nhất của căn nhà!”',
      standingPoint: 'Đứng tại ban công lầu 2 phóng tầm mắt ra xa, tạo cảm giác chủ nhân làm chủ không gian và cao hơn hàng xóm.',
      closingQuestion: '“Căn này hiếm nhất khu vì nở hậu và đường xe hơi tránh. Chiều nay có người khác hẹn xem vòng 2, anh là người xem trước, anh có muốn khóa căn này lại trước họ không?”'
    },
    si: {
      route: 'Dẫn đi qua trường mầm non, trường cấp 1 và công viên nội khu, chỉ rõ con đường an toàn con cái có thể tự đi bộ tới trường.',
      icebreaker: '“Dạ em chào anh chị! Hôm nay cả hai vợ chồng cùng đi xem là quá tuyệt vời. Căn này gian bếp và sân trước thoáng mát lắm, chị nhà xem chắc chắn sẽ ưng ngay!”',
      standingPoint: 'Đứng tại gian bếp hướng mắt ra phòng khách và giếng trời: Cho khách hình dung cảnh cả nhà quây quần nấu nướng mỗi bữa tối.',
      closingQuestion: '“Anh chị thấy các cháu nhỏ ở đây vừa đi học gần, vừa có sân chơi an toàn không tiếng xe máy. Anh chị có muốn gia đình mình dọn về đây an cư trước năm học mới không ạ?”'
    },
    nghi: {
      route: 'Dẫn đi đường chuẩn bản đồ quy hoạch, ghé ngang trụ sở công an phường hoặc UBND phường để tạo cảm giác an tâm về trật tự an ninh.',
      icebreaker: '“Em chào anh! Em chuẩn bị sẵn tập hồ sơ pháp lý, trích lục bản vẽ 1/2000 và sổ hồng hoàn công công chứng đây rồi, anh em mình vừa xem nhà vừa đối chiếu số liệu luôn nhé!”',
      standingPoint: 'Đứng sát cột chịu lực hoặc góc giếng trời: Chỉ rõ tường 20 kiên cố, không bị ẩm mốc, ranh mốc chuẩn khớp từng centimet với sổ đỏ.',
      closingQuestion: '“Pháp lý sạch 100%, không dính quy hoạch, ranh mốc rõ ràng. Anh thấy có điểm nào về giấy tờ cần em hỗ trợ kiểm tra thêm trên quận không, nếu không mình chốt ngày sang cọc nhé?”'
    },
    man: {
      route: 'Dẫn đi qua khu biệt thự hoặc trục phố đẹp nhất, chỉ các nhà hàng xóm là cán bộ cấp cao, bác sĩ, giảng viên để tôn vinh vị thế khu dân cư.',
      icebreaker: '“Em chào anh! Hôm nay rất vinh hạnh được tiếp đón một người có gu thẩm mỹ cao như anh. Căn nhà này gia chủ cũng là người rất kỹ tính, chỉ muốn bàn giao cho người đẳng cấp như anh thôi ạ!”',
      standingPoint: 'Đứng tại phòng khách hoặc sân thượng ngắm view trung tâm: Tôn vinh không gian tiếp khách sang trọng và đẳng cấp của chủ nhân.',
      closingQuestion: '“Vị trí này chỉ cần đọc tên hẻm là bạn bè đối tác ai cũng nể phục gu của anh. Anh thấy căn này đã đủ xứng tầm với vị thế của anh chưa ạ?”'
    }
  };

  const b = briefings[psych] || briefings.tham;

  outputWrap.style.display = 'flex';
  outputWrap.innerHTML = `
    <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid rgba(16, 185, 129, 0.2); padding-bottom: 0.6rem;">
      <div style="font-weight: 800; color: #34d399; font-size: 1rem;">
        🛫 BẢN ĐỒ TÁC CHIẾN BỎ TÚI (3 PHÚT TRƯỚC GIỜ GẶP KHÁCH)
      </div>
      <button type="button" class="btn-copy-zalo" onclick="copyPreFlightBriefing()">
        <span>📋</span> Copy Bản Đồ Này
      </button>
    </div>

    <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 0.85rem; font-size: 0.84rem;">
      <div style="background: rgba(0,0,0,0.25); padding: 0.85rem; border-radius: 6px; border-left: 3px solid #38bdf8;">
        <strong style="color: #38bdf8;">🛣️ TUYẾN ĐƯỜNG NÊN DẮT:</strong>
        <div style="color: #cbd5e1; margin-top: 0.3rem; line-height: 1.45;">${b.route}</div>
      </div>
      <div style="background: rgba(0,0,0,0.25); padding: 0.85rem; border-radius: 6px; border-left: 3px solid #f59e0b;">
        <strong style="color: #fbbf24;">☕ CÂU MỞ ĐẦU PHÁ BĂNG:</strong>
        <div style="color: #fff; font-style: italic; margin-top: 0.3rem; line-height: 1.45;">${b.icebreaker}</div>
      </div>
      <div style="background: rgba(0,0,0,0.25); padding: 0.85rem; border-radius: 6px; border-left: 3px solid #a78bfa;">
        <strong style="color: #c084fc;">📍 ĐIỂM ĐỨNG VÀNG TRONG NHÀ:</strong>
        <div style="color: #cbd5e1; margin-top: 0.3rem; line-height: 1.45;">${b.standingPoint}</div>
      </div>
      <div style="background: rgba(0,0,0,0.25); padding: 0.85rem; border-radius: 6px; border-left: 3px solid #22c55e;">
        <strong style="color: #86efac;">🔒 ĐÒN KHÓA TRƯỚC KHI VỀ:</strong>
        <div style="color: #fff; font-style: italic; margin-top: 0.3rem; line-height: 1.45;">${b.closingQuestion}</div>
      </div>
    </div>
  `;

  if (typeof showToast === 'function') {
    showToast('🚀 Đã sinh Bản Đồ Tác Chiến 3 Phút!', '🛫');
  }
}

function copyPreFlightBriefing() {
  const outputWrap = document.getElementById('briefingOutputWrap');
  if (!outputWrap) return;
  const text = outputWrap.innerText || outputWrap.textContent;
  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') showToast('📋 Đã copy Bản Đồ Tác Chiến bỏ túi!', '✅');
    });
  }
}

// ------------------------------------------
// 5. KHO 30 KỊCH BẢN ZALO "HÂM NÓNG KHÁCH IM LẶNG"
// ------------------------------------------
function initZaloScriptsModule() {
  renderZaloScripts(activeZaloCategory || 'ALL');
}

function filterZaloScripts(category) {
  activeZaloCategory = category || 'ALL';

  const filterBtns = document.querySelectorAll('.zalo-filter-btn');
  filterBtns.forEach(btn => {
    if (btn.getAttribute('onclick') && btn.getAttribute('onclick').includes("'" + activeZaloCategory + "'")) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });

  renderZaloScripts(activeZaloCategory);
}

function renderZaloScripts(category) {
  const container = document.getElementById('zaloScriptsGrid');
  if (!container) return;

  let list = ZALO_NURTURE_SCRIPTS;
  if (category && category !== 'ALL') {
    list = list.filter(item => item.category === category);
  }

  container.innerHTML = list.map(item => `
    <div class="zalo-script-card">
      <div class="zalo-card-top">
        <div class="zalo-card-title">${item.title}</div>
        <span class="zalo-card-cat">${item.catTitle}</span>
      </div>
      <div class="zalo-card-text" id="zalo_text_${item.id}">${item.content}</div>
      <div style="display: flex; justify-content: flex-end;">
        <button type="button" class="btn-copy-zalo" onclick="copyZaloScript('${item.id}')">
          <span>📋</span> Copy Zalo
        </button>
      </div>
    </div>
  `).join('');
}

function copyZaloScript(scriptId) {
  const scriptItem = ZALO_NURTURE_SCRIPTS.find(s => s.id === scriptId);
  if (!scriptItem) return;

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(scriptItem.content).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã copy tin nhắn Zalo!', '💬');
      }
    });
  }
}


