  const alleyLabel = s.step7AlleyType === 'through' ? 'Hẻm thông bàn cờ' : 'Hẻm cụt an ninh';
  const alleyWidthLabel = s.step7AlleyWidth === 'car_pass' ? 'Xe hơi tránh (>5m)' : (s.step7AlleyWidth === 'car_door' ? 'Xe hơi tới cửa (4m)' : (s.step7AlleyWidth === 'bagac' ? 'Xe ba gác (3m)' : 'Xe máy (<2.5m)'));

  const drainageLabel = s.step8Drainage === 'never' ? 'Cao ráo, không bao giờ ngập' : (s.step8Drainage === 'good' ? 'Cống thoát nhanh' : (s.step8Drainage === 'heavy_rain' ? 'Ngập nhẹ khi mưa lớn' : (s.step8Drainage === 'tide' ? 'Ngập triều cường' : 'Có hố ga trước nhà')));

  const electricLabel = s.step3Electric === 'clear' ? 'Mặt tiền thoáng, không vướng cột' : (s.step3Electric === 'pole_side' ? 'Cột điện lệch mép' : (s.step3Electric === 'pole_front' ? 'Cột điện trước nhà' : (s.step3Electric === 'transformer' ? 'Gần trạm biến áp' : 'Dây điện chằng chịt')));

  const neighborsLabel = s.step6Neighbors === 'civilized' ? 'Dân trí cao, an ninh' : (s.step6Neighbors === 'friendly' ? 'Hàng xóm thân thiện' : (s.step6Neighbors === 'business' ? 'Khu kinh doanh buôn bán' : (s.step6Neighbors === 'rental' ? 'Nhiều phòng trọ' : 'Khu vực phức tạp')));

