function fillSampleKhaosat() {
  const sample = DEFAULT_SAMPLE_KHAOSAT;

  const titleInput = document.getElementById('khaosatInputTitle');
  if (titleInput) titleInput.value = sample.title;

  // Call checklist
  const chkAvail = document.getElementById('chkCallAvailable');
  const chkAddr = document.getElementById('chkCallAddress');
  const chkPrice = document.getElementById('chkCallPrice');
  const chkBank = document.getElementById('chkCallBank');
  const chkDocs = document.getElementById('chkCallDocs');

  if (chkAvail) chkAvail.checked = sample.callChecklist.available;
  if (chkAddr) chkAddr.checked = sample.callChecklist.address;
  if (chkPrice) chkPrice.checked = sample.callChecklist.price;
  if (chkBank) chkBank.checked = sample.callChecklist.bank;
  if (chkDocs) chkDocs.checked = sample.callChecklist.docs;

  // 9 Steps
  const s = sample.nineSteps;
  const addr = document.getElementById('ksStep1Address');
  const ver = document.getElementById('ksStep1Verified');
  if (addr) addr.value = s.step1Address;
  if (ver) ver.checked = s.step1Verified;

  const land = document.getElementById('ksStep2LandType');
  const landNote = document.getElementById('ksStep2Note');
  if (land) land.value = s.step2LandType;
  if (landNote) landNote.value = s.step2Note;

  const elec = document.getElementById('ksStep3Electric');
  const elecNote = document.getElementById('ksStep3Note');
  if (elec) elec.value = s.step3Electric;
  if (elecNote) elecNote.value = s.step3Note;

  const dir = document.getElementById('ksStep4Direction');
  const dirNote = document.getElementById('ksStep4Note');
  if (dir) dir.value = s.step4Direction;
  if (dirNote) dirNote.value = s.step4Note;
  updateKhaosatDirectionBadge();

  const envClean = document.getElementById('ksEnvClean');
  const envGrave = document.getElementById('ksEnvGraveyard');
  const envFun = document.getElementById('ksEnvFuneral');
  const envGarb = document.getElementById('ksEnvGarbage');
  const envPoll = document.getElementById('ksEnvPollution');
  const envNote = document.getElementById('ksStep5Note');
  if (envClean) envClean.checked = s.step5Env.clean;
  if (envGrave) envGrave.checked = s.step5Env.graveyard;
  if (envFun) envFun.checked = s.step5Env.funeral;
  if (envGarb) envGarb.checked = s.step5Env.garbage;
  if (envPoll) envPoll.checked = s.step5Env.pollution;
  if (envNote) envNote.value = s.step5Note;

  const neigh = document.getElementById('ksStep6Neighbors');
  const neighNote = document.getElementById('ksStep6Note');
  if (neigh) neigh.value = s.step6Neighbors;
  if (neighNote) neighNote.value = s.step6Note;

  const alType = document.getElementById('ksStep7AlleyType');
  const alWidth = document.getElementById('ksStep7AlleyWidth');
  const alNote = document.getElementById('ksStep7Note');
  if (alType) alType.value = s.step7AlleyType;
  if (alWidth) alWidth.value = s.step7AlleyWidth;
  if (alNote) alNote.value = s.step7Note;

  const drain = document.getElementById('ksStep8Drainage');
  const drainNote = document.getElementById('ksStep8Note');
  if (drain) drain.value = s.step8Drainage;
  if (drainNote) drainNote.value = s.step8Note;

  const spir = document.getElementById('ksStep9Spiritual');
  const spirNote = document.getElementById('ksStep9Note');
  if (spir) spir.value = s.step9Spiritual;
  if (spirNote) spirNote.value = s.step9Note;

  // 5 Pros & 5 Cons
  sample.pros.forEach((pro, idx) => {
    const el = document.getElementById(`ksPro${idx + 1}`);
    if (el) el.value = pro;
  });
  sample.cons.forEach((con, idx) => {
    const el = document.getElementById(`ksCon${idx + 1}`);
    if (el) el.value = con;
  });

  updateKhaosatProgress();
  onKhaosatCallCheckboxChange();
  renderKhaosatLivePreview();
  if (typeof showToast === 'function') {
    showToast('✨ Đã nạp mẫu khảo sát thực chiến chuẩn 9 bước (Nguyễn Kiệm, Gò Vấp)!', '🌹');
  }
}

function resetKhaosatForm() {
  const titleInput = document.getElementById('khaosatInputTitle');
  if (titleInput) titleInput.value = '';

  ['chkCallAvailable', 'chkCallAddress', 'chkCallPrice', 'chkCallBank', 'chkCallDocs'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.checked = false;
  });

  const idsToClear = [
    'ksStep1Address', 'ksStep2Note', 'ksStep3Note', 'ksStep4Note', 'ksStep5Note',
    'ksStep6Note', 'ksStep7Note', 'ksStep8Note', 'ksStep9Note',
    'ksPro1', 'ksPro2', 'ksPro3', 'ksPro4', 'ksPro5',
    'ksCon1', 'ksCon2', 'ksCon3', 'ksCon4', 'ksCon5'
  ];
  idsToClear.forEach(id => {
    const el = document.getElementById(id);
    if (el) el.value = '';
  });

  const envClean = document.getElementById('ksEnvClean');
  if (envClean) envClean.checked = true;
  ['ksEnvGraveyard', 'ksEnvFuneral', 'ksEnvGarbage', 'ksEnvPollution'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.checked = false;
  });

  updateKhaosatDirectionBadge();

  updateKhaosatProgress();
  onKhaosatCallCheckboxChange();
  renderKhaosatLivePreview();
  if (typeof showToast === 'function') {
    showToast('🗑️ Đã làm mới toàn bộ phiếu khảo sát!', '🔄');
  }
}

function addKhaosatProChip(chipText) {
  setTimeout(() => renderKhaosatLivePreview(), 50);
  for (let i = 1; i <= 5; i++) {
    const el = document.getElementById(`ksPro${i}`);
    if (el && !el.value.trim()) {
      el.value = chipText;
      if (typeof showToast === 'function') {
        showToast(`✅ Đã thêm Ưu điểm ${i}: "${chipText}"`, '🌟');
      }
      return;
    }
  }
  const el5 = document.getElementById('ksPro5');
  if (el5) {
    el5.value = chipText;
    if (typeof showToast === 'function') {
      showToast(`✅ Đã cập nhật Ưu điểm 5: "${chipText}"`, '🌟');
    }
  }
}

function addKhaosatConChip(chipText) {
  setTimeout(() => renderKhaosatLivePreview(), 50);
  for (let i = 1; i <= 5; i++) {
    const el = document.getElementById(`ksCon${i}`);
    if (el && !el.value.trim()) {
      el.value = chipText;
      if (typeof showToast === 'function') {
        showToast(`⚠️ Đã thêm Nhược điểm ${i}: "${chipText}"`, '⚠️');
      }
      return;
    }
  }
  const el5 = document.getElementById('ksCon5');
  if (el5) {
    el5.value = chipText;
    if (typeof showToast === 'function') {
      showToast(`⚠️ Đã cập nhật Nhược điểm 5: "${chipText}"`, '⚠️');
    }
  }
}

function collectKhaosatFormData() {
  const title = (document.getElementById('khaosatInputTitle')?.value || '').trim() ||
                (document.getElementById('ksStep1Address')?.value || '').trim() ||
                'Phiếu Khảo Sát BĐS ' + new Date().toLocaleDateString('vi-VN');

  const pros = [1, 2, 3, 4, 5].map(i => (document.getElementById(`ksPro${i}`)?.value || '').trim()).filter(Boolean);
  const cons = [1, 2, 3, 4, 5].map(i => (document.getElementById(`ksCon${i}`)?.value || '').trim()).filter(Boolean);

  return {
    id: 'ks_' + Date.now(),
    title: title,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    callChecklist: {
      available: !!document.getElementById('chkCallAvailable')?.checked,
      address: !!document.getElementById('chkCallAddress')?.checked,
      price: !!document.getElementById('chkCallPrice')?.checked,
      bank: !!document.getElementById('chkCallBank')?.checked,
      docs: !!document.getElementById('chkCallDocs')?.checked
    },
    nineSteps: {
      step1Address: document.getElementById('ksStep1Address')?.value.trim() || '',
      step1Verified: !!document.getElementById('ksStep1Verified')?.checked,
      step2LandType: document.getElementById('ksStep2LandType')?.value || 'ODT',
      step2Note: document.getElementById('ksStep2Note')?.value.trim() || '',
      step3Electric: document.getElementById('ksStep3Electric')?.value || 'clear',
      step3Note: document.getElementById('ksStep3Note')?.value.trim() || '',
      step4Direction: document.getElementById('ksStep4Direction')?.value || 'Đông Nam',
      step4Note: document.getElementById('ksStep4Note')?.value.trim() || '',
      step5Env: {
        clean: !!document.getElementById('ksEnvClean')?.checked,
        graveyard: !!document.getElementById('ksEnvGraveyard')?.checked,
        funeral: !!document.getElementById('ksEnvFuneral')?.checked,
        garbage: !!document.getElementById('ksEnvGarbage')?.checked,
        pollution: !!document.getElementById('ksEnvPollution')?.checked
      },
      step5Note: document.getElementById('ksStep5Note')?.value.trim() || '',
      step6Neighbors: document.getElementById('ksStep6Neighbors')?.value || 'civilized',
      step6Note: document.getElementById('ksStep6Note')?.value.trim() || '',
      step7AlleyType: document.getElementById('ksStep7AlleyType')?.value || 'through',
      step7AlleyWidth: document.getElementById('ksStep7AlleyWidth')?.value || 'car_pass',
      step7Note: document.getElementById('ksStep7Note')?.value.trim() || '',
      step8Drainage: document.getElementById('ksStep8Drainage')?.value || 'never',
      step8Note: document.getElementById('ksStep8Note')?.value.trim() || '',
      step9Spiritual: document.getElementById('ksStep9Spiritual')?.value || 'none',
      step9Note: document.getElementById('ksStep9Note')?.value.trim() || ''
    },
    pros: pros,
    cons: cons
  };
}

function saveCurrentKhaosatReport() {
  const data = collectKhaosatFormData();
  const reports = getKhaosatReports();
  reports[data.id] = data;
  saveKhaosatReports(reports);

  updateKhaosatProgress();
  if (typeof showToast === 'function') {
    showToast(`💾 Đã lưu phiếu khảo sát: "${data.title}" vào kho!`, '✅');
  }
}

function renderKhaosatSavedList() {
  const listEl = document.getElementById('khaosatSavedList');
  const countEl = document.getElementById('khaosatSavedCount');
  if (!listEl) return;

  const reports = getKhaosatReports();
  const keys = Object.keys(reports);
  if (countEl) countEl.textContent = keys.length;

  if (keys.length === 0) {
    listEl.innerHTML = `
      <div style="text-align: center; padding: 1.5rem; color: #64748b; font-size: 0.85rem;">
        Chưa có phiếu khảo sát nào được lưu. Bấm <strong>"✨ Nạp Mẫu Khảo Sát"</strong> hoặc điền form và bấm <strong>"💾 Lưu Phiếu Khảo Sát"</strong>.
      </div>
    `;
    return;
  }

  const sortedReports = keys.map(k => reports[k]).sort((a, b) => new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt));

  let html = '';
  sortedReports.forEach(r => {
    const dateStr = new Date(r.updatedAt || r.createdAt).toLocaleString('vi-VN');
    const proCount = r.pros?.length || 0;
    const conCount = r.cons?.length || 0;

    html += `
      <div style="background: rgba(0, 0, 0, 0.3); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: var(--radius-sm); padding: 0.85rem; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 0.65rem;">
        <div style="flex: 1; min-width: 260px;">
          <div style="font-size: 0.88rem; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 0.4rem;">
            <span>🏡</span>
            <span>${r.title || 'Căn nhà'}</span>
          </div>
          <div style="font-size: 0.76rem; color: #94a3b8; margin-top: 0.2rem; display: flex; gap: 0.6rem; flex-wrap: wrap;">
            <span>📍 ${r.nineSteps?.step1Address || 'Chưa ghi địa chỉ'}</span>
            <span>🧭 Hướng: ${r.nineSteps?.step4Direction || 'Chưa chọn'}</span>
            <span style="color: #34d399;">🌟 ${proCount} Ưu điểm</span>
            <span style="color: #fda4af;">⚠️ ${conCount} Nhược điểm</span>
            <span>🕒 ${dateStr}</span>
          </div>
        </div>

        <div style="display: flex; gap: 0.45rem; align-items: center;">
          <button type="button" class="btn-spin-pill-load" onclick="loadKhaosatReport('${r.id}')" title="Mở phiếu này lên form để xem & sửa">
            📂 Mở Phiếu
          </button>
          <button type="button" class="btn-copy-sm" onclick="copySpecificKhaosatReport('${r.id}')" title="Sao chép báo cáo căn này">
            📋 Copy
          </button>
          <button type="button" class="btn-close-sm" onclick="deleteKhaosatReport('${r.id}')" title="Xóa phiếu khảo sát này" style="color: #ef4444; font-size: 1.1rem; padding: 0.2rem 0.5rem;">
            &times;
          </button>
        </div>
      </div>
    `;
  });

  listEl.innerHTML = html;
}

function loadKhaosatReport(reportId) {
  const reports = getKhaosatReports();
  const r = reports[reportId];
  if (!r) return;

  const titleInput = document.getElementById('khaosatInputTitle');
  if (titleInput) titleInput.value = r.title || '';

  // Call checks
  const chkAvail = document.getElementById('chkCallAvailable');
  const chkAddr = document.getElementById('chkCallAddress');
  const chkPrice = document.getElementById('chkCallPrice');
  const chkBank = document.getElementById('chkCallBank');
  const chkDocs = document.getElementById('chkCallDocs');

  if (chkAvail) chkAvail.checked = !!r.callChecklist?.available;
  if (chkAddr) chkAddr.checked = !!r.callChecklist?.address;
  if (chkPrice) chkPrice.checked = !!r.callChecklist?.price;
  if (chkBank) chkBank.checked = !!r.callChecklist?.bank;
  if (chkDocs) chkDocs.checked = !!r.callChecklist?.docs;

  // 9 Steps
  const s = r.nineSteps || {};
  const addr = document.getElementById('ksStep1Address');
  const ver = document.getElementById('ksStep1Verified');
  if (addr) addr.value = s.step1Address || '';
  if (ver) ver.checked = s.step1Verified !== false;

  const land = document.getElementById('ksStep2LandType');
  const landNote = document.getElementById('ksStep2Note');
  if (land) land.value = s.step2LandType || 'ODT';
  if (landNote) landNote.value = s.step2Note || '';

  const elec = document.getElementById('ksStep3Electric');
  const elecNote = document.getElementById('ksStep3Note');
  if (elec) elec.value = s.step3Electric || 'clear';
  if (elecNote) elecNote.value = s.step3Note || '';

  const dir = document.getElementById('ksStep4Direction');
  const dirNote = document.getElementById('ksStep4Note');
  if (dir) dir.value = s.step4Direction || 'Đông Nam';
  if (dirNote) dirNote.value = s.step4Note || '';
  updateKhaosatDirectionBadge();

  const env = s.step5Env || {};
  const envClean = document.getElementById('ksEnvClean');
  const envGrave = document.getElementById('ksEnvGraveyard');
  const envFun = document.getElementById('ksEnvFuneral');
  const envGarb = document.getElementById('ksEnvGarbage');
  const envPoll = document.getElementById('ksEnvPollution');
  const envNote = document.getElementById('ksStep5Note');
  if (envClean) envClean.checked = !!env.clean;
  if (envGrave) envGrave.checked = !!env.graveyard;
  if (envFun) envFun.checked = !!env.funeral;
  if (envGarb) envGarb.checked = !!env.garbage;
  if (envPoll) envPoll.checked = !!env.pollution;
  if (envNote) envNote.value = s.step5Note || '';

  const neigh = document.getElementById('ksStep6Neighbors');
  const neighNote = document.getElementById('ksStep6Note');
  if (neigh) neigh.value = s.step6Neighbors || 'civilized';
  if (neighNote) neighNote.value = s.step6Note || '';

  const alType = document.getElementById('ksStep7AlleyType');
  const alWidth = document.getElementById('ksStep7AlleyWidth');
  const alNote = document.getElementById('ksStep7Note');
  if (alType) alType.value = s.step7AlleyType || 'through';
  if (alWidth) alWidth.value = s.step7AlleyWidth || 'car_pass';
  if (alNote) alNote.value = s.step7Note || '';

  const drain = document.getElementById('ksStep8Drainage');
  const drainNote = document.getElementById('ksStep8Note');
  if (drain) drain.value = s.step8Drainage || 'never';
  if (drainNote) drainNote.value = s.step8Note || '';

  const spir = document.getElementById('ksStep9Spiritual');
  const spirNote = document.getElementById('ksStep9Note');
  if (spir) spir.value = s.step9Spiritual || 'none';
  if (spirNote) spirNote.value = s.step9Note || '';

  // 5 Pros & 5 Cons
  [1, 2, 3, 4, 5].forEach(i => {
    const proEl = document.getElementById(`ksPro${i}`);
    if (proEl) proEl.value = r.pros && r.pros[i - 1] ? r.pros[i - 1] : '';
    const conEl = document.getElementById(`ksCon${i}`);
    if (conEl) conEl.value = r.cons && r.cons[i - 1] ? r.cons[i - 1] : '';
  });

  const el = document.getElementById('subsystemKhaosatWorkspace');
  if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });

  updateKhaosatProgress();
  onKhaosatCallCheckboxChange();
  renderKhaosatLivePreview();
  if (typeof showToast === 'function') {
    showToast(`📂 Đã mở phiếu khảo sát: ${r.title}!`, '✅');
  }
}

function deleteKhaosatReport(reportId) {
  if (typeof confirm === 'function' && !confirm('Bạn có chắc muốn xóa phiếu khảo sát này không?')) {
    return;
  }
  const reports = getKhaosatReports();
  delete reports[reportId];
  saveKhaosatReports(reports);

  updateKhaosatProgress();
  if (typeof showToast === 'function') {
    showToast('🗑️ Đã xóa phiếu khảo sát thành công!', '✅');
  }
}

function copyKhaosatCallScript(type) {
  const id = type === 'sold' ? 'scriptKhaosatSold' : 'scriptKhaosatAvailable';
  const el = document.getElementById(id);
  const text = el ? el.textContent : '';
  if (!text) return;

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép kịch bản gọi Đầu Chủ vào Clipboard!', '📞');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function generateKhaosatReportText(data) {
  const dateStr = new Date(data.updatedAt || data.createdAt || Date.now()).toLocaleString('vi-VN');
  const s = data.nineSteps || {};

  let text = `=========================================\n`;
  text += `🌹 BÁO CÁO KHẢO SÁT BẤT ĐỘNG SẢN HIỆN TRƯỜNG\n`;
  text += `Tiêu đề: ${data.title || 'BĐS Khảo Sát'}\n`;
  text += `Thời gian thực hiện: ${dateStr}\n`;
  text += `Môi giới phụ trách: ${typeof getUserProfile === 'function' ? getUserProfile().fullName || 'Chuyên viên BĐS' : 'Chuyên viên BĐS'}\n`;
  text += `=========================================\n\n`;

  text += `📞 I. THÔNG TIN XÁC NHẬN ĐẦU CHỦ:\n`;
  text += `• Tình trạng: ${data.callChecklist?.available ? 'Đang chào bán' : 'Cần kiểm tra lại'}\n`;
  text += `• Địa chỉ & Map: ${data.callChecklist?.address ? 'Đã xin chính xác' : 'Chưa có map'}\n`;
  text += `• Pháp lý / Vay bank: ${data.callChecklist?.bank ? 'Đã nắm tình trạng vay & cách rút sổ' : 'Chưa hỏi vay bank'}\n\n`;

  text += `📌 II. 9 YẾU TỐ KHẢO SÁT HIỆN TRƯỜNG:\n`;
  text += `1️⃣ Địa chỉ: ${s.step1Address || 'Chưa ghi'} (${s.step1Verified ? 'Đã đối chiếu số nhà/hẻm' : 'Chưa đối chiếu'})\n`;
  text += `2️⃣ Loại đất: ${s.step2LandType || 'ODT'} - ${s.step2Note || 'Không có ghi chú'}\n`;
  text += `3️⃣ Hệ thống điện: ${s.step3Electric || 'clear'} - ${s.step3Note || 'Bình thường'}\n`;
  text += `4️⃣ Hướng nhà: ${s.step4Direction || 'Đông Nam'} - ${s.step4Note || 'Đón gió mát'}\n`;
  text += `5️⃣ Môi trường xung quanh: ${s.step5Note || 'Bán kính 100m thoáng sạch'}\n`;
  text += `6️⃣ Hàng xóm & Dân trí: ${s.step6Neighbors || 'civilized'} - ${s.step6Note || 'Dân trí tốt'}\n`;
  text += `7️⃣ Hẻm & Giao thông: ${s.step7AlleyType === 'through' ? 'Hẻm thông' : 'Hẻm cụt'} (${s.step7AlleyWidth || 'ô tô'}) - ${s.step7Note || ''}\n`;
  text += `8️⃣ Thoát nước & Ngập: ${s.step8Drainage || 'never'} - ${s.step8Note || 'Cao ráo'}\n`;
  text += `9️⃣ Yếu tố tâm linh: ${s.step9Spiritual || 'none'} - ${s.step9Note || 'Không vướng'}\n\n`;

  text += `🌟 III. 5 ƯU ĐIỂM VÀNG (LÝ DO KHÁCH XUỐNG CỌC):\n`;
  if (data.pros && data.pros.length > 0) {
    data.pros.forEach((pro, idx) => {
      text += `  ${idx + 1}. ${pro}\n`;
    });
  } else {
    text += `  (Chưa nhập ưu điểm)\n`;
  }
  text += `\n`;

  text += `⚠️ IV. 5 NHƯỢC ĐIỂM & HƯỚNG HÓA GIẢI:\n`;
  if (data.cons && data.cons.length > 0) {
    data.cons.forEach((con, idx) => {
      text += `  ${idx + 1}. ${con}\n`;
    });
  } else {
    text += `  (Chưa nhập nhược điểm)\n`;
  }
  text += `\n`;

  text += `🎯 V. TƯ DUY KHẢO SÁT & ĐỀ XUẤT HÀNH ĐỘNG:\n`;
  text += `• "Khảo sát không phải đi xem nhà — Khảo sát là đi tìm lý do để khách mua căn nhà đó!"\n`;
  text += `• Đề xuất: Lên ngay kịch bản video 14 khối & bài viết đa kênh khai thác trúng tử huyệt cảm xúc!\n`;
  text += `=========================================`;

  return text;
}

function copyKhaosatFullReport() {
  const data = collectKhaosatFormData();
  const text = generateKhaosatReportText(data);

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép toàn bộ báo cáo khảo sát hiện trường vào Clipboard!', '🌹');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function copySpecificKhaosatReport(reportId) {
  const reports = getKhaosatReports();
  const r = reports[reportId];
  if (!r) return;
  const text = generateKhaosatReportText(r);

  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast(`📋 Đã copy báo cáo căn: "${r.title}"!`, '✅');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function downloadKhaosatReportTxt() {
  const data = collectKhaosatFormData();
  const text = generateKhaosatReportText(data);
  const fileName = `Khao_Sat_${(data.title || 'BDS').replace(/[^a-zA-Z0-9à-ỹÀ-Ỹ]/g, '_')}.txt`;

  try {
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    if (typeof showToast === 'function') {
      showToast('📥 Đã tải file báo cáo khảo sát .TXT về máy!', '💾');
    }
  } catch (e) {
    console.error('Download error:', e);
  }
}

function applyKhaosatToVideoSubsystem() {
  const data = collectKhaosatFormData();
  const s = data.nineSteps;

  let raw = `Cần bán gấp: ${data.title}\n`;
  if (s.step1Address) raw += `Địa chỉ: ${s.step1Address}\n`;
  if (s.step4Direction) raw += `Hướng: ${s.step4Direction}\n`;
  if (s.step7AlleyWidth) raw += `Đặc điểm đường: ${s.step7AlleyType === 'through' ? 'Hẻm thông' : 'Hẻm cụt'}, rộng ${s.step7AlleyWidth === 'car_pass' ? '5m ô tô tránh' : '4m ô tô tới cửa'}\n`;
  if (s.step2Note) raw += `Diện tích & Pháp lý: ${s.step2Note}\n`;

  if (data.pros && data.pros.length > 0) {
    raw += `Ưu điểm nổi bật:\n`;
    data.pros.forEach(p => raw += `- ${p}\n`);
  }
  if (data.cons && data.cons.length > 0) {
    raw += `Lưu ý & Điểm đặc biệt:\n`;
    data.cons.forEach(c => raw += `- ${c}\n`);
  }

  const rawEl = document.getElementById('rawInfoInput');
  if (rawEl) {
    rawEl.value = raw;
  }

  try {
    if (typeof extractPropertyData === 'function') {
      AppState.currentPropertyData = extractPropertyData(raw);
    }
  } catch (e) {}

  switchSubsystem('video');

  const videoWorkspace = document.getElementById('propertyInputWorkspace');
  if (videoWorkspace) {
    videoWorkspace.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  if (typeof showToast === 'function') {
    showToast('🎬 Đã nạp 5 ưu điểm & dữ liệu khảo sát vào Phân hệ 01 Video Script!', '🚀');
  }
}

function applyKhaosatToCopywritingSubsystem() {
  const data = collectKhaosatFormData();
  const s = data.nineSteps;

  let raw = `Cần bán: ${data.title}\n`;
  if (s.step1Address) raw += `Địa chỉ: ${s.step1Address}\n`;
  if (s.step4Direction) raw += `Hướng: ${s.step4Direction}\n`;
  if (s.step2Note) raw += `Pháp lý: ${s.step2Note}\n`;

  if (data.pros && data.pros.length > 0) {
    raw += `5 Ưu điểm vàng:\n`;
    data.pros.forEach(p => raw += `+ ${p}\n`);
  }
  if (data.cons && data.cons.length > 0) {
    raw += `Điểm cần lưu ý:\n`;
    data.cons.forEach(c => raw += `+ ${c}\n`);
  }

  const rawEl = document.getElementById('rawInfoInput');
  if (rawEl) {
    rawEl.value = raw;
  }

  try {
    if (typeof extractPropertyData === 'function') {
      AppState.currentPropertyData = extractPropertyData(raw);
    }
  } catch (e) {}

  switchSubsystem('copywriting');

  const copyWorkspace = document.getElementById('subsystemCopywritingWorkspace');
  if (copyWorkspace) {
    copyWorkspace.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  if (typeof showToast === 'function') {
    showToast('✍️ Đã nạp dữ liệu khảo sát vào Phân hệ 02 Copywriting Đa Kênh!', '🚀');
  }
}

function initKhaosatModule() {
  populateKhaosatSavedPropsDropdown();
  renderKhaosatSavedList();
  updateKhaosatDirectionBadge();
  onKhaosatCallCheckboxChange();
  updateKhaosatProgress();
  renderKhaosatLivePreview();
  switchKhaosatSubtab('call');
}

