let currentTestDealSubtab = 'l1';
let testDealAnswersCache = null;
let testDealPlanCache = null;

function getTestDealAnswers() {
  if (testDealAnswersCache) return testDealAnswersCache;
  if (typeof localStorage !== 'undefined') {
    const raw = localStorage.getItem(STORAGE_KEY_TEST_DEAL_ANSWERS);
    if (raw) {
      try {
        testDealAnswersCache = JSON.parse(raw);
        return testDealAnswersCache;
      } catch (e) {
        console.error('Error parsing test deal answers:', e);
      }
    }
  }
  testDealAnswersCache = {};
  return testDealAnswersCache;
}

function saveTestDealAnswers(answers) {
  testDealAnswersCache = answers;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_TEST_DEAL_ANSWERS, JSON.stringify(answers));
    } catch (e) {
      console.error('Error saving test deal answers:', e);
    }
  }
  updateTestDealProgress();
}

function getTestDealPlanState() {
  if (testDealPlanCache) return testDealPlanCache;
  if (typeof localStorage !== 'undefined') {
    const raw = localStorage.getItem(STORAGE_KEY_TEST_DEAL_PLAN);
    if (raw) {
      try {
        testDealPlanCache = JSON.parse(raw);
        return testDealPlanCache;
      } catch (e) {
        console.error('Error parsing test deal plan:', e);
      }
    }
  }
  testDealPlanCache = {};
  return testDealPlanCache;
}

function saveTestDealPlanState(state) {
  testDealPlanCache = state;
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem(STORAGE_KEY_TEST_DEAL_PLAN, JSON.stringify(state));
    } catch (e) {
      console.error('Error saving test deal plan:', e);
    }
  }
}

function switchTestDealSubtab(tabKey) {
  if (typeof document === 'undefined') return;
  currentTestDealSubtab = tabKey;
  const subtabs = ['l1', 'l2', 'l3', 'matrix', 'plan', 'all'];
  const paneMap = {
    l1: 'testdealPaneL1',
    l2: 'testdealPaneL2',
    l3: 'testdealPaneL3',
    matrix: 'testdealPaneMatrix',
    plan: 'testdealPanePlan'
  };

  subtabs.forEach(key => {
    const btn = document.getElementById(`btnTestdealSubtab${key.charAt(0).toUpperCase() + key.slice(1)}`);
    if (btn) {
      if (key === tabKey) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    }
  });

  if (tabKey === 'all') {
    Object.values(paneMap).forEach(paneId => {
      const pane = document.getElementById(paneId);
      if (pane) pane.style.display = 'flex';
    });
  } else {
    Object.keys(paneMap).forEach(key => {
      const pane = document.getElementById(paneMap[key]);
      if (pane) {
        pane.style.display = (key === tabKey) ? 'flex' : 'none';
      }
    });
  }

  if (tabKey === 'matrix' || tabKey === 'all') {
    renderTestDealEvaluation();
  }
  if (tabKey === 'plan' || tabKey === 'all') {
    renderTestDealPlan();
  }
  updateTestDealProgress();
}

function renderTestDealQuestions() {
  if (typeof document === 'undefined') return;
  const containerL1 = document.getElementById('testdealContainerL1');
  const containerL2 = document.getElementById('testdealContainerL2');
  if (!containerL1 || !containerL2) return;

  const answers = getTestDealAnswers();

  // Render Level 1
  const l1Questions = TEST_DEAL_QUESTIONS.filter(q => q.level === 1);
  let l1Html = '';
  let currentPart = '';

  l1Questions.forEach((q, idx) => {
    if (q.part !== currentPart) {
      currentPart = q.part;
      l1Html += `
        <div style="font-size: 0.88rem; font-weight: 800; color: #fbbf24; text-transform: uppercase; letter-spacing: 0.04em; margin-top: ${idx > 0 ? '0.75rem' : '0'}; padding-bottom: 0.35rem; border-bottom: 1px dashed rgba(251, 191, 36, 0.3);">
          ⚡ ${currentPart}
        </div>
      `;
    }

    const selected = answers[q.id] || '';

    l1Html += `
      <div class="testdeal-question-card" id="card_${q.id}">
        <div class="testdeal-question-title">
          <span class="testdeal-qnum-badge">Câu ${idx + 1}</span>
          <span>${q.text}</span>
        </div>
        <div class="testdeal-options-grid">
          ${q.options.map(opt => `
            <label class="testdeal-option-label ${selected === opt.key ? 'selected' : ''}" 
                   id="optLabel_${q.id}_${opt.key}" 
                   onclick="selectTestDealOption('${q.id}', '${opt.key}')">
              <span class="testdeal-opt-badge">${opt.key}</span>
              <span style="font-size: 0.84rem; line-height: 1.45;">${opt.text}</span>
            </label>
          `).join('')}
        </div>
      </div>
    `;
  });
  containerL1.innerHTML = l1Html;

  // Render Level 2
  const l2Questions = TEST_DEAL_QUESTIONS.filter(q => q.level === 2);
  let l2Html = '';

  l2Questions.forEach((q, idx) => {
    const selected = answers[q.id] || '';

    l2Html += `
      <div class="testdeal-question-card" id="card_${q.id}">
        <div class="testdeal-question-title">
          <span class="testdeal-qnum-badge" style="background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);">Câu ${idx + 21}</span>
          <div>
            <span style="color: #94a3b8; font-size: 0.78rem; text-transform: uppercase; font-weight: 700; display: block;">${q.part}</span>
            <span>${q.text}</span>
          </div>
        </div>
        <div class="testdeal-options-grid">
          ${q.options.map(opt => `
            <label class="testdeal-option-label ${selected === opt.key ? 'selected' : ''}" 
                   id="optLabel_${q.id}_${opt.key}" 
                   onclick="selectTestDealOption('${q.id}', '${opt.key}')">
              <span class="testdeal-opt-badge">${opt.key}</span>
              <span style="font-size: 0.84rem; line-height: 1.45;">${opt.text}</span>
            </label>
          `).join('')}
        </div>
      </div>
    `;
  });
  containerL2.innerHTML = l2Html;

  // Render Level 3 inputs if cached
  const inputQ31 = document.getElementById('testdealInputQ31');
  const inputQ32 = document.getElementById('testdealInputQ32');
  if (inputQ31 && answers.q31) inputQ31.value = answers.q31;
  if (inputQ32 && answers.q32) inputQ32.value = answers.q32;

  if (answers.q33) {
    const labelA = document.getElementById('labelTestdealQ33A');
    const labelB = document.getElementById('labelTestdealQ33B');
    const warn = document.getElementById('testdealQ33Warning');
    if (labelA && labelB) {
      if (answers.q33 === 'A') {
        labelA.classList.add('selected');
        labelB.classList.remove('selected');
        if (warn) warn.style.display = 'none';
      } else {
        labelB.classList.add('selected');
        labelA.classList.remove('selected');
        if (warn) warn.style.display = 'block';
      }
    }
  }

  updateTestDealProgress();
}

function selectTestDealOption(questionId, optionKey) {
  const answers = getTestDealAnswers();
  answers[questionId] = optionKey;
  saveTestDealAnswers(answers);

  if (questionId === 'q33') {
    const labelA = document.getElementById('labelTestdealQ33A');
    const labelB = document.getElementById('labelTestdealQ33B');
    const warn = document.getElementById('testdealQ33Warning');
    if (labelA && labelB) {
      if (optionKey === 'A') {
        labelA.classList.add('selected');
        labelB.classList.remove('selected');
        if (warn) warn.style.display = 'none';
      } else {
        labelB.classList.add('selected');
        labelA.classList.remove('selected');
        if (warn) warn.style.display = 'block';
      }
    }
    return;
  }

  const q = TEST_DEAL_QUESTIONS.find(item => item.id === questionId);
  if (!q) return;

  q.options.forEach(opt => {
    const el = document.getElementById(`optLabel_${questionId}_${opt.key}`);
    if (el) {
      if (opt.key === optionKey) {
        el.classList.add('selected');
      } else {
        el.classList.remove('selected');
      }
    }
  });

  updateTestDealProgress();
}

function onTestDealEssayInput(questionId) {
  const el = document.getElementById(questionId === 'q31' ? 'testdealInputQ31' : 'testdealInputQ32');
  if (!el) return;
  const answers = getTestDealAnswers();
  answers[questionId] = el.value;
  saveTestDealAnswers(answers);
}

function updateTestDealProgress() {
  if (typeof document === 'undefined') return { answeredCount: 0, score: 0 };
  const answers = getTestDealAnswers();

  let l1Answered = 0;
  let l2Answered = 0;
  let l3Answered = 0;
  let score = 0;

  TEST_DEAL_QUESTIONS.forEach(q => {
    const ans = answers[q.id];
    if (q.level === 1) {
      if (ans) {
        l1Answered++;
        if (ans === q.correct) score++;
      }
    } else if (q.level === 2) {
      if (ans) {
        l2Answered++;
        if (ans === q.correct) score++;
      }
    } else if (q.level === 3) {
      if (q.type === 'essay') {
        if (ans && ans.trim().length > 5) l3Answered++;
      } else if (q.type === 'commitment') {
        if (ans) l3Answered++;
      }
    }
  });

  const totalAnswered = l1Answered + l2Answered + l3Answered;
  const pct = Math.round((totalAnswered / 33) * 100);

  const fill = document.getElementById('testdealProgressFill');
  if (fill) fill.style.width = pct + '%';

  const textEl = document.getElementById('testdealProgressText');
  if (textEl) textEl.textContent = `${totalAnswered}/33 câu (${pct}%)`;

  const scoreEl = document.getElementById('testdealCurrentScoreText');
  if (scoreEl) scoreEl.textContent = `${score}/30 điểm`;

  const b1 = document.getElementById('testdealBadgeL1');
  if (b1) b1.textContent = `${l1Answered}/20`;

  const b2 = document.getElementById('testdealBadgeL2');
  if (b2) b2.textContent = `${l2Answered}/10`;

  const b3 = document.getElementById('testdealBadgeL3');
  if (b3) b3.textContent = `${l3Answered}/3`;

  return { answeredCount: totalAnswered, score: score, l1Answered, l2Answered, l3Answered };
}

function evaluateTestDealResults() {
  const answers = getTestDealAnswers();
  let l1Score = 0;
  let l2Score = 0;
  const incorrectQuestions = [];

  TEST_DEAL_QUESTIONS.forEach(q => {
    if (q.level === 1) {
      if (answers[q.id] === q.correct) {
        l1Score++;
      } else {
        incorrectQuestions.push({
          question: q,
          userAnswer: answers[q.id] || '(Chưa trả lời)'
        });
      }
    } else if (q.level === 2) {
      if (answers[q.id] === q.correct) {
        l2Score++;
      } else {
        incorrectQuestions.push({
          question: q,
          userAnswer: answers[q.id] || '(Chưa trả lời)'
        });
      }
    }
  });

  const totalScore = l1Score + l2Score;

  // Tier classification
  let tier = 'danger';
  let tierTitle = 'BÁO ĐỘNG — Sai Lệch Toàn Diện';
  let tierColor = '#ef4444';
  let tierDiagnosis = 'Trống hổng cả về tư duy gốc rễ lẫn hành vi thực tế. Làm việc ngẫu hứng, đổ lỗi ngoại cảnh, thiếu kỷ luật tự học.';
  let tierAction = 'Tái cấu trúc tư duy & Kỷ luật nghiêm ngặt. Buộc học lại từ đầu, áp đặt lộ trình 7 ngày dưới sự giám sát 100% của Trưởng phòng/Coach.';

  if (totalScore >= 25) {
    tier = 'excellent';
    tierTitle = 'XUẤT SẮC — Tư Duy Bán Hàng Tư Vấn Chuẩn (Consultative Selling)';
    tierColor = '#10b981';
    tierDiagnosis = 'Nắm vững triết lý tư vấn, kiểm soát tốt cuộc hội thoại, phân loại khách Net chuẩn xác và phản xạ chốt deal sắc bén.';
    tierAction = 'Thúc đẩy thực chiến (Fast-track Deal Execution). Giao rổ hàng giá trị cao/deal khó, ghép cặp làm Trưởng nhóm kinh doanh hoặc Co-trainer.';
  } else if (totalScore >= 18) {
    tier = 'good';
    tierTitle = 'KHÁ — Còn Hổng Kỹ Năng Thực Chiến';
    tierColor = '#fbbf24';
    tierDiagnosis = 'Đã nhận thức đúng về mặt tư duy nhưng phản xạ thực tế chưa đồng bộ. Vẫn bị thói quen cũ chi phối khi khách chê giá, im lặng, chần chừ.';
    tierAction = 'Huấn luyện 1-1 (1-on-1 Coaching Focus). Tập trung chỉnh sửa kịch bản đối thoại trực diện (Level 2), tổ chức đóng vai (Roleplay) giả định hàng tuần.';
  } else if (totalScore >= 10) {
    tier = 'weak';
    tierTitle = 'YẾU — Bán Hàng Theo Bản Năng Thô';
    tierColor = '#f97316';
    tierDiagnosis = 'Bị cuốn theo khách hàng, thiếu quy trình chuẩn. Mắc sai lầm nghiêm trọng ở khâu lọc khách và dẫn khách xem nhà. Dành sức cho sai đối tượng.';
    tierAction = 'Tái đào tạo quy trình (Immediate Retraining Required). Yêu cầu dừng dẫn khách tự do, buộc học lại bài bản quy trình BANT, SPIN và bộ kịch bản từ chối.';
  }

  // 5 Skills Matrix calculation
  const skillsEvaluation = TEST_DEAL_MATRIX_SKILLS.map(skill => {
    let passedCount = 0;
    skill.questions.forEach(qid => {
      const q = TEST_DEAL_QUESTIONS.find(item => item.id === qid);
      if (q && answers[qid] === q.correct) {
        passedCount++;
      }
    });
    const isPassed = passedCount >= skill.passingThreshold;
    return {
      skill,
      passedCount,
      total: skill.total,
      passingThreshold: skill.passingThreshold,
      isPassed
    };
  });

  return {
    totalScore,
    l1Score,
    l2Score,
    tier,
    tierTitle,
    tierColor,
    tierDiagnosis,
    tierAction,
    skillsEvaluation,
    incorrectQuestions,
    essayQ31: answers.q31 || '',
    essayQ32: answers.q32 || '',
    commitmentQ33: answers.q33 || ''
  };
}

