function renderTestDealPlan() {
  if (typeof document === 'undefined') return;
  const container = document.getElementById('testdealPlanContainer');
  if (!container) return;

  const planState = getTestDealPlanState();

  let html = '';
  TEST_DEAL_PLAN_7DAYS.forEach(day => {
    const dayTasks = day.tasks;
    const completedTasks = dayTasks.filter((_, idx) => !!planState[`d${day.day}_${idx}`]).length;
    const isDayDone = completedTasks === dayTasks.length;

    html += `
      <div class="testdeal-day-box ${isDayDone ? 'done' : ''}" id="dayBox_${day.day}">
        <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 0.5rem; border-bottom: 1px solid rgba(255, 255, 255, 0.08); padding-bottom: 0.6rem;">
          <div style="font-size: 1rem; font-weight: 800; color: #fff; display: flex; align-items: center; gap: 0.45rem;">
            <span style="background: ${isDayDone ? '#10b981' : '#8b5cf6'}; color: #fff; padding: 0.15rem 0.55rem; border-radius: 6px; font-size: 0.8rem;">Ngày ${day.day}</span>
            <span>${day.title}</span>
          </div>
          <div>
            <span class="testdeal-section-badge" style="background: ${isDayDone ? 'rgba(16, 185, 129, 0.2)' : 'rgba(255, 255, 255, 0.08)'}; color: ${isDayDone ? '#34d399' : '#94a3b8'}; border-color: ${isDayDone ? '#10b981' : 'rgba(255, 255, 255, 0.15)'};">
              ${isDayDone ? '✓ ĐÃ HOÀN THÀNH' : `Tiến độ: ${completedTasks}/${dayTasks.length}`}
            </span>
          </div>
        </div>

        <!-- Task Checklists -->
        <div style="display: flex; flex-direction: column; gap: 0.5rem;">
          ${dayTasks.map((task, tIdx) => {
            const isChecked = !!planState[`d${day.day}_${tIdx}`];
            return `
              <label style="display: flex; align-items: flex-start; gap: 0.65rem; font-size: 0.84rem; color: ${isChecked ? '#e2e8f0' : '#cbd5e1'}; cursor: pointer;">
                <input type="checkbox" style="margin-top: 0.2rem; accent-color: #10b981; width: 16px; height: 16px;" 
                       ${isChecked ? 'checked' : ''} 
                       onchange="toggleTestDealPlanTask(${day.day}, ${tIdx})" />
                <span style="${isChecked ? 'text-decoration: line-through; opacity: 0.8;' : ''}">${task}</span>
              </label>
            `;
          }).join('')}
        </div>

        <!-- KPI Box -->
        <div style="background: rgba(251, 191, 36, 0.08); border: 1px dashed rgba(251, 191, 36, 0.35); border-radius: var(--radius-sm); padding: 0.65rem 0.95rem; font-size: 0.8rem; color: #fbbf24; line-height: 1.45;">
          <strong>🎯 Chỉ số định lượng (KPIs):</strong> ${day.kpi}
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

function toggleTestDealPlanTask(dayNum, taskIdx) {
  const planState = getTestDealPlanState();
  const key = `d${dayNum}_${taskIdx}`;
  planState[key] = !planState[key];
  saveTestDealPlanState(planState);
  renderTestDealPlan();

  if (typeof showToast === 'function') {
    showToast(`📅 Đã cập nhật tiến độ Ngày ${dayNum}!`, '✅');
  }
}

function fillSampleTestDeal(type) {
  const preset = type === 'master' ? SAMPLE_TEST_DEAL_MASTER : SAMPLE_TEST_DEAL_STRUGGLING;
  saveTestDealAnswers(JSON.parse(JSON.stringify(preset)));
  renderTestDealQuestions();
  renderTestDealEvaluation();
  renderTestDealPlan();

  if (typeof showToast === 'function') {
    if (type === 'master') {
      showToast('💎 Đã nạp mẫu Chuyên Viên Xuất Sắc (29/30 điểm — Chuẩn Consultative Selling)!', '🎯');
    } else {
      showToast('✨ Đã nạp mẫu Môi Giới Bế Tắc (11/30 điểm — Bản năng thô cần can thiệp)!', '⚠️');
    }
  }
}

function resetTestDealForm() {
  saveTestDealAnswers({});
  saveTestDealPlanState({});
  renderTestDealQuestions();
  renderTestDealEvaluation();
  renderTestDealPlan();

  if (typeof showToast === 'function') {
    showToast('🗑️ Đã làm mới toàn bộ bài test!', '🔄');
  }
}

function generateTestDealReportText(evalData) {
  const data = evalData || evaluateTestDealResults();
  const dateStr = new Date().toLocaleString('vi-VN');

  let text = `=========================================\n`;
  text += `🎯 BÁO CÁO CHẨN ĐOÁN: VÌ SAO BẠN CHƯA CHỐT ĐƯỢC DEAL?\n`;
  text += `Hệ thống đánh giá năng lực Bán Hàng Tư Vấn (Consultative Selling)\n`;
  text += `Thời gian thực hiện: ${dateStr}\n`;
  text += `=========================================\n\n`;

  text += `I. KẾT QUẢ ĐÁNH GIÁ TỔNG HỢP:\n`;
  text += `• Tổng điểm: ${data.totalScore}/30 điểm (Level 1: ${data.l1Score}/20, Level 2: ${data.l2Score}/10)\n`;
  text += `• Phân loại: ${data.tierTitle}\n`;
  text += `• Chẩn đoán gốc rễ: ${data.tierDiagnosis}\n`;
  text += `• Kế hoạch can thiệp đào tạo: ${data.tierAction}\n\n`;

  text += `II. MA TRẬN 5 NHÓM KỸ NĂNG CỐT LÕI:\n`;
  data.skillsEvaluation.forEach(s => {
    text += `• ${s.skill.name}: ${s.passedCount}/${s.total} câu ${s.isPassed ? '[ĐẠT CHUẨN]' : '[CẦN CAN THIỆP]'}\n`;
    if (!s.isPassed) {
      text += `  -> Điểm nghẽn: ${s.skill.weaknessWarning}\n`;
    }
  });
  text += `\n`;

  text += `III. CÁC ĐIỂM NGHẼN CẦN ĐÓNG BĂNG NGAY (${data.incorrectQuestions.length} CÂU LÀM SAI):\n`;
  data.incorrectQuestions.forEach(item => {
    const q = item.question;
    const userOpt = q.options?.find(o => o.key === item.userAnswer)?.text || item.userAnswer;
    const correctOpt = q.options?.find(o => o.key === q.correct)?.text || q.correct;
    text += `• Câu ${q.id.replace('q','')}: ${q.text}\n`;
    text += `  - Đang làm sai: [${item.userAnswer}] ${userOpt}\n`;
    text += `  - Chuẩn Tư Vấn: [${q.correct}] ${correctOpt}\n`;
    text += `  - Giải thích: ${q.explanation}\n\n`;
  });

  text += `IV. TỰ PHẢN TƯ & CAM KẾT (LEVEL 3):\n`;
  text += `• Câu 31 (Sai nhiều nhất): ${data.essayQ31 || '(Chưa ghi)'}\n`;
  text += `• Câu 32 (Thay đổi 7 ngày): ${data.essayQ32 || '(Chưa ghi)'}\n`;
  text += `• Câu 33 (Sẵn sàng bỏ cách cũ): ${data.commitmentQ33 === 'A' ? 'CÓ (Cam kết 100%)' : 'Chưa cam kết'}\n\n`;

  text += `V. LỘ TRÌNH 7 NGÀY CHUYỂN ĐỔI TỪ BẢN NĂNG SANG TƯ VẤN:\n`;
  TEST_DEAL_PLAN_7DAYS.forEach(day => {
    text += `[Ngày ${day.day}] ${day.title}\n`;
    day.tasks.forEach(t => text += `  - ${t}\n`);
    text += `  * KPI: ${day.kpi}\n\n`;
  });

  text += `=========================================`;
  return text;
}

function copyTestDealReport() {
  const text = generateTestDealReportText();
  if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép toàn bộ báo cáo chẩn đoán vào Clipboard!', '🎯');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function downloadTestDealReportTxt() {
  const text = generateTestDealReportText();
  const fileName = 'Bao_Cao_Chan_Doan_Chot_Deal_' + new Date().toISOString().slice(0,10) + '.txt';
  try {
    const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    if (typeof showToast === 'function') {
      showToast('📥 Đã tải file báo cáo chẩn đoán .TXT về máy!', '💾');
    }
  } catch (e) {
    console.error('Download error:', e);
  }
}

function initTestDealModule() {
  renderTestDealQuestions();
  updateTestDealProgress();
  renderTestDealEvaluation();
  renderTestDealPlan();
  switchTestDealSubtab('l1');
}


