function getMorningEffectiveDate(now = new Date()) {
  const d = new Date(now.getTime());
  // Before 6:00 AM (0..5:59:59.999), it belongs to previous day's shift
  if (d.getHours() < 6) {
    d.setDate(d.getDate() - 1);
  }
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function formatVietnameseDate(d = new Date()) {
  const days = ['Chủ Nhật', 'Thứ Hai', 'Thứ Ba', 'Thứ Tư', 'Thứ Năm', 'Thứ Sáu', 'Thứ Bảy'];
  const dayName = days[d.getDay()];
  const date = d.getDate();
  const month = d.getMonth() + 1;
  const year = d.getFullYear();
  return `${dayName}, ${date} tháng ${month}, ${year}`;
}

function getMorningChecklistState() {
  const effDate = getMorningEffectiveDate();
  let data;
  try {
    const raw = (typeof localStorage !== 'undefined') ? localStorage.getItem(STORAGE_KEY_MORNING_CHECKLIST) : null;
    data = raw ? JSON.parse(raw) : null;
  } catch(e) {
    data = null;
  }

  if (!data) {
    data = {
      lastEffectiveDate: effDate,
      checkedIds: [],
      todayQualified: false,
      streak: 0,
      bestStreak: 0,
      history: {}
    };
    saveMorningChecklistState(data);
    return data;
  }

  // Check if new morning cycle started (passed 6:00 AM)
  if (data.lastEffectiveDate !== effDate) {
    const prevDate = data.lastEffectiveDate;
    const prevChecked = Array.isArray(data.checkedIds) ? data.checkedIds.length : 0;
    const prevQualified = prevChecked >= 12; // 80% threshold (12/14 = 85.7%)

    data.history = data.history || {};
    data.history[prevDate] = {
      checkedCount: prevChecked,
      total: 14,
      percent: Math.round((prevChecked / 14) * 100),
      qualified: prevQualified
    };

    // Check consecutive day
    const d1 = new Date(prevDate + 'T00:00:00');
    const d2 = new Date(effDate + 'T00:00:00');
    const diffDays = Math.round((d2 - d1) / (1000 * 60 * 60 * 24));

    if (diffDays === 1 && prevQualified) {
      // Streak continues!
    } else {
      // Skipped day or didn't qualify yesterday -> streak resets
      data.streak = 0;
    }

    // Fresh checklist for today
    data.lastEffectiveDate = effDate;
    data.checkedIds = [];
    data.todayQualified = false;
    saveMorningChecklistState(data);
  }

  return data;
}

function saveMorningChecklistState(data) {
  try {
    if (typeof localStorage !== 'undefined') {
      localStorage.setItem(STORAGE_KEY_MORNING_CHECKLIST, JSON.stringify(data));
    }
  } catch(e) {
    console.error('Error saving morning checklist:', e);
  }
}

function initMorningChecklistModule() {
  const data = getMorningChecklistState();
  renderMorningChecklist();
}

function renderMorningChecklist() {
  const data = getMorningChecklistState();
  const checkedSet = new Set(data.checkedIds || []);
  const checkedCount = checkedSet.size;
  const totalTasks = 14;
  const percent = Math.min(100, Math.round((checkedCount / totalTasks) * 100));

  // 1. Update Streak & Date
  const streakCountEl = document.getElementById('morningStreakCount');
  if (streakCountEl) streakCountEl.textContent = data.streak || 0;

  const headerStreakBadgeEl = document.getElementById('headerMorningStreakBadge');
  if (headerStreakBadgeEl) {
    headerStreakBadgeEl.textContent = `🔥 ${data.streak || 0}`;
  }
  const navMorningBadgeEl = document.getElementById('navMorningBadge');
  if (navMorningBadgeEl) {
    navMorningBadgeEl.textContent = `🔥 ${data.streak || 0}`;
  }

  const dateSubEl = document.getElementById('morningCurrentDateStr');
  if (dateSubEl) {
    dateSubEl.textContent = formatVietnameseDate(new Date());
  }

  // 2. Update Percentage & Progress Fill
  const percentTextEl = document.getElementById('morningPercentText');
  if (percentTextEl) {
    percentTextEl.textContent = `${percent}%`;
    if (percent >= 80) {
      percentTextEl.style.color = '#34d399';
    } else if (percent > 0) {
      percentTextEl.style.color = '#fbbf24';
    } else {
      percentTextEl.style.color = '#f8fafc';
    }
  }

  const progressFillEl = document.getElementById('morningProgressFill');
  if (progressFillEl) {
    progressFillEl.style.width = `${percent}%`;
    if (percent >= 80) {
      progressFillEl.style.background = 'linear-gradient(90deg, #10b981, #059669)';
      progressFillEl.style.boxShadow = '0 0 15px rgba(16, 185, 129, 0.6)';
    } else {
      progressFillEl.style.background = 'linear-gradient(90deg, #f59e0b, #fbbf24)';
      progressFillEl.style.boxShadow = '0 0 12px rgba(245, 158, 11, 0.4)';
    }
  }

  // 3. Render 4 Categories and Task Cards
  const container = document.getElementById('morningTasksContainer');
  if (!container) return;

  let html = '';
  MORNING_CHECKLIST_DATA.forEach(cat => {
    let catChecked = 0;
    cat.tasks.forEach(t => {
      if (checkedSet.has(t.id)) catChecked++;
    });

    html += `<div class="morning-category-block">`;
    html += `  <div class="morning-category-header">`;
    html += `    <span>${cat.categoryIcon} ${cat.categoryTitle}</span>`;
    html += `    <span class="morning-category-badge">${catChecked}/${cat.tasks.length}</span>`;
    html += `  </div>`;

    cat.tasks.forEach(task => {
      const isChecked = checkedSet.has(task.id);
      html += `  <div class="morning-task-card ${isChecked ? 'checked' : ''}" onclick="toggleMorningTask('${task.id}')">`;
      html += `    <div class="morning-custom-checkbox">${isChecked ? '✓' : ''}</div>`;
      html += `    <div class="morning-task-body">`;
      html += `      <div class="morning-task-title">${task.title}</div>`;
      html += `      <div class="morning-task-subtext">${task.subtext}</div>`;
      html += `    </div>`;
      if (task.quickSubsystem && task.quickLabel) {
        html += `    <button type="button" class="morning-task-quick-btn" onclick="event.stopPropagation(); switchSubsystem('${task.quickSubsystem}')" title="Chuyển nhanh đến phân hệ liên quan">`;
        html += `      👉 ${task.quickLabel}`;
        html += `    </button>`;
      }
      html += `  </div>`;
    });

    html += `</div>`;
  });

  container.innerHTML = html;
}

function toggleMorningTask(taskId) {
  const data = getMorningChecklistState();
  const set = new Set(data.checkedIds || []);
  if (set.has(taskId)) {
    set.delete(taskId);
  } else {
    set.add(taskId);
  }
  data.checkedIds = Array.from(set);

  const wasQualified = !!data.todayQualified;
  const isNowQualified = data.checkedIds.length >= 12; // 80% threshold (12/14)

  if (!wasQualified && isNowQualified) {
    data.todayQualified = true;
    data.streak = (data.streak || 0) + 1;
    if (data.streak > (data.bestStreak || 0)) {
      data.bestStreak = data.streak;
    }
    if (typeof showToast === 'function') {
      showToast(`🔥 Tuyệt vời! Bạn đã hoàn thành ${Math.round((data.checkedIds.length/14)*100)}% checklist và đạt chuỗi Streak ${data.streak} ngày liên tiếp!`, '🎉');
    }
  } else if (wasQualified && !isNowQualified) {
    data.todayQualified = false;
    data.streak = Math.max(0, (data.streak || 1) - 1);
  }

  saveMorningChecklistState(data);
  renderMorningChecklist();
}

function completeAllMorningChecklist() {
  const data = getMorningChecklistState();
  const allIds = [];
  MORNING_CHECKLIST_DATA.forEach(cat => {
    cat.tasks.forEach(t => allIds.push(t.id));
  });
  data.checkedIds = allIds;

  if (!data.todayQualified) {
    data.todayQualified = true;
    data.streak = (data.streak || 0) + 1;
    if (data.streak > (data.bestStreak || 0)) {
      data.bestStreak = data.streak;
    }
    if (typeof showToast === 'function') {
      showToast(`🔥 Xuất sắc! Hoàn thành 100% Checklist Buổi Sáng — Streak: ${data.streak} ngày liên tiếp!`, '🌟');
    }
  } else {
    if (typeof showToast === 'function') {
      showToast('✅ Đã tích chọn toàn bộ 14/14 việc buổi sáng!', '✅');
    }
  }

  saveMorningChecklistState(data);
  renderMorningChecklist();
}

function resetMorningChecklist() {
  const data = getMorningChecklistState();
  if (data.todayQualified) {
    data.streak = Math.max(0, (data.streak || 1) - 1);
    data.todayQualified = false;
  }
  data.checkedIds = [];
  saveMorningChecklistState(data);
  renderMorningChecklist();

  if (typeof showToast === 'function') {
    showToast('🔄 Đã làm mới checklist buổi sáng hôm nay về 0%!', 'ℹ️');
  }
}

function fillMorningSample80() {
  const data = getMorningChecklistState();
  const allIds = [];
  MORNING_CHECKLIST_DATA.forEach(cat => {
    cat.tasks.forEach(t => allIds.push(t.id));
  });
  // Pick first 12 tasks (85.7% >= 80%)
  data.checkedIds = allIds.slice(0, 12);
  if (!data.todayQualified) {
    data.todayQualified = true;
    data.streak = (data.streak || 0) + 1;
    if (data.streak > (data.bestStreak || 0)) {
      data.bestStreak = data.streak;
    }
  }
  saveMorningChecklistState(data);
  renderMorningChecklist();

  if (typeof showToast === 'function') {
    showToast(`⚡ Đã nạp mẫu đạt chuẩn 12/14 việc (86%) — Streak: ${data.streak} ngày liên tiếp!`, '🔥');
  }
}

function generateMorningReportText() {
  const data = getMorningChecklistState();
  const checkedSet = new Set(data.checkedIds || []);
  const checkedCount = checkedSet.size;
  const total = 14;
  const percent = Math.round((checkedCount / total) * 100);
  const dateFormatted = formatVietnameseDate(new Date());

  let report = `=========================================\n`;
  report += `☀️ CHECKLIST BUỔI SÁNG — KỶ LUẬT MÔI GIỚI BĐS\n`;
  report += `📅 Ngày: ${dateFormatted}\n`;
  report += `🔥 Chuỗi Streak: ${data.streak || 0} ngày liên tiếp\n`;
  report += `📊 Tiến độ hoàn thành: ${checkedCount}/${total} việc (${percent}%)\n`;
  report += `🏆 Đạt chuẩn ngày (≥80%): ${data.todayQualified ? 'ĐẠT CHUẨN ✅' : 'CHƯA ĐẠT ⏳'}\n`;
  report += `=========================================\n\n`;

  MORNING_CHECKLIST_DATA.forEach(cat => {
    report += `${cat.categoryIcon} ${cat.categoryTitle}:\n`;
    cat.tasks.forEach(t => {
      const isDone = checkedSet.has(t.id);
      report += `  [${isDone ? 'X' : ' '}] ${t.title} (${t.subtext})\n`;
    });
    report += `\n`;
  });

  report += `💡 Lời nhắc: Kỷ luật làm đủ checklist mỗi sáng = Môi giới chuyên nghiệp!\n`;
  report += `Checklist tự reset lúc 6:00 sáng mỗi ngày.\n`;
  return report;
}

function copyMorningChecklistReport() {
  const text = generateMorningReportText();
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép báo cáo kỷ luật buổi sáng vào clipboard!', '✅');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}


// =============================================================================
// BẢNG TÍNH BÀI TOÁN LÃI VAY & DÒNG TIỀN (MORTGAGE, CASHFLOW & ROI CALCULATOR)
// =============================================================================
const MORTGAGE_PRESETS = {
  safe_home: {
    name: 'An Cư An Toàn',
    loanPercent: 50,
    loanYears: 20,
    preferRate: 7.5,
    preferMonths: 24,
    floatingRate: 10.5,
    method: 'reducing'
  },
  max_leverage: {
    name: 'Đòn Bẩy 70%',
    loanPercent: 70,
    loanYears: 25,
    preferRate: 7.0,
    preferMonths: 24,
    floatingRate: 10.0,
    method: 'reducing'
  },
  cashflow_invest: {
    name: 'Đầu Tư Dòng Tiền',
    loanPercent: 60,
    loanYears: 20,
    preferRate: 7.5,
    preferMonths: 24,
    floatingRate: 10.5,
    method: 'reducing'
  },
  short_term: {
    name: 'Lướt Sóng Ngắn Hạn',
    loanPercent: 50,
    loanYears: 5,
    preferRate: 8.0,
    preferMonths: 12,
    floatingRate: 11.0,
    method: 'reducing'
  }
};

let currentMortgageScheduleTab = '12m'; // '12m' | 'years'
let lastMortgageCalculationResult = null;

function formatMoneyVietnamese(num) {
  if (isNaN(num) || num === null || num === undefined) return '0 đ';
  const abs = Math.abs(num);
  if (abs >= 1000000000) {
    const ty = parseFloat((num / 1000000000).toFixed(2));
    return `${ty} Tỷ`;
  }
  if (abs >= 1000000) {
    const tr = parseFloat((num / 1000000).toFixed(2));
    return `${tr} Triệu`;
  }
  return num.toLocaleString('vi-VN') + ' đ';
}

function calculateMortgage(params = {}) {
  const totalPrice = parseFloat(params.totalPrice) || 8500000000;
  const loanPercent = Math.min(90, Math.max(5, parseFloat(params.loanPercent) || 70));
  const loanYears = Math.min(35, Math.max(1, parseInt(params.loanYears) || 20));
  const preferRate = Math.max(0, parseFloat(params.preferRate) || 7.5);
  const preferMonths = Math.min(loanYears * 12, Math.max(0, parseInt(params.preferMonths) || 24));
  const floatingRate = Math.max(0, parseFloat(params.floatingRate) || 10.5);
  const method = params.method === 'annuity' ? 'annuity' : 'reducing';
  const monthlyRent = Math.max(0, parseFloat(params.monthlyRent) || 25000000);
  const operatingCostPercent = Math.min(50, Math.max(0, parseFloat(params.operatingCostPercent) || 10));
  const appreciationRate = Math.min(50, Math.max(0, parseFloat(params.appreciationRate) || 8));

  const loanAmount = Math.round(totalPrice * (loanPercent / 100));
  const equityAmount = totalPrice - loanAmount;
  const totalMonths = loanYears * 12;

  const schedule = [];
  let remainingPrincipal = loanAmount;
  let totalInterest = 0;

  for (let m = 1; m <= totalMonths; m++) {
    const isPrefer = m <= preferMonths;
    const annualRate = isPrefer ? preferRate : floatingRate;
    const monthlyRate = (annualRate / 100) / 12;

    const openingBalance = remainingPrincipal;
    let principalPaid = 0;
    let interestPaid = 0;
    let totalPayment = 0;

    if (method === 'reducing') {
      principalPaid = Math.round(loanAmount / totalMonths);
      if (m === totalMonths) principalPaid = openingBalance;
      interestPaid = Math.round(openingBalance * monthlyRate);
      totalPayment = principalPaid + interestPaid;
      remainingPrincipal = Math.max(0, openingBalance - principalPaid);
    } else {
      // Annuity / Equal Installment
      const r = monthlyRate;
      const n = totalMonths - m + 1;
      const emi = (r === 0) ? Math.round(openingBalance / n) : Math.round(openingBalance * r * Math.pow(1 + r, n) / (Math.pow(1 + r, n) - 1));
      interestPaid = Math.round(openingBalance * r);
      principalPaid = Math.min(openingBalance, emi - interestPaid);
      totalPayment = principalPaid + interestPaid;
      remainingPrincipal = Math.max(0, openingBalance - principalPaid);
    }

    totalInterest += interestPaid;

    schedule.push({
      month: m,
      openingBalance,
      principalPaid,
      interestPaid,
      totalPayment,
      remainingPrincipal,
      rate: annualRate
    });
  }

  const firstMonth = schedule[0] || { totalPayment: 0, principalPaid: 0, interestPaid: 0 };
  const lastMonth = schedule[schedule.length - 1] || { totalPayment: 0 };
  const avgMonthlyPayment = Math.round((loanAmount + totalInterest) / totalMonths);

  // Cashflow
  const netMonthlyRent = Math.round(monthlyRent * (1 - operatingCostPercent / 100));
  const firstMonthGap = netMonthlyRent - firstMonth.totalPayment;
  const isPositiveCashflow = firstMonthGap >= 0;
  const monthlyTopUp = Math.abs(firstMonthGap);
  const rentCoveragePercent = firstMonth.totalPayment > 0 ? Math.min(100, Math.round((netMonthlyRent / firstMonth.totalPayment) * 100)) : 100;

  // Yields
  const grossYield = totalPrice > 0 ? parseFloat(((monthlyRent * 12 / totalPrice) * 100).toFixed(2)) : 0;
  const netYield = totalPrice > 0 ? parseFloat(((netMonthlyRent * 12 / totalPrice) * 100).toFixed(2)) : 0;

  // 5 Years Projection
  const m60 = schedule[Math.min(59, schedule.length - 1)];
  const remainingAt5Y = m60 ? m60.remainingPrincipal : 0;
  const propertyValueAt5Y = Math.round(totalPrice * Math.pow(1 + appreciationRate / 100, 5));
  const netEquityAt5Y = propertyValueAt5Y - remainingAt5Y;
  const capitalGainAt5Y = propertyValueAt5Y - totalPrice;

  // DTI (Debt-to-income recommendation 60%)
  const minRequiredIncome = Math.round(firstMonth.totalPayment / 0.6);

  return {
    totalPrice,
    loanPercent,
    loanAmount,
    equityAmount,
    loanYears,
    totalMonths,
    preferRate,
    preferMonths,
    floatingRate,
    method,
    monthlyRent,
    netMonthlyRent,
    operatingCostPercent,
    appreciationRate,
    totalInterest,
    totalPaymentAll: loanAmount + totalInterest,
    firstMonthPayment: firstMonth.totalPayment,
    firstMonthPrincipal: firstMonth.principalPaid,
    firstMonthInterest: firstMonth.interestPaid,
    lastMonthPayment: lastMonth.totalPayment,
    avgMonthlyPayment,
    minRequiredIncome,
    firstMonthGap,
    isPositiveCashflow,
    monthlyTopUp,
    rentCoveragePercent,
    grossYield,
    netYield,
    propertyValueAt5Y,
    remainingAt5Y,
    netEquityAt5Y,
    capitalGainAt5Y,
    schedule
  };
}

function getMortgageInputs() {
  const priceInput = document.getElementById('mortgageInputPrice');
  const rentInput = document.getElementById('mortgageInputRent');
  const loanPercentInput = document.getElementById('mortgageInputLoanPercent');
  const yearsSelect = document.getElementById('mortgageSelectYears');
  const preferMonthsSelect = document.getElementById('mortgageSelectPreferMonths');
  const preferRateInput = document.getElementById('mortgageInputPreferRate');
  const floatingRateInput = document.getElementById('mortgageInputFloatingRate');
  const methodAnnuityRadio = document.getElementById('mortgageMethodAnnuity');
  const operatingCostInput = document.getElementById('mortgageInputOperatingCost');
  const appreciationInput = document.getElementById('mortgageInputAppreciation');

  return {
    totalPrice: priceInput ? parseFloat(priceInput.value) || 8500000000 : 8500000000,
    monthlyRent: rentInput ? parseFloat(rentInput.value) || 25000000 : 25000000,
    loanPercent: loanPercentInput ? parseFloat(loanPercentInput.value) || 70 : 70,
    loanYears: yearsSelect ? parseInt(yearsSelect.value) || 20 : 20,
    preferMonths: preferMonthsSelect ? parseInt(preferMonthsSelect.value) || 24 : 24,
    preferRate: preferRateInput ? parseFloat(preferRateInput.value) || 7.5 : 7.5,
    floatingRate: floatingRateInput ? parseFloat(floatingRateInput.value) || 10.5 : 10.5,
    method: (methodAnnuityRadio && methodAnnuityRadio.checked) ? 'annuity' : 'reducing',
    operatingCostPercent: operatingCostInput ? parseFloat(operatingCostInput.value) || 10 : 10,
    appreciationRate: appreciationInput ? parseFloat(appreciationInput.value) || 8 : 8
  };
}

function onMortgageInputChanged() {
  recalculateMortgageAndRender();
}

function onMortgageSliderChanged(val) {
  const numInput = document.getElementById('mortgageInputLoanPercent');
  if (numInput) numInput.value = val;
  recalculateMortgageAndRender();
}

function onMortgagePercentInputChanged(val) {
  const slider = document.getElementById('mortgageRangeLoanPercent');
  if (slider) slider.value = val;
  recalculateMortgageAndRender();
}

function applyMortgagePreset(presetKey) {
  const p = MORTGAGE_PRESETS[presetKey];
  if (!p) return;

  const loanPercentInput = document.getElementById('mortgageInputLoanPercent');
  const slider = document.getElementById('mortgageRangeLoanPercent');
  const yearsSelect = document.getElementById('mortgageSelectYears');
  const preferMonthsSelect = document.getElementById('mortgageSelectPreferMonths');
  const preferRateInput = document.getElementById('mortgageInputPreferRate');
  const floatingRateInput = document.getElementById('mortgageInputFloatingRate');
  const methodReducingRadio = document.getElementById('mortgageMethodReducing');
  const methodAnnuityRadio = document.getElementById('mortgageMethodAnnuity');

  if (loanPercentInput) loanPercentInput.value = p.loanPercent;
  if (slider) slider.value = p.loanPercent;
  if (yearsSelect) yearsSelect.value = p.loanYears;
  if (preferMonthsSelect) preferMonthsSelect.value = p.preferMonths;
  if (preferRateInput) preferRateInput.value = p.preferRate;
  if (floatingRateInput) floatingRateInput.value = p.floatingRate;
  if (p.method === 'annuity') {
    if (methodAnnuityRadio) methodAnnuityRadio.checked = true;
  } else {
    if (methodReducingRadio) methodReducingRadio.checked = true;
  }

  recalculateMortgageAndRender();

  if (typeof showToast === 'function') {
    showToast(`⚡ Đã áp dụng gói mẫu: ${p.name}!`, '💡');
  }
}

function recalculateMortgageAndRender() {
  const inputs = getMortgageInputs();
  const res = calculateMortgage(inputs);
  lastMortgageCalculationResult = res;

  // 1. Update In-Words previews
  const priceInWords = document.getElementById('mortgagePriceInWords');
  if (priceInWords) priceInWords.textContent = formatMoneyVietnamese(res.totalPrice);

  const rentInWords = document.getElementById('mortgageRentInWords');
  if (rentInWords) rentInWords.textContent = formatMoneyVietnamese(res.monthlyRent) + '/tháng';

  const loanPercentLabel = document.getElementById('mortgageLoanPercentLabel');
  if (loanPercentLabel) loanPercentLabel.textContent = res.loanPercent + '%';

  const pillLoan = document.getElementById('mortgagePillLoanAmount');
  if (pillLoan) pillLoan.textContent = res.loanAmount.toLocaleString('vi-VN') + ' đ';

  const pillEquity = document.getElementById('mortgagePillEquityAmount');
  if (pillEquity) pillEquity.textContent = res.equityAmount.toLocaleString('vi-VN') + ' đ';

  // 2. Monthly Debt Highlights
  const valFirst = document.getElementById('mortgageValFirstMonth');
  if (valFirst) valFirst.textContent = (res.firstMonthPayment / 1000000).toFixed(2) + ' Tr';

  const valFirstSub = document.getElementById('mortgageValFirstMonthSub');
  if (valFirstSub) valFirstSub.textContent = `Gốc: ${(res.firstMonthPrincipal / 1000000).toFixed(1)} Tr + Lãi: ${(res.firstMonthInterest / 1000000).toFixed(1)} Tr`;

  const valLast = document.getElementById('mortgageValLastMonth');
  if (valLast) valLast.textContent = (res.lastMonthPayment / 1000000).toFixed(2) + ' Tr';

  const valIncome = document.getElementById('mortgageValRequiredIncome');
  if (valIncome) valIncome.textContent = '≥ ' + Math.ceil(res.minRequiredIncome / 1000000) + ' Tr';

  const valTotalInt = document.getElementById('mortgageValTotalInterest');
  if (valTotalInt) valTotalInt.textContent = (res.totalInterest / 1000000000).toFixed(2) + ' Tỷ';

  const valTotalPay = document.getElementById('mortgageValTotalPayment');
  if (valTotalPay) valTotalPay.textContent = (res.totalPaymentAll / 1000000000).toFixed(2) + ' Tỷ';

  // 3. Cashflow Gap Banner
  const gapBanner = document.getElementById('mortgageGapBanner');
  const gapMainVal = document.getElementById('mortgageGapMainVal');
  const gapSubtext = document.getElementById('mortgageGapSubtext');

  if (gapBanner && gapMainVal && gapSubtext) {
    if (res.isPositiveCashflow) {
      gapBanner.className = 'mortgage-gap-banner positive';
      gapMainVal.textContent = `🟢 Dòng tiền dương ròng: +${(res.firstMonthGap / 1000000).toFixed(2)} Triệu/tháng`;
      gapSubtext.innerHTML = `Doanh thu thuê ròng đạt <strong>${(res.netMonthlyRent / 1000000).toFixed(1)} Triệu/tháng</strong> (sau trừ ${res.operatingCostPercent}% chi phí). Sau khi trả hết gốc & lãi ngân hàng, tài sản <strong>tự sinh lời thặng dư</strong> mỗi tháng!`;
    } else {
      gapBanner.className = 'mortgage-gap-banner negative';
      gapMainVal.textContent = `🔴 Mỗi tháng bù thêm: ${(res.monthlyTopUp / 1000000).toFixed(2)} Triệu/tháng`;
      gapSubtext.innerHTML = `Doanh thu thuê ròng đạt <strong>${(res.netMonthlyRent / 1000000).toFixed(1)} Triệu/tháng</strong>. Tiền thuê đã gánh trả <strong>${res.rentCoveragePercent}%</strong> nghĩa vụ ngân hàng. Khách chỉ cần trích thêm <strong>${(res.monthlyTopUp / 1000000).toFixed(1)} Triệu/tháng</strong> để nắm trọn căn nhà <strong>${formatMoneyVietnamese(res.totalPrice)}</strong>!`;
    }
  }

  // 4. Yields & 5 Years Projection
  const valGrossYield = document.getElementById('mortgageValGrossYield');
  if (valGrossYield) valGrossYield.textContent = res.grossYield + '%/năm';

  const valNetYield = document.getElementById('mortgageValNetYield');
  if (valNetYield) valNetYield.textContent = res.netYield + '%/năm';

  const valVal5Y = document.getElementById('mortgageValValue5Y');
  if (valVal5Y) valVal5Y.textContent = (res.propertyValueAt5Y / 1000000000).toFixed(2) + ' Tỷ';

  const valDebt5Y = document.getElementById('mortgageValDebt5Y');
  if (valDebt5Y) valDebt5Y.textContent = (res.remainingAt5Y / 1000000000).toFixed(2) + ' Tỷ';

  const valEquity5Y = document.getElementById('mortgageValEquity5Y');
  if (valEquity5Y) valEquity5Y.textContent = (res.netEquityAt5Y / 1000000000).toFixed(2) + ' Tỷ';

  const valGain5Y = document.getElementById('mortgageValGain5Y');
  if (valGain5Y) valGain5Y.textContent = '+' + (res.capitalGainAt5Y / 1000000000).toFixed(2) + ' Tỷ';

  // 5. Advisor Script
  const scriptContent = document.getElementById('mortgageAdvisorScriptContent');
  if (scriptContent) {
    scriptContent.textContent = generateMortgageAdvisorScript(res);
  }

  // 6. Schedule Table
  renderMortgageScheduleTable(res.schedule, currentMortgageScheduleTab);
}

function renderMortgageScheduleTable(schedule, mode) {
  const tbody = document.getElementById('mortgageScheduleTableBody');
  if (!tbody || !schedule || schedule.length === 0) return;

  let rowsHtml = '';
  if (mode === '12m') {
    const list = schedule.slice(0, 12);
    list.forEach(row => {
      rowsHtml += `<tr>
        <td style="text-align: left; font-weight: 600; color: #fbbf24;">Tháng ${row.month}</td>
        <td>${(row.openingBalance / 1000000).toFixed(1)} Tr</td>
        <td style="color: #38bdf8;">${(row.principalPaid / 1000000).toFixed(1)} Tr</td>
        <td style="color: #fb923c;">${(row.interestPaid / 1000000).toFixed(1)} Tr</td>
        <td style="font-weight: 700; color: #f8fafc;">${(row.totalPayment / 1000000).toFixed(1)} Tr</td>
        <td>${(row.remainingPrincipal / 1000000).toFixed(1)} Tr</td>
      </tr>`;
    });
  } else {
    // Yearly breakdown
    const yearsCount = Math.ceil(schedule.length / 12);
    for (let y = 1; y <= yearsCount; y++) {
      const yearRows = schedule.slice((y - 1) * 12, y * 12);
      if (yearRows.length === 0) continue;
      const opening = yearRows[0].openingBalance;
      const closing = yearRows[yearRows.length - 1].remainingPrincipal;
      const totalPrincipal = yearRows.reduce((sum, r) => sum + r.principalPaid, 0);
      const totalInterest = yearRows.reduce((sum, r) => sum + r.interestPaid, 0);
      const totalPayment = totalPrincipal + totalInterest;

      rowsHtml += `<tr>
        <td style="text-align: left; font-weight: 600; color: #34d399;">Năm ${y}</td>
        <td>${(opening / 1000000000).toFixed(2)} Tỷ</td>
        <td style="color: #38bdf8;">${(totalPrincipal / 1000000000).toFixed(2)} Tỷ</td>
        <td style="color: #fb923c;">${(totalInterest / 1000000000).toFixed(2)} Tỷ</td>
        <td style="font-weight: 700; color: #f8fafc;">${(totalPayment / 1000000000).toFixed(2)} Tỷ</td>
        <td>${(closing / 1000000000).toFixed(2)} Tỷ</td>
      </tr>`;
    }
  }

  tbody.innerHTML = rowsHtml;
}

function switchMortgageScheduleTab(mode) {
  currentMortgageScheduleTab = mode;
  const btn12 = document.getElementById('btnMortgageTab12M');
  const btnYears = document.getElementById('btnMortgageTabYears');
  if (btn12) {
    if (mode === '12m') btn12.classList.add('active');
    else btn12.classList.remove('active');
  }
  if (btnYears) {
    if (mode === 'years') btnYears.classList.add('active');
    else btnYears.classList.remove('active');
  }
  if (lastMortgageCalculationResult) {
    renderMortgageScheduleTable(lastMortgageCalculationResult.schedule, mode);
  }
}

function generateMortgageAdvisorScript(calc) {
  const c = calc || lastMortgageCalculationResult || calculateMortgage();
  const priceStr = formatMoneyVietnamese(c.totalPrice);
  const equityStr = formatMoneyVietnamese(c.equityAmount);
  const loanStr = formatMoneyVietnamese(c.loanAmount);
  const rentStr = (c.monthlyRent / 1000000).toFixed(1) + ' triệu/tháng';
  const firstPayStr = (c.firstMonthPayment / 1000000).toFixed(1) + ' triệu/tháng';
  const topUpStr = (c.monthlyTopUp / 1000000).toFixed(1) + ' triệu/tháng';
  const value5YStr = (c.propertyValueAt5Y / 1000000000).toFixed(2) + ' tỷ';
  const equity5YStr = (c.netEquityAt5Y / 1000000000).toFixed(2) + ' tỷ';

  let scriptText = `💎 BÀI TOÁN ĐÒN BẨY TÀI CHÍNH THÔNG MINH CHO CĂN NHÀ ${priceStr.toUpperCase()}:\n\n`;
  scriptText += `1️⃣ VỐN BAN ĐẦU RẤT HỢP LÝ: Quý khách chỉ cần chuẩn bị ${equityStr} (${100 - c.loanPercent}% vốn tự có). Ngân hàng giải ngân ${loanStr} (${c.loanPercent}%) với lãi suất ưu đãi ${c.preferRate}%/năm trong ${c.preferMonths} tháng đầu.\n\n`;
  
  if (c.isPositiveCashflow) {
    scriptText += `2️⃣ BẤT ĐỘNG SẢN TỰ SINH LỜI DÒNG TIỀN: Khai thác cho thuê đạt ${rentStr}. Sau khi khấu trừ toàn bộ gốc + lãi ngân hàng (${firstPayStr}), tài sản vẫn mang về dòng tiền thặng dư ròng +${(c.firstMonthGap / 1000000).toFixed(1)} triệu/tháng vào tài khoản quý khách!\n\n`;
  } else {
    scriptText += `2️⃣ NGƯỜI THUÊ GÁNH HỘ ${c.rentCoveragePercent}% NỢ NGÂN HÀNG: Căn nhà đang tạo dòng tiền thuê ${rentStr}. Mỗi tháng quý khách chỉ cần trích thêm khoảng ${topUpStr} từ thu nhập kinh doanh là đã thanh toán toàn bộ nghĩa vụ ngân hàng và nắm quyền sở hữu trọn đời tài sản ${priceStr}!\n\n`;
  }

  scriptText += `3️⃣ TĂNG TRƯỞNG TÀI SẢN BỨT PHÁ SAU 5 NĂM: Với tỷ lệ tăng giá thận trọng ${c.appreciationRate}%/năm, giá trị căn nhà ước tính đạt ${value5YStr}. Dư nợ ngân hàng giảm sâu còn ${(c.remainingAt5Y / 1000000000).toFixed(2)} tỷ. Khối tài sản ròng thực tế của quý khách tăng vọt lên ${equity5YStr}, nhân gấp bội số vốn ${equityStr} ban đầu!`;

  return scriptText;
}

function generateMortgageReportText(calc) {
  const c = calc || lastMortgageCalculationResult || calculateMortgage();
  const dateStr = new Date().toLocaleDateString('vi-VN');

  let text = `=========================================\n`;
  text += `💰 BẢNG TÍNH KẾ HOẠCH LÃI VAY & DÒNG TIỀN ĐẦU TƯ BĐS\n`;
  text += `Hệ thống: CONTENT SO DO — Financial Advisory Suite\n`;
  text += `Ngày lập: ${dateStr}\n`;
  text += `=========================================\n\n`;

  text += `1. THÔNG SỐ TỔNG QUAN BẤT ĐỘNG SẢN:\n`;
  text += `• Tổng giá trị BĐS: ${formatMoneyVietnamese(c.totalPrice)} (${c.totalPrice.toLocaleString('vi-VN')} đ)\n`;
  text += `• Doanh thu cho thuê: ${(c.monthlyRent / 1000000).toFixed(1)} Triệu/tháng (${c.monthlyRent.toLocaleString('vi-VN')} đ/tháng)\n`;
  text += `• Tỷ suất cho thuê (Gross Yield): ${c.grossYield}%/năm\n\n`;

  text += `2. CẤU TRÚC GÓI VAY & NGUỒN VỐN:\n`;
  text += `• Tỷ lệ vay ngân hàng: ${c.loanPercent}% (${c.loanAmount.toLocaleString('vi-VN')} đ)\n`;
  text += `• Vốn tự có cần chuẩn bị: ${100 - c.loanPercent}% (${c.equityAmount.toLocaleString('vi-VN')} đ)\n`;
  text += `• Thời hạn vay: ${c.loanYears} Năm (${c.totalMonths} tháng)\n`;
  text += `• Lãi suất ưu đãi: ${c.preferRate}%/năm trong ${c.preferMonths} tháng đầu\n`;
  text += `• Lãi suất thả nổi dự kiến: ${c.floatingRate}%/năm\n`;
  text += `• Phương thức trả nợ: ${c.method === 'annuity' ? 'Niên kim cố định' : 'Dư nợ giảm dần'}\n\n`;

  text += `3. NGHĨA VỤ TRẢ NỢ HÀNG THÁNG:\n`;
  text += `• Tháng đầu tiên (Cao nhất): ${c.firstMonthPayment.toLocaleString('vi-VN')} đ (Gốc: ${c.firstMonthPrincipal.toLocaleString('vi-VN')} đ + Lãi: ${c.firstMonthInterest.toLocaleString('vi-VN')} đ)\n`;
  text += `• Tháng cuối cùng: ${c.lastMonthPayment.toLocaleString('vi-VN')} đ\n`;
  text += `• Tổng lãi phải trả toàn kỳ: ${(c.totalInterest / 1000000000).toFixed(2)} Tỷ (${c.totalInterest.toLocaleString('vi-VN')} đ)\n`;
  text += `• Tổng gốc + lãi trả ngân hàng: ${(c.totalPaymentAll / 1000000000).toFixed(2)} Tỷ (${c.totalPaymentAll.toLocaleString('vi-VN')} đ)\n`;
  text += `• Thu nhập chứng minh đề xuất: ≥ ${Math.ceil(c.minRequiredIncome / 1000000)} Triệu/tháng\n\n`;

  text += `4. BÀI TOÁN BÙ ĐẮP DÒNG TIỀN (CASHFLOW):\n`;
  text += `• Doanh thu thuê ròng: +${(c.netMonthlyRent / 1000000).toFixed(1)} Triệu/tháng\n`;
  if (c.isPositiveCashflow) {
    text += `• ĐÁNH GIÁ: Dòng tiền dương ròng +${(c.firstMonthGap / 1000000).toFixed(2)} Triệu/tháng! BĐS tự nuôi chính nó.\n\n`;
  } else {
    text += `• ĐÁNH GIÁ: Mỗi tháng chỉ cần bù thêm: ${(c.monthlyTopUp / 1000000).toFixed(2)} Triệu/tháng (Người thuê gánh ${c.rentCoveragePercent}% nợ ngân hàng).\n\n`;
  }

  text += `5. DỰ PHÓNG TÀI SẢN 5 NĂM (TĂNG GIÁ ${c.appreciationRate}%/NĂM):\n`;
  text += `• Giá trị căn nhà sau 5 năm: ${(c.propertyValueAt5Y / 1000000000).toFixed(2)} Tỷ\n`;
  text += `• Dư nợ ngân hàng còn lại: ${(c.remainingAt5Y / 1000000000).toFixed(2)} Tỷ\n`;
  text += `• TÀI SẢN RÒNG THỰC TẾ (NET EQUITY): ${(c.netEquityAt5Y / 1000000000).toFixed(2)} Tỷ\n`;
  text += `• Lãi vốn ròng tích lũy: +${(c.capitalGainAt5Y / 1000000000).toFixed(2)} Tỷ\n\n`;

  text += `=========================================\n`;
  text += `📌 LỜI KHUYÊN CỐ VẤN TÀI CHÍNH:\n`;
  text += generateMortgageAdvisorScript(c) + `\n`;
  return text;
}

function openMortgageCalculatorModal(source = '') {
  const ws = document.getElementById('subsystemMortgageWorkspace');
  if (ws && ws.style.display !== 'flex' && typeof switchSubsystem === 'function') {
    switchSubsystem('mortgage');
  }
  const modal = document.getElementById('mortgageCalculatorModal');
  if (!modal) return;
  modal.style.display = 'flex';
  modal.classList.add('open');

  // Auto-sync current property data if price input is default or empty
  if (typeof AppState !== 'undefined' && AppState.currentPropertyData) {
    const rawPrice = AppState.currentPropertyData.gia_chuan || AppState.currentPropertyData.gia_ban;
    if (rawPrice) {
      parseAndSetMortgagePrice(rawPrice);
    }
  }

  recalculateMortgageAndRender();
}

function closeMortgageCalculatorModal() {
  const modal = document.getElementById('mortgageCalculatorModal');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('open');
  }
  const ws = document.getElementById('subsystemMortgageWorkspace');
  if (ws) ws.style.display = 'none';
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('dashboard');
  }
}

function parseAndSetMortgagePrice(str) {
  if (!str) return;
  let text = String(str).toLowerCase().trim();
  let price = 0;
  if (text.includes('tỷ')) {
    const num = parseFloat(text.replace(/[^0-9.]/g, ''));
    if (!isNaN(num)) price = Math.round(num * 1000000000);
  } else if (text.includes('triệu')) {
    const num = parseFloat(text.replace(/[^0-9.]/g, ''));
    if (!isNaN(num)) price = Math.round(num * 1000000);
  } else {
    const num = parseFloat(text.replace(/[^0-9]/g, ''));
    if (!isNaN(num)) price = num;
  }

  if (price > 0) {
    const priceInput = document.getElementById('mortgageInputPrice');
    if (priceInput) priceInput.value = price;
  }
}

function loadCurrentPropertyIntoMortgage() {
  let loaded = false;
  if (typeof AppState !== 'undefined' && AppState.currentPropertyData) {
    const p = AppState.currentPropertyData;
    const price = p.gia_chuan || p.gia_ban;
    if (price) {
      parseAndSetMortgagePrice(price);
      loaded = true;
    }
    // Check if there is rent info in facts
    if (p.facts && Array.isArray(p.facts)) {
      const rentFact = p.facts.find(f => f.toLowerCase().includes('thuê') || f.toLowerCase().includes('dòng tiền'));
      if (rentFact) {
        const num = parseFloat(rentFact.replace(/[^0-9.]/g, ''));
        if (!isNaN(num) && num > 0) {
          const rentInput = document.getElementById('mortgageInputRent');
          if (rentInput) rentInput.value = (num < 1000 ? num * 1000000 : num);
        }
      }
    }
  }

  recalculateMortgageAndRender();

  if (typeof showToast === 'function') {
    if (loaded) {
      showToast('🔄 Đã nạp giá trị căn nhà hiện tại vào bảng tính!', '✅');
    } else {
      showToast('ℹ️ Đã kiểm tra giỏ hàng hiện tại!', 'ℹ️');
    }
  }
}

function copyMortgageReport() {
  const text = generateMortgageReportText(lastMortgageCalculationResult);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép kế hoạch tài chính vào clipboard!', '✅');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function copyMortgageAdvisorScript() {
  const text = generateMortgageAdvisorScript(lastMortgageCalculationResult);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép lời thoại cố vấn vào clipboard!', '✅');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function injectMortgageIntoCopywriting() {
  const advisorScript = generateMortgageAdvisorScript(lastMortgageCalculationResult);
  
  // Look for target in copywriting workspace
  const copyOutput = document.getElementById('copywritingOutputText');
  const manualRawInput = document.getElementById('rawPropertyInput');

  let injected = false;
  if (copyOutput && copyOutput.value !== undefined) {
    copyOutput.value += '\n\n' + advisorScript;
    injected = true;
  } else if (copyOutput && copyOutput.innerText !== undefined) {
    copyOutput.innerText += '\n\n' + advisorScript;
    injected = true;
  }

  closeMortgageCalculatorModal();

  // Switch to copywriting subsystem
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('copywriting');
  }

  if (typeof showToast === 'function') {
    showToast('⚡ Đã chèn bài toán đòn bẩy tài chính vào bài viết Phân Hệ 02!', '🎯');
  }
}

function printMortgagePlan() {
  const reportText = generateMortgageReportText(lastMortgageCalculationResult);
  const printModal = document.getElementById('printReportModal');
  const printBody = document.getElementById('printReportModalBody');

  if (printModal && printBody) {
    printBody.innerHTML = `<div style="font-family: monospace; font-size: 0.9rem; white-space: pre-wrap; line-height: 1.6; color: #000; background: #fff; padding: 1.5rem; border: 1px solid #ddd; border-radius: 6px;">${reportText}</div>`;
    closeMortgageCalculatorModal();
    printModal.style.display = 'flex';
  } else {
    window.print();
  }
}


// =============================================================================
// BỘ CÔNG CỤ ĐỊNH GIÁ BẤT ĐỘNG SẢN CHUYÊN NGHIỆP (REAL ESTATE VALUATION SUITE)
// =============================================================================
let currentValuationTab = 'cost'; // 'cost' | 'compare' | 'income'
let currentValuationScriptTab = 'owner'; // 'owner' | 'buyer'
let lastValuationResult = null;

function calculateValuationCostMethod(params = {}) {
  const askingPrice = Math.max(0, parseFloat(params.askingPrice) || 8500000000);
  const landArea = Math.max(1, parseFloat(params.landArea) || 68);
  const baseLandPrice = Math.max(0, (parseFloat(params.baseLandPrice) || 110) * 1000000); // Tr to VND
  const alleyFactor = Math.max(0.1, parseFloat(params.alleyFactor) || 0.75);
  const shapeFactor = Math.max(0.1, parseFloat(params.shapeFactor) || 1.05);

  const floorArea = Math.max(0, parseFloat(params.floorArea) || 210);
  const constructionPricePerM2 = Math.max(0, (parseFloat(params.constructionPricePerM2) || 7.5) * 1000000); // Tr to VND
  const buildingQualityPercent = Math.min(100, Math.max(0, parseFloat(params.buildingQualityPercent) || 85));

  // 1. Land Value Calculation
  const adjustedLandUnitPrice = Math.round(baseLandPrice * alleyFactor * shapeFactor);
  const totalLandValue = Math.round(landArea * adjustedLandUnitPrice);

  // 2. Building Value Calculation
  const newBuildingValue = Math.round(floorArea * constructionPricePerM2);
  const totalBuildingValue = Math.round(newBuildingValue * (buildingQualityPercent / 100));

  // 3. Total Appraised Value
  const totalAppraisedValue = totalLandValue + totalBuildingValue;
  const appraisedPricePerM2Land = Math.round(totalAppraisedValue / landArea);

  // 4. Comparison with Asking Price
  const priceDiff = askingPrice - totalAppraisedValue;
  const diffPercent = totalAppraisedValue > 0 ? parseFloat(((priceDiff / totalAppraisedValue) * 100).toFixed(1)) : 0;

  let marketStatus = 'fair';
  let statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';

  if (diffPercent <= -10) {
    marketStatus = 'bargain';
    statusLabel = 'GIÁ NGỘP RẺ (Dưới Thị Trường >10%)';
  } else if (diffPercent <= 5) {
    marketStatus = 'fair';
    statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';
  } else if (diffPercent <= 15) {
    marketStatus = 'high';
    statusLabel = 'GIÁ HƠI CAO (+5% đến +15%)';
  } else {
    marketStatus = 'overpriced';
    statusLabel = 'GIÁ ẢO TƯỞNG (Cao Hơn Thị Trường >15%)';
  }

  // Recommended Buying Zone
  const buyZoneMin = Math.round(totalAppraisedValue * 0.92);
  const buyZoneTarget = Math.round(totalAppraisedValue * 0.97);
  const buyZoneMax = totalAppraisedValue;

  return {
    method: 'cost',
    methodName: 'Tách Đất & Nhà (Chi Phí Khấu Hao)',
    askingPrice,
    landArea,
    baseLandPrice,
    alleyFactor,
    shapeFactor,
    adjustedLandUnitPrice,
    totalLandValue,
    floorArea,
    constructionPricePerM2,
    buildingQualityPercent,
    totalBuildingValue,
    totalAppraisedValue,
    appraisedPricePerM2Land,
    priceDiff,
    diffPercent,
    marketStatus,
    statusLabel,
    buyZoneMin,
    buyZoneTarget,
    buyZoneMax
  };
}

function calculateValuationCompareMethod(params = {}) {
  const askingPrice = Math.max(0, parseFloat(params.askingPrice) || 8500000000);
  const landArea = Math.max(1, parseFloat(params.landArea) || 68);

  const p1 = (parseFloat(params.compPrice1) || 7.5) * 1000000000;
  const a1 = Math.max(1, parseFloat(params.compArea1) || 70);

  const p2 = (parseFloat(params.compPrice2) || 6.8) * 1000000000;
  const a2 = Math.max(1, parseFloat(params.compArea2) || 64);

  const p3 = (parseFloat(params.compPrice3) || 8.0) * 1000000000;
  const a3 = Math.max(1, parseFloat(params.compArea3) || 76);

  const unit1 = p1 / a1;
  const unit2 = p2 / a2;
  const unit3 = p3 / a3;

  const avgUnitPrice = Math.round((unit1 + unit2 + unit3) / 3);
  const totalAppraisedValue = Math.round(landArea * avgUnitPrice);
  const priceDiff = askingPrice - totalAppraisedValue;
  const diffPercent = totalAppraisedValue > 0 ? parseFloat(((priceDiff / totalAppraisedValue) * 100).toFixed(1)) : 0;

  let marketStatus = 'fair';
  let statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';
  if (diffPercent <= -10) {
    marketStatus = 'bargain';
    statusLabel = 'GIÁ NGỘP RẺ (Dưới Thị Trường >10%)';
  } else if (diffPercent <= 5) {
    marketStatus = 'fair';
    statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';
  } else if (diffPercent <= 15) {
    marketStatus = 'high';
    statusLabel = 'GIÁ HƠI CAO (+5% đến +15%)';
  } else {
    marketStatus = 'overpriced';
    statusLabel = 'GIÁ ẢO TƯỞNG (Cao Hơn Thị Trường >15%)';
  }

  return {
    method: 'compare',
    methodName: 'So Sánh 3 BĐS Tương Đồng',
    askingPrice,
    landArea,
    avgUnitPrice,
    totalLandValue: totalAppraisedValue,
    totalBuildingValue: 0,
    totalAppraisedValue,
    appraisedPricePerM2Land: avgUnitPrice,
    priceDiff,
    diffPercent,
    marketStatus,
    statusLabel,
    buyZoneMin: Math.round(totalAppraisedValue * 0.93),
    buyZoneTarget: Math.round(totalAppraisedValue * 0.98),
    buyZoneMax: totalAppraisedValue
  };
}

function calculateValuationIncomeMethod(params = {}) {
  const askingPrice = Math.max(0, parseFloat(params.askingPrice) || 8500000000);
  const landArea = Math.max(1, parseFloat(params.landArea) || 68);
  const monthlyRent = Math.max(0, parseFloat(params.monthlyRent) || 25000000);
  const costPercent = Math.min(50, Math.max(0, parseFloat(params.costPercent) || 10));
  const capRate = Math.max(0.5, parseFloat(params.capRate) || 3.8);

  const annualGrossRent = monthlyRent * 12;
  const annualNetRent = annualGrossRent * (1 - costPercent / 100);
  const totalAppraisedValue = Math.round(annualNetRent / (capRate / 100));

  const priceDiff = askingPrice - totalAppraisedValue;
  const diffPercent = totalAppraisedValue > 0 ? parseFloat(((priceDiff / totalAppraisedValue) * 100).toFixed(1)) : 0;

  let marketStatus = 'fair';
  let statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';
  if (diffPercent <= -10) {
    marketStatus = 'bargain';
    statusLabel = 'GIÁ NGỘP RẺ (Dưới Thị Trường >10%)';
  } else if (diffPercent <= 5) {
    marketStatus = 'fair';
    statusLabel = 'HỢP LÝ (Đúng Giá Thị Trường)';
  } else if (diffPercent <= 15) {
    marketStatus = 'high';
    statusLabel = 'GIÁ HƠI CAO (+5% đến +15%)';
  } else {
    marketStatus = 'overpriced';
    statusLabel = 'GIÁ ẢO TƯỞNG (Cao Hơn Thị Trường >15%)';
  }

  return {
    method: 'income',
    methodName: 'Dòng Tiền Thu Nhập (Cap Rate)',
    askingPrice,
    landArea,
    monthlyRent,
    annualNetRent,
    capRate,
    totalLandValue: Math.round(totalAppraisedValue * 0.8),
    totalBuildingValue: Math.round(totalAppraisedValue * 0.2),
    totalAppraisedValue,
    appraisedPricePerM2Land: Math.round(totalAppraisedValue / landArea),
    priceDiff,
    diffPercent,
    marketStatus,
    statusLabel,
    buyZoneMin: Math.round(totalAppraisedValue * 0.92),
    buyZoneTarget: Math.round(totalAppraisedValue * 0.97),
    buyZoneMax: totalAppraisedValue
  };
}

function getValuationInputs() {
  const askInput = document.getElementById('valInputAskingPrice');
  const landAreaInput = document.getElementById('valInputLandArea');
  const baseLandInput = document.getElementById('valInputBaseLandPrice');
  const alleySelect = document.getElementById('valSelectAlleyFactor');
  const shapeSelect = document.getElementById('valSelectShapeFactor');

  const floorAreaInput = document.getElementById('valInputFloorArea');
  const constructPriceInput = document.getElementById('valInputConstructPrice');
  const qualitySelect = document.getElementById('valSelectQualityPercent');

  // Compare inputs
  const compPrice1 = document.getElementById('valCompPrice1');
  const compArea1 = document.getElementById('valCompArea1');
  const compPrice2 = document.getElementById('valCompPrice2');
  const compArea2 = document.getElementById('valCompArea2');
  const compPrice3 = document.getElementById('valCompPrice3');
  const compArea3 = document.getElementById('valCompArea3');

  // Income inputs
  const rentInput = document.getElementById('valIncomeRent');
  const costInput = document.getElementById('valIncomeCost');
  const capRateInput = document.getElementById('valIncomeCapRate');

  return {
    askingPrice: askInput ? parseFloat(askInput.value) || 8500000000 : 8500000000,
    landArea: landAreaInput ? parseFloat(landAreaInput.value) || 68 : 68,
    baseLandPrice: baseLandInput ? parseFloat(baseLandInput.value) || 110 : 110,
    alleyFactor: alleySelect ? parseFloat(alleySelect.value) || 0.75 : 0.75,
    shapeFactor: shapeSelect ? parseFloat(shapeSelect.value) || 1.05 : 1.05,
    floorArea: floorAreaInput ? parseFloat(floorAreaInput.value) || 210 : 210,
    constructionPricePerM2: constructPriceInput ? parseFloat(constructPriceInput.value) || 7.5 : 7.5,
    buildingQualityPercent: qualitySelect ? parseFloat(qualitySelect.value) || 85 : 85,
    // Compare
    compPrice1: compPrice1 ? parseFloat(compPrice1.value) || 7.5 : 7.5,
    compArea1: compArea1 ? parseFloat(compArea1.value) || 70 : 70,
    compPrice2: compPrice2 ? parseFloat(compPrice2.value) || 6.8 : 6.8,
    compArea2: compArea2 ? parseFloat(compArea2.value) || 64 : 64,
    compPrice3: compPrice3 ? parseFloat(compPrice3.value) || 8.0 : 8.0,
    compArea3: compArea3 ? parseFloat(compArea3.value) || 76 : 76,
    // Income
    monthlyRent: rentInput ? parseFloat(rentInput.value) || 25000000 : 25000000,
    costPercent: costInput ? parseFloat(costInput.value) || 10 : 10,
    capRate: capRateInput ? parseFloat(capRateInput.value) || 3.8 : 3.8
  };
}

function onValuationInputChanged() {
  recalculateValuationAndRender();
}

function switchValuationTab(tabKey) {
  currentValuationTab = tabKey;
  const btnCost = document.getElementById('btnValuationTabCost');
  const btnCompare = document.getElementById('btnValuationTabCompare');
  const btnIncome = document.getElementById('btnValuationTabIncome');

  const paneCost = document.getElementById('valuationPaneCost');
  const paneCompare = document.getElementById('valuationPaneCompare');
  const paneIncome = document.getElementById('valuationPaneIncome');

  if (btnCost) btnCost.classList.remove('active');
  if (btnCompare) btnCompare.classList.remove('active');
  if (btnIncome) btnIncome.classList.remove('active');

  if (paneCost) paneCost.style.display = 'none';
  if (paneCompare) paneCompare.style.display = 'none';
  if (paneIncome) paneIncome.style.display = 'none';

  if (tabKey === 'compare') {
    if (btnCompare) btnCompare.classList.add('active');
    if (paneCompare) paneCompare.style.display = 'flex';
  } else if (tabKey === 'income') {
    if (btnIncome) btnIncome.classList.add('active');
    if (paneIncome) paneIncome.style.display = 'flex';
  } else {
    if (btnCost) btnCost.classList.add('active');
    if (paneCost) paneCost.style.display = 'flex';
  }

  recalculateValuationAndRender();
}

function switchValuationScript(scriptKey) {
  currentValuationScriptTab = scriptKey;
  const btnOwner = document.getElementById('btnValScriptOwner');
  const btnBuyer = document.getElementById('btnValScriptBuyer');

  if (btnOwner) {
    if (scriptKey === 'owner') btnOwner.classList.add('active');
    else btnOwner.classList.remove('active');
  }
  if (btnBuyer) {
    if (scriptKey === 'buyer') btnBuyer.classList.add('active');
    else btnBuyer.classList.remove('active');
  }

  if (lastValuationResult) {
    const scriptBox = document.getElementById('valScriptContent');
    if (scriptBox) {
      scriptBox.textContent = generateValuationScript(lastValuationResult, scriptKey);
    }
  }
}

function recalculateValuationAndRender() {
  const inputs = getValuationInputs();
  let res;

  if (currentValuationTab === 'compare') {
    res = calculateValuationCompareMethod(inputs);
  } else if (currentValuationTab === 'income') {
    res = calculateValuationIncomeMethod(inputs);
  } else {
    res = calculateValuationCostMethod(inputs);
  }

  lastValuationResult = res;

  // 1. Update In-Words & Badges
  const askWords = document.getElementById('valAskingPriceWords');
  if (askWords) askWords.textContent = formatMoneyVietnamese(res.askingPrice);

  const landBadge = document.getElementById('valLandValueBadge');
  if (landBadge) landBadge.textContent = formatMoneyVietnamese(res.totalLandValue);

  const bldBadge = document.getElementById('valBuildingValueBadge');
  if (bldBadge) bldBadge.textContent = formatMoneyVietnamese(res.totalBuildingValue);

  // 2. Thermometer Banner
  const thermBox = document.getElementById('valThermometerBox');
  const thermBadge = document.getElementById('valThermometerBadge');
  const diffNum = document.getElementById('valDiffNum');
  const thermDesc = document.getElementById('valThermometerDesc');

  if (thermBox && thermBadge && diffNum && thermDesc) {
    thermBox.className = `valuation-thermometer-box ${res.marketStatus}`;
    thermBadge.textContent = res.statusLabel;

    const sign = res.priceDiff > 0 ? '+' : '';
    diffNum.textContent = `${sign}${formatMoneyVietnamese(res.priceDiff)} (${sign}${res.diffPercent}%)`;

    if (res.marketStatus === 'bargain') {
      thermDesc.innerHTML = `Giá chủ chào bán thấp hơn giá trị thẩm định thực tế <strong>${formatMoneyVietnamese(Math.abs(res.priceDiff))} (-${Math.abs(res.diffPercent)}%)</strong>. Đây là bất động sản <strong>GIÁ NGỘP RẺ / CỰC KỲ HỜI</strong>, biên độ an toàn vốn cực cao, cần thúc đẩy khách mua cọc ngay!`;
    } else if (res.marketStatus === 'fair') {
      thermDesc.innerHTML = `Giá chủ chào bán chênh lệch ${sign}${res.diffPercent}% so với giá định giá thực tế. Mức giá này <strong>HỢP LÝ & ĐÚNG MẶT BẰNG THỊ TRƯỜNG</strong>, tính thanh khoản tốt, có thể thương lượng nhẹ bớt lộc khi vào việc.`;
    } else if (res.marketStatus === 'high') {
      thermDesc.innerHTML = `Giá chào bán đang cao hơn giá trị thực tế <strong>${formatMoneyVietnamese(res.priceDiff)} (+${res.diffPercent}%)</strong>. Chủ nhà đang neo giá theo kỳ vọng, môi giới cần lập hồ sơ để đàm phán kéo giá về vùng thanh khoản.`;
    } else {
      thermDesc.innerHTML = `Giá chào bán cao hơn giá trị thực tế tới <strong>${formatMoneyVietnamese(res.priceDiff)} (+${res.diffPercent}%)</strong>. Đây là mức giá <strong>ẢO TƯỞNG / KHÓ BÁN</strong>, nguy cơ đóng băng nguồn hàng rất cao nếu không làm việc lại với Đầu Chủ.`;
    }
  }

  // 3. Stats Grid
  const statTotal = document.getElementById('valStatTotal');
  if (statTotal) statTotal.textContent = formatMoneyVietnamese(res.totalAppraisedValue);

  const statTotalSub = document.getElementById('valStatTotalSub');
  if (statTotalSub) statTotalSub.textContent = `Đơn giá: ~${(res.appraisedPricePerM2Land / 1000000).toFixed(1)} Tr/m² đất`;

  const statLand = document.getElementById('valStatLand');
  if (statLand) statLand.textContent = formatMoneyVietnamese(res.totalLandValue);

  const statLandSub = document.getElementById('valStatLandSub');
  if (statLandSub) statLandSub.textContent = `Đơn giá đất: ~${(res.adjustedLandUnitPrice / 1000000).toFixed(1)} Tr/m²`;

  const statBld = document.getElementById('valStatBuilding');
  if (statBld) statBld.textContent = formatMoneyVietnamese(res.totalBuildingValue);

  const statBldSub = document.getElementById('valStatBuildingSub');
  if (statBldSub) statBldSub.textContent = `DTSXD: ${res.floorArea} m² (${res.buildingQualityPercent}% mới)`;

  // 4. Target Buying Zone
  const zoneMin = document.getElementById('valZoneMin');
  if (zoneMin) zoneMin.textContent = `${formatMoneyVietnamese(res.buyZoneMin)} - ${formatMoneyVietnamese(res.buyZoneTarget)}`;

  const zoneMax = document.getElementById('valZoneMax');
  if (zoneMax) zoneMax.textContent = formatMoneyVietnamese(res.buyZoneMax);

  // 5. Script
  const scriptBox = document.getElementById('valScriptContent');
  if (scriptBox) {
    scriptBox.textContent = generateValuationScript(res, currentValuationScriptTab);
  }
}

function generateValuationScript(res, type = 'owner') {
  if (!res) return '';
  const askingStr = formatMoneyVietnamese(res.askingPrice);
  const appraisedStr = formatMoneyVietnamese(res.totalAppraisedValue);
  const landStr = formatMoneyVietnamese(res.totalLandValue);
  const bldStr = formatMoneyVietnamese(res.totalBuildingValue);
  const targetStr = formatMoneyVietnamese(res.buyZoneTarget);

  if (type === 'owner') {
    if (res.marketStatus === 'overpriced' || res.marketStatus === 'high') {
      return `🗣️ KỊCH BẢN THOẠI ĐÀM PHÁN ÉP GIÁ VỚI CHỦ NHÀ:\n"Dạ anh/chị chủ, em đã làm việc với bộ phận định giá và tra cứu ngân hàng kỹ lưỡng. Đất khu mình đơn giá thực tế khoảng ${(res.adjustedLandUnitPrice / 1000000).toFixed(1)} tr/m² (${landStr}), cộng xác nhà kiên cố ${bldStr}, tổng giá trị định giá thực của căn nhà mình là ${appraisedStr}. Hiện giá anh/chị đang chào ${askingStr} đang cao hơn thị trường khoảng ${formatMoneyVietnamese(res.priceDiff)} (+${res.diffPercent}%). Em khuyên thật lòng, nếu anh/chị muốn thanh khoản nhanh trước mùa mưa/cuối năm, mình nên cân đối hạ về khoảng ${targetStr}, em cam kết sẽ tập trung dồn khách nét vào chốt deal ngay cho mình ạ!"`;
    } else {
      return `🗣️ KỊCH BẢN THOẠI LÀM VIỆC VỚI CHỦ NHÀ:\n"Dạ anh/chị chủ, giá chào ${askingStr} của mình rất hợp lý và sát với thẩm định thị trường (${appraisedStr}). Em đã nắm toàn bộ ưu thế sổ và hiện trạng, em sẽ đẩy mạnh truyền thông đa kênh để tìm đúng khách có tài chính sẵn sàng vào tiền chốt sớm cho anh/chị!"`;
    }
  } else {
    // Buyer
    if (res.marketStatus === 'bargain') {
      return `🗣️ KỊCH BẢN THOẠI TƯ VẤN KHÁCH MUA CHỐT CỌC GẤP:\n"Anh/chị ơi, căn này em vừa chạy thẩm định giá chi tiết: Tiền đất khu này đã là ${landStr}, tiền xây nhà kiên cố hoàn công ${bldStr}, tổng giá trị thực tế tối thiểu ${appraisedStr}. Chủ nhà đang kẹt dòng tiền nên bán gấp chỉ ${askingStr}, rẻ hơn thị trường tới ${formatMoneyVietnamese(Math.abs(res.priceDiff))}! Anh/chị mua là nắm chắc phần lời ngay trong tay. Căn này hàng hiếm phân khúc, em khuyên anh/chị chuẩn bị tiền cọc ngay hôm nay kẻo người khác cọc mất ạ!"`;
    } else {
      return `🗣️ KỊCH BẢN THOẠI TƯ VẤN KHÁCH MUA ĐÀM PHÁN:\n"Dạ anh/chị, căn này qua thẩm định chuyên sâu của bên em, giá trị thực tế rơi vào khoảng ${appraisedStr}. Chủ đang kêu ${askingStr}. Em đã chuẩn bị sẵn bảng bóc tách đất và chi phí nhà để hỗ trợ anh/chị thương lượng về vùng giá đẹp khoảng ${targetStr}. Anh/chị chốt phương án để em trực tiếp ngồi làm việc với chủ ép giá tốt nhất cho mình nhé!"`;
    }
  }
}

function generateValuationReportText(res) {
  const r = res || lastValuationResult || calculateValuationCostMethod();
  const dateStr = new Date().toLocaleDateString('vi-VN');

  let text = `=========================================\n`;
  text += `💎 BÁO CÁO THẨM ĐỊNH GIÁ TRỊ BẤT ĐỘNG SẢN\n`;
  text += `Phương pháp: ${r.methodName}\n`;
  text += `Ngày thực hiện: ${dateStr}\n`;
  text += `=========================================\n\n`;

  text += `1. THÔNG SỐ BẤT ĐỘNG SẢN & GIÁ CHÀO BÁN:\n`;
  text += `• Giá chủ đang chào bán: ${formatMoneyVietnamese(r.askingPrice)} (${r.askingPrice.toLocaleString('vi-VN')} đ)\n`;
  text += `• Diện tích đất công nhận: ${r.landArea} m²\n`;
  if (r.floorArea) text += `• Diện tích sàn xây dựng (DTSXD): ${r.floorArea} m²\n`;
  text += `\n`;

  text += `2. KẾT QUẢ THẨM ĐỊNH GIÁ TRỊ THỰC:\n`;
  text += `• TỔNG GIÁ TRỊ ĐỊNH GIÁ: ${formatMoneyVietnamese(r.totalAppraisedValue)} (${r.totalAppraisedValue.toLocaleString('vi-VN')} đ)\n`;
  if (r.totalLandValue) text += `  - Giá trị Quyền sử dụng Đất: ${formatMoneyVietnamese(r.totalLandValue)} (~${(r.adjustedLandUnitPrice / 1000000).toFixed(1)} Tr/m²)\n`;
  if (r.totalBuildingValue) text += `  - Giá trị Công trình Nhà: ${formatMoneyVietnamese(r.totalBuildingValue)} (${r.buildingQualityPercent}% chất lượng còn lại)\n`;
  text += `• Đơn giá đất toàn bộ sau định giá: ~${(r.appraisedPricePerM2Land / 1000000).toFixed(1)} Tr/m²\n\n`;

  text += `3. SO SÁNH ĐỘ LỆCH GIÁ & ĐÁNH GIÁ NHIỆT KẾ:\n`;
  const sign = r.priceDiff > 0 ? '+' : '';
  text += `• Chênh lệch giá (Giá chào - Định giá): ${sign}${formatMoneyVietnamese(r.priceDiff)} (${sign}${r.diffPercent}%)\n`;
  text += `• NHẬN ĐỊNH: ${r.statusLabel}\n\n`;

  text += `4. VÙNG GIÁ MUA KHUYÊN NGHỊ (TARGET BUYING ZONE):\n`;
  text += `• Vùng giá hời nên đàm phán: ${formatMoneyVietnamese(r.buyZoneMin)} - ${formatMoneyVietnamese(r.buyZoneTarget)}\n`;
  text += `• Giá trần tối đa nên mua: ${formatMoneyVietnamese(r.buyZoneMax)}\n\n`;

  text += `5. LỜI KHUYÊN CHIẾN THUẬT ĐÀM PHÁN:\n`;
  text += generateValuationScript(r, 'owner') + `\n\n`;
  text += generateValuationScript(r, 'buyer') + `\n`;
  return text;
}

function openValuationModal(source = '') {
  const ws = document.getElementById('subsystemValuationWorkspace');
  if (ws && ws.style.display !== 'flex' && typeof switchSubsystem === 'function') {
    switchSubsystem('valuation');
  }
  const modal = document.getElementById('propertyValuationModal');
  if (!modal) return;
  modal.style.display = 'flex';
  modal.classList.add('open');

  // Auto-sync current property data
  if (typeof AppState !== 'undefined' && AppState.currentPropertyData) {
    const p = AppState.currentPropertyData;
    const askPrice = p.gia_chuan || p.gia_ban;
    if (askPrice) {
      parseAndSetValuationPrice(askPrice);
    }
    if (p.dien_tich) {
      const areaInput = document.getElementById('valInputLandArea');
      const num = parseFloat(String(p.dien_tich).replace(/[^0-9.]/g, ''));
      if (areaInput && !isNaN(num) && num > 0) areaInput.value = num;
    }
  }

  recalculateValuationAndRender();
}

function closeValuationModal() {
  const modal = document.getElementById('propertyValuationModal');
  if (modal) {
    modal.style.display = 'none';
    modal.classList.remove('open');
  }
  const ws = document.getElementById('subsystemValuationWorkspace');
  if (ws) ws.style.display = 'none';
  if (typeof switchSubsystem === 'function') {
    switchSubsystem('dashboard');
  }
}

function parseAndSetValuationPrice(str) {
  if (!str) return;
  let text = String(str).toLowerCase().trim();
  let price = 0;
  if (text.includes('tỷ')) {
    const num = parseFloat(text.replace(/[^0-9.]/g, ''));
    if (!isNaN(num)) price = Math.round(num * 1000000000);
  } else if (text.includes('triệu')) {
    const num = parseFloat(text.replace(/[^0-9.]/g, ''));
    if (!isNaN(num)) price = Math.round(num * 1000000);
  } else {
    const num = parseFloat(text.replace(/[^0-9]/g, ''));
    if (!isNaN(num)) price = num;
  }

  if (price > 0) {
    const priceInput = document.getElementById('valInputAskingPrice');
    if (priceInput) priceInput.value = price;
  }
}

function loadCurrentPropertyIntoValuation() {
  let loaded = false;
  if (typeof AppState !== 'undefined' && AppState.currentPropertyData) {
    const p = AppState.currentPropertyData;
    const askPrice = p.gia_chuan || p.gia_ban;
    if (askPrice) {
      parseAndSetValuationPrice(askPrice);
      loaded = true;
    }
    if (p.dien_tich) {
      const areaInput = document.getElementById('valInputLandArea');
      const num = parseFloat(String(p.dien_tich).replace(/[^0-9.]/g, ''));
      if (areaInput && !isNaN(num) && num > 0) {
        areaInput.value = num;
        loaded = true;
      }
    }
    // Check if there is rent info
    if (p.facts && Array.isArray(p.facts)) {
      const rentFact = p.facts.find(f => f.toLowerCase().includes('thuê') || f.toLowerCase().includes('dòng tiền'));
      if (rentFact) {
        const num = parseFloat(rentFact.replace(/[^0-9.]/g, ''));
        if (!isNaN(num) && num > 0) {
          const rentInput = document.getElementById('valIncomeRent');
          if (rentInput) rentInput.value = (num < 1000 ? num * 1000000 : num);
        }
      }
    }
  }

  recalculateValuationAndRender();

  if (typeof showToast === 'function') {
    if (loaded) {
      showToast('🔄 Đã nạp thông số căn nhà hiện tại vào bảng định giá!', '✅');
    } else {
      showToast('ℹ️ Đã kiểm tra giỏ hàng hiện tại!', 'ℹ️');
    }
  }
}

function copyValuationReport() {
  const text = generateValuationReportText(lastValuationResult);
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(() => {
      if (typeof showToast === 'function') {
        showToast('📋 Đã sao chép báo cáo thẩm định giá vào clipboard!', '✅');
      }
    }).catch(() => fallbackCopyText(text));
  } else {
    fallbackCopyText(text);
  }
}

function sendValuationToMortgage() {
  const res = lastValuationResult || calculateValuationCostMethod();
  const priceInput = document.getElementById('mortgageInputPrice');
  if (priceInput) {
    priceInput.value = res.totalAppraisedValue;
  }
  closeValuationModal();
  openMortgageCalculatorModal();

  if (typeof showToast === 'function') {
    showToast(`💰 Đã chuyển mức định giá ${formatMoneyVietnamese(res.totalAppraisedValue)} sang Bảng tính Lãi Vay!`, '🎯');
  }
}

function injectValuationIntoCopywriting() {
  const res = lastValuationResult || calculateValuationCostMethod();
  const scriptText = generateValuationScript(res, 'buyer');

  const copyOutput = document.getElementById('copywritingOutputText');
  if (copyOutput && copyOutput.value !== undefined) {
    copyOutput.value += '\n\n' + scriptText;
  } else if (copyOutput && copyOutput.innerText !== undefined) {
    copyOutput.innerText += '\n\n' + scriptText;
  }

  closeValuationModal();

  if (typeof switchSubsystem === 'function') {
    switchSubsystem('copywriting');
  }

  if (typeof showToast === 'function') {
    showToast('⚡ Đã chèn luận điểm định giá vào bài viết Phân Hệ 02!', '🎯');
  }
}

function printValuationCertificate() {
  const reportText = generateValuationReportText(lastValuationResult);
  const printModal = document.getElementById('printReportModal');
  const printBody = document.getElementById('printReportModalBody');

  if (printModal && printBody) {
    printBody.innerHTML = `<div style="font-family: monospace; font-size: 0.9rem; white-space: pre-wrap; line-height: 1.6; color: #000; background: #fff; padding: 1.5rem; border: 1px solid #ddd; border-radius: 6px;">${reportText}</div>`;
    closeValuationModal();
    printModal.style.display = 'flex';
  } else {
    window.print();
  }
}

