function closeV7SidebarMobile() {
  const sidebar = document.getElementById('v7Sidebar');
  const backdrop = document.getElementById('v7SidebarBackdrop');
  if (sidebar) sidebar.classList.remove('mobile-open');
  if (backdrop) backdrop.classList.remove('active');
}

function toggleV7Sidebar() {
  const sidebar = document.getElementById('v7Sidebar');
  const backdrop = document.getElementById('v7SidebarBackdrop');
  if (!sidebar) return;
  if (window.innerWidth <= 900) {
    const isOpen = sidebar.classList.contains('mobile-open');
    if (isOpen) {
      sidebar.classList.remove('mobile-open');
      if (backdrop) backdrop.classList.remove('active');
    } else {
      sidebar.classList.add('mobile-open');
      if (backdrop) backdrop.classList.add('active');
    }
  } else {
    sidebar.classList.toggle('collapsed');
  }
}

let v7IsLightMode = false;
function toggleV7Theme() {
  v7IsLightMode = !v7IsLightMode;
  const dot = typeof document !== 'undefined' ? document.getElementById('v7ThemeSwitchDot') : null;
  if (dot) {
    dot.style.left = v7IsLightMode ? '16px' : '2px';
  }
  if (typeof document !== 'undefined' && document.body) {
    if (v7IsLightMode) {
      document.body.classList.add('light-theme');
      document.body.style.filter = 'none';
    } else {
      document.body.classList.remove('light-theme');
      document.body.style.filter = 'none';
    }
  }
  if (typeof localStorage !== 'undefined') {
    try {
      localStorage.setItem('contentsodo_theme', v7IsLightMode ? 'light' : 'dark');
    } catch (e) {}
  }
  if (typeof showToast === 'function') {
    showToast(v7IsLightMode ? '☀️ Đã chuyển sang giao diện Sáng!' : '🌙 Đã chuyển sang giao diện Tối!', '✨');
  }
}

function initV7Theme() {
  try {
    if (typeof localStorage !== 'undefined' && localStorage.getItem('contentsodo_theme') === 'light') {
      v7IsLightMode = true;
      if (typeof document !== 'undefined' && document.body) {
        document.body.classList.add('light-theme');
        document.body.style.filter = 'none';
      }
      const dot = typeof document !== 'undefined' ? document.getElementById('v7ThemeSwitchDot') : null;
      if (dot) {
        dot.style.left = '16px';
      }
    }
  } catch (e) {}
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initV7Theme);
  } else {
    initV7Theme();
  }
}

