let lastBienTauResult = '';
function runBienTauAnalysis() {
  const inputEl = document.getElementById('bienTauInputText');
  const resultBox = document.getElementById('bienTauResultBox');
  const diagEl = document.getElementById('bienTauDiagnoseText');
  const outputEl = document.getElementById('bienTauOutputContent');

  const text = inputEl ? inputEl.value.trim() : '';
  if (!text) {
    if (typeof showToast === 'function') showToast('Vui lòng dán bài đăng cũ để biến tấu!', '⚠️');
    return;
  }

  const lines = text.split('\n').filter(Boolean);
  const words = text.split(/\s+/).filter(Boolean).length;

  let diagnosis = '⚠️ Điểm nghẽn bài cũ: ';
  if (words < 50) diagnosis += 'Bài quá ngắn, thiếu số liệu diện tích và kết cấu. ';
  if (text.toLowerCase().includes('inbox') || text.toLowerCase().includes('ib')) diagnosis += 'Bị bóp tương tác do bắt khách inbox giấu giá. ';
  if (!/[0-9]/.test(lines[0] || '')) diagnosis += 'Tiêu đề thiếu con số kích thích thị giác. ';
  if (!text.includes('09') && !text.includes('08') && !text.includes('07') && !text.includes('03')) diagnosis += 'Thiếu số điện thoại liên hệ trực tiếp. ';

  if (diagEl) diagEl.textContent = diagnosis;

  const version1 = '🔥 [BẢN 1: GIẬT TÍT KỊCH TÍNH - BẮT ĐÁY]\n' +
    'CHỦ NGỘP NỢ HẠ GẤP 600 TRIỆU BÁN NHÀ ĐẸP HIẾM CÓ!\n' +
    '📍 Vị trí đắc địa hẻm xe hơi thông thoáng, khu dân trí cao.\n' +
    '📐 Diện tích chuẩn phong thủy, sổ hồng riêng chính chủ công chứng trong ngày.\n' +
    '📞 Gọi ngay: 0909.xxx.xxx xem nhà 24/7 kẻo lỡ!';

  const version2 = '\n\n💰 [BẢN 2: DÒNG TIỀN CHO THUÊ - ĐẦU TƯ]\n' +
    'CƠ HỘI ĐẦU TƯ SINH LỜI: BÁN NHÀ CÓ SẴN HỢP ĐỒNG THUÊ 18 TRIỆU/THÁNG!\n' +
    '📍 Tọa lạc tại khu phố sầm uất, nhu cầu thuê luôn kín phòng.\n' +
    '💰 Mua là có ngay dòng tiền thụ động chảy về tài khoản mỗi tháng.\n' +
    '📞 Liên hệ trực tiếp: 0909.xxx.xxx để nhận bảng phân tích ROI!';

  const version3 = '\n\n🏡 [BẢN 3: AN CƯ ẤM CÚNG - GIA ĐÌNH]\n' +
    'TỔ ẤM BÌNH AN ĐÓN TẾT: NHÀ ĐẸP LUNG LIN DỌN VÀO Ở NGAY!\n' +
    '📍 Gần trường học, chợ, công viên rợp bóng mát, an ninh tuyệt đối.\n' +
    '🏢 Kết cấu BTCT kiên cố, phòng ngủ đón sáng tự nhiên, giếng trời thoáng đãng.\n' +
    '📞 Gọi em xem nhà thực tế: 0909.xxx.xxx (Chủ thiện chí bớt lộc may mắn)!';

  lastBienTauResult = version1 + version2 + version3;
  if (outputEl) outputEl.textContent = lastBienTauResult;
  if (resultBox) resultBox.style.display = 'flex';
  if (typeof showToast === 'function') showToast('⚡ Đã hoàn thành chẩn đoán & biến tấu 3 phiên bản!', '✨');
}

