// ========================================================
// PWA (PROGRESSIVE WEB APP) MANAGER
// Tối ưu hóa 100% cho Vercel Edge CDN & GitHub Actions
// ========================================================
let deferredPwaPrompt = null;
const STORAGE_KEY_PWA_DISMISSED = 'pwa_install_banner_dismissed_until';

function registerServiceWorker() {
  if (typeof window === 'undefined') return;

  // Lắng nghe sự kiện cài đặt PWA từ trình duyệt
  window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPwaPrompt = e;
    console.log('[PWA] beforeinstallprompt event captured');

    const topBtn = document.getElementById('btnPwaInstall');
    if (topBtn) topBtn.style.display = 'inline-flex';

    // Hiển thị banner nếu chưa bị từ chối gần đây
    checkAndShowPwaBanner();
  });

  // Sự kiện khi app đã được cài đặt thành công
  window.addEventListener('appinstalled', () => {
    console.log('[PWA] Ứng dụng Content Sổ Đỏ đã được cài đặt thành công!');
    deferredPwaPrompt = null;
    hidePwaBanner();
    if (typeof showToast === 'function') {
      showToast('🎉 Đã cài đặt Content Sổ Đỏ vào màn hình chính!', '📱');
    }
  });

  // Đăng ký Service Worker
  if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
      navigator.serviceWorker.register('./sw.js')
        .then((reg) => {
          console.log('[PWA] ServiceWorker registered with scope:', reg.scope);

          // Lắng nghe bản cập nhật mới khi deploy Vercel
          reg.onupdatefound = () => {
            const installingWorker = reg.installing;
            if (installingWorker) {
              installingWorker.onstatechange = () => {
                if (installingWorker.state === 'installed' && navigator.serviceWorker.controller) {
                  if (typeof showToast === 'function') {
                    showToast('✨ Đã có bản cập nhật mới! Tải lại trang để áp dụng.', '🔄');
                  }
                }
              };
            }
          };
        })
        .catch((err) => {
          console.warn('[PWA] ServiceWorker registration failed:', err);
        });
    });
  }

  // Khởi tạo hiển thị nút PWA trên mobile nếu đang chạy trên trình duyệt web
  initPwaUiState();
}

function isPwaStandaloneMode() {
  if (typeof window === 'undefined') return false;
  return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) ||
         (window.navigator && window.navigator.standalone === true);
}

function initPwaUiState() {
  if (isPwaStandaloneMode()) {
    // Đang chạy bên trong PWA App đã cài
    const banner = document.getElementById('pwaInstallBanner');
    if (banner) banner.style.display = 'none';
    const topBtn = document.getElementById('btnPwaInstall');
    if (topBtn) topBtn.style.display = 'none';
    return;
  }

  // Tự động kiểm tra sau 2.5s khi mở trang
  setTimeout(() => {
    checkAndShowPwaBanner();
  }, 2500);
}

function checkAndShowPwaBanner() {
  if (isPwaStandaloneMode()) return;

  const now = Date.now();
  if (typeof localStorage !== 'undefined') {
    try {
      const dismissedUntil = parseInt(localStorage.getItem(STORAGE_KEY_PWA_DISMISSED) || '0', 10);
      if (now < dismissedUntil) return; // Chưa hết thời gian hoãn
    } catch (e) {}
  }

  const banner = document.getElementById('pwaInstallBanner');
  if (banner) {
    banner.style.display = 'block';
  }
}

function hidePwaBanner() {
  const banner = document.getElementById('pwaInstallBanner');
  if (banner) {
    banner.style.display = 'none';
  }
}

function dismissPwaBanner() {
  hidePwaBanner();
  // Hoãn nhắc lại trong 2 ngày (48 giờ)
  if (typeof localStorage !== 'undefined') {
    try {
      const twoDaysLater = Date.now() + (48 * 60 * 60 * 1000);
      localStorage.setItem(STORAGE_KEY_PWA_DISMISSED, String(twoDaysLater));
    } catch (e) {}
  }
}

function openPwaInstallGuideModal() {
  const modal = document.getElementById('pwaInstallGuideModal');
  if (!modal) return;
  modal.style.display = 'flex';

  const isIOS = (typeof navigator !== 'undefined') && /iPad|iPhone|iPod/.test(navigator.userAgent || '');
  if (isIOS) {
    switchPwaGuideTab('ios');
  } else {
    switchPwaGuideTab('android');
  }

  const directBox = document.getElementById('pwaDirectInstallBox');
  if (directBox) {
    directBox.style.display = deferredPwaPrompt ? 'block' : 'none';
  }
}

function closePwaInstallGuideModal() {
  const modal = document.getElementById('pwaInstallGuideModal');
  if (modal) modal.style.display = 'none';
}

function switchPwaGuideTab(tabKey) {
  ['ios', 'android', 'pc'].forEach(k => {
    const btn = document.getElementById('pwaTabBtn' + k.charAt(0).toUpperCase() + k.slice(1));
    const panel = document.getElementById('pwaPanel' + k.charAt(0).toUpperCase() + k.slice(1));
    if (btn) {
      if (k === tabKey) btn.classList.add('active');
      else btn.classList.remove('active');
    }
    if (panel) {
      panel.style.display = (k === tabKey) ? 'block' : 'none';
    }
  });
}

function triggerDirectPwaInstall() {
  if (deferredPwaPrompt) {
    deferredPwaPrompt.prompt();
    deferredPwaPrompt.userChoice.then((choiceResult) => {
      if (choiceResult.outcome === 'accepted') {
        hidePwaBanner();
        closePwaInstallGuideModal();
        if (typeof showToast === 'function') {
          showToast('🎉 Đang tiến hành cài đặt ứng dụng!', '📲');
        }
      }
      deferredPwaPrompt = null;
    });
  }
}

function promptPwaInstall() {
  if (isPwaStandaloneMode()) {
    if (typeof showToast === 'function') {
      showToast('✅ Bạn đang sử dụng ứng dụng Content Sổ Đỏ chính thức!', '💎');
    }
    return;
  }

  if (deferredPwaPrompt) {
    deferredPwaPrompt.prompt();
    deferredPwaPrompt.userChoice.then((choiceResult) => {
      if (choiceResult.outcome === 'accepted') {
        console.log('[PWA] Người dùng đã đồng ý cài đặt');
        hidePwaBanner();
        closePwaInstallGuideModal();
        if (typeof showToast === 'function') {
          showToast('🎉 Đang tiến hành cài đặt ứng dụng!', '📲');
        }
      } else {
        console.log('[PWA] Người dùng đã từ chối cài đặt');
      }
      deferredPwaPrompt = null;
    });
  } else {
    // Mở Modal Hướng dẫn trực quan chi tiết cho từng thiết bị
    openPwaInstallGuideModal();
  }
}

